(411, '_transient_neve_dash_useful_plugins', '{\"optimole-wp\":{\"banner\":\"https:\\/\\/ps.w.org\\/optimole-wp\\/assets\\/banner-772x250.jpg?rev=2001004\",\"name\":\"Image Optimization by Optimole \\u2013 Lazy Load, CDN, Convert to WebP & AVIF\",\"description\":\"Comprime, optimiza y sirve autom\\u00e1ticamente im\\u00e1genes escaladas junto con WebP de nueva generaci\\u00f3n, todo desde la CDN de CloudFront. Carga diferida incluida \\u26a1\",\"version\":\"3.11.0\",\"author\":\"Optimole\",\"cta\":\"install\",\"path\":\"optimole-wp\\/optimole-wp.php\",\"activate\":\"plugins.php?action=activate&plugin=optimole-wp%2Foptimole-wp.php&plugin_status=all&paged=1&_wpnonce=c925da0be2\",\"deactivate\":\"plugins.php?action=deactivate&plugin=optimole-wp%2Foptimole-wp.php&plugin_status=all&paged=1&_wpnonce=794be5a5fc\",\"network\":false},\"wp-landing-kit\":{\"banner\":\"http:\\/\\/localhost\\/banco-actual\\/wp-content\\/themes\\/neve\\/assets\\/img\\/dashboard\\/wp-landing.jpg\",\"name\":\"WP Landing Kit\",\"description\":\"Turn WordPress into a landing page powerhouse with Landing Kit. Map domains to pages or any other published resource.\",\"author\":\"Themeisle\",\"cta\":\"external\",\"url\":\"https:\\/\\/wplandingkit.com\\/?utm_source=wpadmin&utm_medium=nevedashboard&utm_campaign=recommendedplugins&utm_content=wplandingkitcom\",\"premium\":true},\"otter-blocks\":{\"banner\":\"https:\\/\\/ps.w.org\\/otter-blocks\\/assets\\/banner-772x250.png?rev=2019296\",\"name\":\"Otter Blocks \\u2013 Gutenberg Blocks, Page Builder for Gutenberg Editor & FSE\",\"description\":\"Otter offers dynamic Gutenberg blocks for the WordPress block editor. Craft beautiful posts & pages using post blocks, post grids & WordPress  \\u2026\",\"version\":\"2.4.1\",\"author\":\"ThemeIsle\",\"cta\":\"install\",\"path\":\"otter-blocks\\/otter-blocks.php\",\"activate\":\"plugins.php?action=activate&plugin=otter-blocks%2Fotter-blocks.php&plugin_status=all&paged=1&_wpnonce=56c19e7e83\",\"deactivate\":\"plugins.php?action=deactivate&plugin=otter-blocks%2Fotter-blocks.php&plugin_status=all&paged=1&_wpnonce=6d3b52c45a\",\"network\":false},\"wp-cloudflare-page-cache\":{\"banner\":\"https:\\/\\/ps.w.org\\/wp-cloudflare-page-cache\\/assets\\/banner-772x250.jpeg?rev=2691373\",\"name\":\"Super Page Cache for Cloudflare\",\"description\":\"Speed up a WordPress website by caching your webpages onto global CDN using any Cloudflare Plan.\",\"version\":\"4.7.5\",\"author\":\"Optimole\",\"cta\":\"install\",\"path\":\"wp-cloudflare-page-cache\\/wp-cloudflare-super-page-cache.php\",\"activate\":\"plugins.php?action=activate&plugin=wp-cloudflare-page-cache%2Fwp-cloudflare-super-page-cache.php&plugin_status=all&paged=1&_wpnonce=68f15b695c\",\"deactivate\":\"plugins.php?action=deactivate&plugin=wp-cloudflare-page-cache%2Fwp-cloudflare-super-page-cache.php&plugin_status=all&paged=1&_wpnonce=38197ab463\",\"network\":false},\"templates-patterns-collection\":{\"banner\":\"https:\\/\\/ps.w.org\\/templates-patterns-collection\\/assets\\/banner-772x250.jpg?rev=2348265\",\"name\":\"Cloud Templates & Patterns collection\",\"description\":\"Un servicio basado en la nube con m\\u00e1s de 100 plantillas y sitios de inicio para el tema Neve.\",\"version\":\"1.2.5\",\"author\":\"ThemeIsle\",\"cta\":\"install\",\"path\":\"templates-patterns-collection\\/templates-patterns-collection.php\",\"activate\":\"plugins.php?action=activate&plugin=templates-patterns-collection%2Ftemplates-patterns-collection.php&plugin_status=all&paged=1&_wpnonce=480cb44108\",\"deactivate\":\"plugins.php?action=deactivate&plugin=templates-patterns-collection%2Ftemplates-patterns-collection.php&plugin_status=all&paged=1&_wpnonce=ce2ca089b3\",\"network\":false},\"themeisle-companion\":{\"banner\":\"https:\\/\\/ps.w.org\\/themeisle-companion\\/assets\\/banner-772x250.png?rev=2891367\",\"name\":\"Orbit Fox by ThemeIsle\",\"description\":\"This swiss-knife plugin comes with a quality template library, menu\\/sharing icons, Elementor\\/BeaverBuilder page builder widgets and many more.\",\"version\":\"2.10.26\",\"author\":\"Themeisle\",\"cta\":\"install\",\"path\":\"themeisle-companion\\/themeisle-companion.php\",\"activate\":\"plugins.php?action=activate&plugin=themeisle-companion%2Fthemeisle-companion.php&plugin_status=all&paged=1&_wpnonce=84c3a59474\",\"deactivate\":\"plugins.php?action=deactivate&plugin=themeisle-companion%2Fthemeisle-companion.php&plugin_status=all&paged=1&_wpnonce=d820354f9d\",\"network\":false},\"translatepress-multilingual\":{\"banner\":\"https:\\/\\/ps.w.org\\/translatepress-multilingual\\/assets\\/banner-772x250.png?rev=2312348\",\"name\":\"Translate Multilingual sites \\u2013 TranslatePress\",\"description\":\"Traduce todo tu sitio directamente desde la vista p\\u00fablica y hazlo multiling\\u00fce. Compatibilidad total con WooCommerce y con maquetadores de p\\u00e1ginas, adem\\u00e1s de integraci\\u00f3n con Google Translate.\",\"version\":\"2.6.6\",\"author\":\"Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban\",\"cta\":\"install\",\"path\":\"translatepress-multilingual\\/index.php\",\"activate\":\"plugins.php?action=activate&plugin=translatepress-multilingual%2Findex.php&plugin_status=all&paged=1&_wpnonce=69d2b7e2e6\",\"deactivate\":\"plugins.php?action=deactivate&plugin=translatepress-multilingual%2Findex.php&plugin_status=all&paged=1&_wpnonce=d0b937b22e\",\"network\":false},\"amp\":{\"banner\":\"https:\\/\\/ps.w.org\\/amp\\/assets\\/banner-772x250.png?rev=2527602\",\"name\":\"AMP\",\"description\":\"Una ruta m\\u00e1s sencilla para una fant\\u00e1stica experiencia de p\\u00e1gina para todos. Funciona con AMP.\",\"version\":\"2.5.0\",\"author\":\"AMP Project Contributors\",\"cta\":\"install\",\"path\":\"amp\\/amp.php\",\"activate\":\"plugins.php?action=activate&plugin=amp%2Famp.php&plugin_status=all&paged=1&_wpnonce=9480a608a2\",\"deactivate\":\"plugins.php?action=deactivate&plugin=amp%2Famp.php&plugin_status=all&paged=1&_wpnonce=5863090e0c\",\"network\":false}}', 'yes'),
