(8989, '_transient_otter_blocks_pro_patterns_preview_v1', 'a:146:{i:0;a:9:{s:4:\"slug\";s:17:\"blog-minimal-grid\";s:5:\"title\";s:17:\"Blog Minimal Grid\";s:10:\"categories\";a:2:{i:0;s:12:\"otter-blocks\";i:1;s:4:\"blog\";}s:11:\"description\";s:149:\"Minimal blog post grid with hairline dividers, category labels and read times for a product engineering journal, clean text-only three-column layout.\";s:8:\"keywords\";a:1:{i:0;s:13:\"style:classic\";}s:4:\"tone\";s:5:\"light\";s:6:\"layout\";s:6:\"cols-3\";s:8:\"elements\";a:0:{}s:10:\"screenshot\";s:90:\"https://api.themeisle.com/sites/wp-content/uploads/sites/664/2026/06/blog-minimal-grid.jpg\";}i:1;a:9:{s:4:\"slug\";s:18:\"blog-magazine-hero\";s:5:\"title\";s:18:\"Blog Magazine Hero\";s:10:\"categories\";a:2:{i:0;s:12:\"otter-blocks\";i:1;s:4:\"blog\";}s:11:\"description\";s:140:\"Dark magazine blog layout with a full-width featured cover story hero and a three-column grid of bordered article cards, news and editorial.\";s:8:\"keywords\";a:1:{i:0;s:13:\"style:classic\";}s:4:\"tone\";s:4:\"dark\";s:6:\"layout\";s:6:\"cols-3\";s:8:\"elements\";a:1:{i:0;s:5:\"image\";}s:10:\"screenshot\";s:91:\"https://api.themeisle.com/sites/wp-content/uploads/sites/664/2026/06/blog-magazine-hero.jpg\";}i:2;a:9:{s:4:\"slug\";s:17:\"blog-poster-cards\";s:5:\"title\";s:16:\"Poster Type Blog\";s:10:\"categories\";a:2:{i:0;s:12:\"otter-blocks\";i:1;s:4:\"blog\";}s:11:\"description\";s:152:\"Bold poster-style blog post grid with thick borders, uppercase headlines and amber neo-brutalist cards for a design studio journal, three-column layout.\";s:8:\"keywords\";a:1:{i:0;s:12:\"style:poster\";}s:4:\"tone\";s:5:\"light\";s:6:\"layout\";s:6:\"cols-3\";s:8:\"elements\";a:1:{i:0;s:5:\"image\";}s:10:\"screenshot\";s:90:\"https://api.themeisle.com/sites/wp-content/uploads/sites/664/2026/06/blog-poster-cards.jpg\";}i:3;a:9:{s:4:\"slug\";s:16:\"blog-glass-cards\";s:5:\"title\";s:20:\"Cinematic Glass Blog\";s:10:\"categories\";a:2:{i:0;s:12:\"ott