ull,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-d3c03c4c\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-d3c03c4c\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ef39620e\",\"margin\":{\"top\":\"40px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ef39620e\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>Tasas de Interés de Cuentas de Ahorro / Personas Naturales</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table {\"hasFixedLayout\":true,\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table class=\"has-fixed-layout\"><tbody><tr><td> <strong>A la vista</strong></td><td>0,50 <strong>CUP</strong></td><td>0,25 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 3 Meses</strong></td><td>2,00 <strong>CUP</strong></td><td>0,50 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 6 Meses</strong></td><td>2,50 <strong>CUP</strong></td><td>0,75 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 12 Meses</strong></td><td>4,00 <strong>CUP</strong></td><td>1,00 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 24 Meses</strong></td><td>5,00 <strong>CUP</strong></td><td>1,25 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 36 Meses</strong></td><td>6,00 <strong>CUP</strong></td><td>1,75 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 48 meses</strong></td><td>6,25 <strong>CUP</strong></td><td>1,80 <strong>USD</strong></td></tr><tr><td><strong>Plazos de: 60 Meses</strong></td><td>6,50 <strong>CUP</strong></td><td>1,90 <strong>USD</strong></td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph -->\n<p><strong>Observaciones:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>CUP</strong>: pesos cubanos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>USD</strong>: dólares estadounidenses.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En las cuentas <strong>A la Vista</strong> se comienza a ganar el interés a partir de <strong>200,00 CUP </strong>o<strong> USD</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>La tasa de interés de las cuentas de <strong>Formación de Fondos</strong> es del <strong>2.0 % anual</strong>, bonificación del <strong>2.0 % adicional</strong> si no realiza extracciones en un año y de <strong>1.0 % adicional</strong> si no realiza extracciones durante <strong>3 años</strong> consecutivos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En los <strong>Depósitos a Plazos Fijos</strong> se pagan solo al vencimiento de los plazos pactados. Excepto el de <strong>72 meses</strong> en CUP.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>En los Certificados a Término la forma de pago es:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><u>Plazos de 3, 6 y 12 meses</u></strong>: antes de haber transcurrido el <strong>50 % del término pactado</strong>, se paga <strong>sólo el principal</strong> y pierde el derecho al cobro del interés; si ha transcurrido el <strong>50 % o más del término pactado</strong>, se paga <strong>el principal y el 50 % del interés acumulado hasta el cierre del día anterior</strong>; si ha transcurrido el <strong>100 % del término pactado</strong>, se paga <strong>el principal y el 100 % del interés acumulado hasta el cierre</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><u>Plazos de 24, 36, 48 y 60 meses</u></strong>: antes de haber transcurrido el <strong>25 % del término pactado</strong>, se le paga <strong>sólo el principal</strong> y pierde el derecho al cobro del interés; si ha transcurrido el <strong>25 % o más del término pactado</strong>, se paga <strong>el principal y el 50 % del interés acumulado hasta el cierre del día anterior</strong>; si ha transcurrido el <strong>100 % del término pactado</strong>, se le paga <strong>el principal y el 100 % del interés</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><tbody><tr><td colspan=\"3\"><strong>Certificados a Término</strong> <strong>&nbsp;</strong></td></tr><tr><td><strong>Plazos</strong></td><td><strong>CUP</strong></td><td><strong>USD</strong></td></tr><tr><td><strong>3 Meses</strong><strong></strong></td><td>2,00</td><td>0,50</td></tr><tr><td><strong>6 Meses</strong><strong></strong></td><td>2,50</td><td>0,75</td></tr><tr><td><strong>12 Meses</strong><strong></strong></td><td>4,00</td><td>1,00</td></tr><tr><td><strong>24 Meses</strong><strong></strong></td><td>5,00</td><td>1,25</td></tr><tr><td><strong>36 Meses</strong><strong></strong></td><td>6,00</td><td>1,75</td></tr><tr><td><strong>48 Meses</strong></td><td>6,25</td><td>1,80</td></tr><tr><td><strong>60 Meses</strong><strong></strong></td><td>6,50</td><td>1,90</td></tr></tbody></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Tasas de Interés de Cuentas de Ahorro  Personas Naturales', '', 'inherit', 'closed', 'closed', '', '2139-revision-v1', '', '', '2024-06-19 14:40:30', '2024-06-19 14:40:30', '', 2139, 'http://localhost/banco-actual/?p=2148', 0, 'revision', '', 0),
