s/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Tarifas, Comisiones y Otros cargos</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"40px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7969f93c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7969f93c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El <strong>Banco Metropolitano</strong> aplica las <strong>tasas y comisiones</strong> para los servicios que ofrecen las sucursales a las <strong>Representaciones Diplomáticas</strong> y <strong>Consulares</strong>, <strong>Entidades Comerciales Privadas</strong>, <strong>Cubanas</strong>, <strong>Extranjeras </strong>o<strong> Mixtas, </strong>a <strong>ciudadanos extranjeros</strong> radicados en Cuba, a <strong>turistas</strong> y a otras <strong>personas naturales</strong> que sean <strong>titulares </strong>de<strong> cuentas bancarias</strong> en <strong>pesos cubanos</strong> (CUP), en <strong>monedas libremente convertibles</strong> (MLC) u otras que requieran de la prestación de un servicio determinado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>precios</strong> de las <strong>tarifas</strong>, <strong>comisiones</strong> y <strong>otros cargos</strong> se <strong>reconocen </strong>en<strong> CUP</strong>,con independencia de la moneda en que se ejecute el pago.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;<strong>Condiciones generales:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El banco se reserva el derecho de cargar comisiones por servicios bancarios no contemplados en la relación que aparecen a continuación y, de realizar las modificaciones sin previo aviso.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los servicios que requieran el uso adicional de las comunicaciones, se le sumarán a su comisión inicial.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos rehusados y/o reclamados por otras contrapartes o bancos serán a cargo del cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos que se originan en el exterior y se exijan por los bancos corresponsales, se cargan a la cuenta del ordenante.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-54e9a28c\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-54e9a28c\" class=\"wp-block-themeisle-blocks-advanced-columns has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-6727c3e6\",\"margin\":{\"top\":\"0px\",\"right\":\"20px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-6727c3e6\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-f9333d82\",\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"titleBackground\":\"var(\\u002d\\u002dnv-site-bg)\",\"alwaysOpen\":false,\"activeTitleColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"activeTitleBackground\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"is-style-default  has-light-active-title-bg has-light-title-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-f9333d82\" class=\"wp-block-themeisle-blocks-accordion exclusive is-style-default  has-light-active-title-bg has-light-title-bg\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de Cuentas Bancarias\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio de Cuentas Bancarias</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Apertura de cuentas</strong><br>Porciento:<br>Mínimo:<br>Máximo: <strong>Libre</strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes del mes de apertura. Excepto las cuentas en USD que pueden variar por la tasa de cambio<br>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes los tres meses de apertura. Excepto las en USD que puedan variar por la tasa de cambio<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Deterioro de libreta de ahorro (se excluyen los modelos de depósito a plazo fijo y certificado de depósito)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Extravío de Libreta de Ahorro<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas adicionales de Cuentas Corrientes (persona natural)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas y Certificación de Cuentas (Personas Naturales con Cuentas de Ahorro)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>100.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de Saldos a Clientes. (Cuenta de ahorro o corriente, por cada cuenta que solicite el titular. Se incluye la certificación de cobro de jubilación o pensión)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de adeudos a clientes<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>10.00</strong></strong></strong></td></tr></tbody></table></figure>\n<!-- /wp:table --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de Cheques y Giros\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio de Cheques y Giros</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Apertura de cuentas</strong><br>Porciento:<br>Mínimo:<br>Máximo: <strong>Libre</strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes del mes de apertura. Excepto las cuentas en USD que pueden variar por la tasa de cambio<br>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes los tres meses de apertura. Excepto las en USD que puedan variar por la tasa de cambio<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Deterioro de libreta de ahorro (se excluyen los modelos de depósito a plazo fijo y certificado de depósito)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Extravío de Libreta de Ahorro<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas adicionales de Cuentas Corrientes (persona natural)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas y Certificación de Cuentas (Personas Naturales con Cuentas de Ahorro)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>100.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de Saldos a Clientes. (Cuenta de ahorro o corriente, por cada cuenta que solicite el titular. Se incluye la certificación de cobro de jubilación o pensión)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de adeudos a clientes<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>10.00</strong></strong></strong></td></tr></tbody></table></figure>\n<!-- /wp:table --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-19d3fd2a\",\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-19d3fd2a\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-952fdf82\",\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"titleBackground\":\"var(\\u002d\\u002dnv-site-bg)\",\"alwaysOpen\":false,\"activeTitleColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"activeTitleBackground\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"is-style-default  has-light-active-title-bg has-light-title-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-952fdf82\" class=\"wp-block-themeisle-blocks-accordion exclusive is-style-default  has-light-active-title-bg has-light-title-bg\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de \\u003cstrong\\u003eTransferencias\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio de <strong>Transferencias</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Transferencias enviadas entre cuentas de un mismo cliente y entre clientes del Banco Metropolitano</strong><br>Porciento:<br>Mínimo:<br>Máximo: <strong>Libre</strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias enviadas para depositar en cuenta de beneficiarios de otros bancos en el país<br>Porciento: 0.25<br>Mínimo: 20.00<br>Máximo: <strong><strong>50.00</strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencia enviadapara pagar en efectivo a beneficiarios de otros bancos<br><strong>Porciento: 0.25<br>Mínimo: 40.00<br>Máximo: <strong><strong>100.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias periódicas por convenio con el titular de la cuenta (standing order)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Depósitos para la cuenta del Plan Materno Infantil y la lucha contra el cáncer<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>Libre</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias <strong>recibidas </strong>de Bancos extranjeros para acreditar en cuenta de Personas Naturales y Personas Jurídicas con gastos compartidos o a pagar del beneficiario<br><strong>Porciento: 0.50<br>Mínimo: 10.00<br>Máximo: <strong><strong>150.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias <strong>recibidas </strong>de Bancos cubanos para acreditar en cuenta de Personas Naturales y Personas Jurídicas con gastos por el ordenante<br><strong><strong>Porciento: 0.50<br>Mínimo: 10.00<br>Máximo: <strong><strong>100.00</strong></strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias <strong>recibidas </strong>de bancos extranjeros para pagar en efectivo<br><strong><strong><strong>Porciento: 0.50<br>Mínimo: 20.00<br>Máximo: <strong><strong>300.00</strong></strong></strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Transferencias recibidas de bancos extranjeros para pagar a través de otro banco del país<br><strong><strong><strong><strong>Porciento: 0.50<br>Mínimo: 10.00<br>Máximo: <strong><strong>150.00</strong></strong></strong></strong></strong></strong></td></tr></tbody></table></figure>\n<!-- /wp:table --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de Cheques y Giros\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio de Cheques y Giros</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Apertura de cuentas</strong><br>Porciento:<br>Mínimo:<br>Máximo: <strong>Libre</strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes del mes de apertura. Excepto las cuentas en USD que pueden variar por la tasa de cambio<br>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes los tres meses de apertura. Excepto las en USD que puedan variar por la tasa de cambio<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Deterioro de libreta de ahorro (se excluyen los modelos de depósito a plazo fijo y certificado de depósito)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Extravío de Libreta de Ahorro<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas adicionales de Cuentas Corrientes (persona natural)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas y Certificación de Cuentas (Personas Naturales con Cuentas de Ahorro)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>100.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de Saldos a Clientes. (Cuenta de ahorro o corriente, por cada cuenta que solicite el titular. Se incluye la certificación de cobro de jubilación o pensión)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de adeudos a clientes<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>10.00</strong></strong></strong></td></tr></tbody></table></figure>\n<!-- /wp:table --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Tarifas, Comisiones y Otros cargos', '', 'inherit', 'closed', 'closed', '', '2079-revision-v1', '', '', '2024-06-19 03:07:31', '2024-06-19 03:07:31', '', 2079, 'http://localhost/banco-actual/?p=2119', 0, 'revision', '', 0),
