anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Banca Móvil</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Electrónica</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-22441938\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-22441938\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-b6db265e\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-b6db265e\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Servicio del <strong>Banco Metropolitano</strong> que le permite, con el uso de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>, gestionar trámites bancarios y servicios de telecomunicaciones, realizar pagos en línea a través de <strong>códigos QR</strong> y le facilita las compras en las <strong>tiendas virtuales</strong>, le permite realizar las transacciones y consultas en tiempo real.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para hacer uso del servicio necesita:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Teléfono celular con sistema operativo <strong>Android</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Teléfono celular con sistema operativo <strong>iOS</strong> mediante <strong>códigos USSD</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Una cuenta con <strong>tarjeta magnética</strong> RED emitida por el <strong>Banco Metropolitano</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tarjeta de <strong>TeleBANCA</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tener instaladas en el teléfono celular las aplicaciones <strong>Transfermóvil</strong> o <strong>EnZona</strong>, disponibles en los sitios web <strong>APKLIS</strong>, <strong>XETID</strong> y de <strong>ETECSA</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Después de instalar una de las aplicaciones en el teléfono celular, debe <strong>REGISTRAR</strong> sus datos por <strong>única vez</strong>, siguiendo los pasos indicados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:shortcode -->\n[wpdm_package id=\'2450\']\n<!-- /wp:shortcode -->', 'Banca MÓVIL', '', 'inherit', 'closed', 'closed', '', '1088-revision-v1', '', '', '2024-06-24 17:13:36', '2024-06-24 17:13:36', '', 1088, 'http://localhost/banco-actual/?p=2451', 0, 'revision', '', 0),
