et\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Tarifas, Comisiones y Otros cargos</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"40px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7969f93c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7969f93c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El <strong>Banco Metropolitano</strong> aplica las <strong>tasas y comisiones</strong> para los servicios que ofrecen las sucursales a las <strong>Representaciones Diplomáticas</strong> y <strong>Consulares</strong>, <strong>Entidades Comerciales Privadas</strong>, <strong>Cubanas</strong>, <strong>Extranjeras </strong>o<strong> Mixtas, </strong>a <strong>ciudadanos extranjeros</strong> radicados en Cuba, a <strong>turistas</strong> y a otras <strong>personas naturales</strong> que sean <strong>titulares </strong>de<strong> cuentas bancarias</strong> en <strong>pesos cubanos</strong> (CUP), en <strong>monedas libremente convertibles</strong> (MLC) u otras que requieran de la prestación de un servicio determinado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>precios</strong> de las <strong>tarifas</strong>, <strong>comisiones</strong> y <strong>otros cargos</strong> se <strong>reconocen </strong>en<strong> CUP</strong>,con independencia de la moneda en que se ejecute el pago.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;<strong>Condiciones generales:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El banco se reserva el derecho de cargar comisiones por servicios bancarios no contemplados en la relación que aparecen a continuación y, de realizar las modificaciones sin previo aviso.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los servicios que requieran el uso adicional de las comunicaciones, se le sumarán a su comisión inicial.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos rehusados y/o reclamados por otras contrapartes o bancos serán a cargo del cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos que se originan en el exterior y se exijan por los bancos corresponsales, se cargan a la cuenta del ordenante.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-3e60e253\",\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-3e60e253\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eCuentas bancarias\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Cuentas bancarias</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-9ba2feb3\",\"tag\":\"h4\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-9ba2feb3\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-9ba2feb3\"><strong>Servicio de Apertura de cuentas</strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Porciento</strong>:</td><td><strong>Minimo</strong>:</td><td><strong>Maximo</strong>: Libre</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-642b1383\",\"tag\":\"h4\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-642b1383\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-642b1383\"><strong>Cierre de cuentas de todo tipo antes del mes de apertura. Excepto las cuentas en USD que pueden variar por la tasa de cambio</strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Porciento</strong>:</td><td><strong>Minimo</strong>:</td><td><strong>Maximo</strong>: 40.00</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-490cf350\",\"tag\":\"h4\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-490cf350\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-490cf350\"><strong>Cierre de cuentas de todo tipo antes los tres meses de apertura. Excepto las en USD que puedan variar por la tasa de cambio</strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Porciento</strong>:</td><td><strong>Minimo</strong>:</td><td><strong>Maximo</strong>: 20.00</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator --></div>\n<!-- /wp:group --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion -->\n\n<!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><thead><tr><th><strong>SERVICIO</strong></th><th><strong>%</strong></th><th><strong>MÍNIMO</strong></th><th><strong>MÁXIMO O CONSTANTE</strong></th></tr></thead><tbody><tr><td><strong>Cuentas bancarias</strong></td><td><strong>&nbsp;</strong></td><td><strong>&nbsp;</strong></td><td><strong>&nbsp;</strong></td></tr><tr><td>Deterioro de libreta de ahorro (se excluyen los modelos de depósito a plazo fijo y certificado de depósito)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>20.00</strong></td></tr><tr><td>Extravío de Libreta de Ahorro</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>40.00</strong></td></tr><tr><td>Estados de Cuentas adicionales de Cuentas Corrientes (persona natural)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>40.00</strong></td></tr><tr><td>Estados de Cuentas y Certificación de Cuentas (Personas Naturales con Cuentas de Ahorro)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>100.00</strong></td></tr><tr><td>Certificación de Saldos a Clientes. (Cuenta de ahorro o corriente, por cada cuenta que solicite el titular. Se incluye la certificación de cobro de jubilación o pensión)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>40.00</strong></td></tr><tr><td>Certificación de adeudos a clientes</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>10.00</strong></td></tr><tr><td><strong>Cheques y Giros</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Presentados para acreditar en cuenta a cargo nuestro o de otros bancos en el país</td><td><strong>&nbsp;</strong></td><td>&nbsp;</td><td>Libre</td></tr><tr><td>Presentados para acreditar en cuenta a cargo de bancos corresponsales en el extranjero</td><td>0,25</td><td>10.00</td><td>40.00</td></tr><tr><td>Presentados para cobrar en efectivo a cargo de otros bancos en Cuba</td><td>0.25</td><td><strong>10.00</strong></td><td><strong>35.00</strong></td></tr><tr><td>Presentados para cobrar en efectivo a cargo de bancos en el extranjero BCC</td><td>0.25</td><td><strong>20.00</strong><strong></strong></td><td>40.00</td></tr><tr><td>Garantía por devolución por posibles gastos del Banco corresponsal &nbsp;BM (si no lo devuelven se reintegra al cliente)</td><td>&nbsp;</td><td>&nbsp;</td><td>50.00</td></tr><tr><td>Emisión de Cheques de Gerencia</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>30.00</strong> &nbsp;</td></tr><tr><td>Cancelación, reintegro o extravío todo tipo de Cheques (Gerencia o Certificado)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>30.00</strong><strong></strong></td></tr><tr><td>Cheques devueltos por no suficiente fondos y por otras causas imputables al girador (persona natural) BCC</td><td>&nbsp;</td><td>&nbsp;</td><td>10.00</td></tr><tr><td>Tramitación para devoluciones de Cheques extranjeros</td><td>&nbsp;</td><td>&nbsp;</td><td>5.00</td></tr><tr><td><strong>Transferencias</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Transferencias enviadas entre cuentas de un mismo cliente y entre clientes del Banco Metropolitano</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr><tr><td>Transferencias enviadas para depositar en cuenta de beneficiarios de otros bancos en el país</td><td><strong>0.25</strong></td><td><strong>20.00</strong></td><td><strong>50.00</strong></td></tr><tr><td>Transferencia enviadapara pagar en efectivo a beneficiarios de otros bancos</td><td><strong>0.25</strong></td><td><strong>40.00</strong></td><td><strong>100.00</strong></td></tr><tr><td>Transferencias periódicas por convenio con el titular de la cuenta (standing order)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>20.00</strong><strong></strong></td></tr><tr><td>Depósitos para la cuenta del Plan Materno Infantil y la lucha contra el cáncer</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr><tr><td>Transferencias <strong>recibidas </strong>de Bancos extranjeros para acreditar en cuenta de Personas Naturales y Personas Jurídicas con gastos compartidos o a pagar del beneficiario</td><td>0.50</td><td><strong>10.00</strong><strong></strong></td><td>150.00</td></tr><tr><td>Transferencias <strong>recibidas </strong>de Bancos cubanos para acreditar en cuenta de Personas Naturales y Personas Jurídicas con gastos por el ordenante</td><td>0.50</td><td><strong>10.00</strong></td><td><strong>100.00</strong></td></tr><tr><td>Transferencias <strong>recibidas </strong>de bancos extranjeros para pagar en efectivo</td><td>0.50</td><td><strong>20.00</strong></td><td><strong>300.00</strong></td></tr><tr><td>Transferencias recibidas de bancos extranjeros para pagar a través de otro banco del país</td><td>0.50</td><td><strong>10.00</strong><strong></strong></td><td>150.00</td></tr><tr><td><strong>Otras comisiones por Transferencias Automáticas</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Transferencias de <strong>FINCIMEX</strong></td><td>Según convenio</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Transferencias recibidas de <strong>ANTEX</strong></td><td>Según convenio</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>Operaciones por cuenta de terceros</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Seguridad Social MINFAR- MININT (cada una-chequera)</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr><tr><td>Imposición de Fianzas</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>10.00</strong><strong></strong></td></tr><tr><td>Devolución de Fianzas</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;<strong>30.00</strong></td></tr><tr><td>Pagos a beneficiarios (cada uno)</td><td><strong>3.00</strong></td><td><strong>20.00</strong></td><td><strong>&nbsp;300.00</strong></td></tr><tr><td>Pagos a Herederos (se cobra sobre el saldo total a liquidar a los herederos, por cada cuenta que tenga el titular, antes de realizar la distribución a los herederos)</td><td><strong>2.00</strong></td><td><strong>&nbsp;10.00</strong></td><td><strong>200.00</strong></td></tr><tr><td>Pago de Comunidad Matrimonial</td><td><strong>3.00</strong></td><td><strong>&nbsp;</strong></td><td><strong>50.00</strong></td></tr><tr><td>Cobro de Comisión de estipendio a estudiantes</td><td>0.30</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Duplicado de títulos de propiedad (LGV) o contrato de arrendamiento con opción de compra (no incluye sellos de timbre)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>100.00</strong><strong></strong></td></tr><tr><td>Tramitación de giros postales Correos de Cuba (sucursal 259, Zanja y Belascoain)</td><td>0.50</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Administración de Fondos para Materiales de Construcción</td><td><strong>0.2</strong></td><td><strong>2.00</strong></td><td>&nbsp;</td></tr><tr><td>Emisión de títulos de propiedad (LGV) o contrato de arrendamiento con opción de compra (no incluye sellos de timbre)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>50.00</strong><strong></strong></td></tr><tr><td>Arrendamiento de Tierra (por cada pago que se realice)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>10.00</strong><strong></strong></td></tr><tr><td><strong>Servicios Varios</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Localización de documentos cargados o acreditados en cuentas imputables a clientes (por cada uno)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>60.00</strong><strong></strong></td></tr><tr><td>Certificación de operación realizada (una sola)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>10.00</strong><strong></strong></td></tr><tr><td>Certificación de operaciones realizadas (varias)</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>50.00</strong><strong></strong></td></tr><tr><td>Billetes de banco puestos al cobro por clientes (cada uno)</td><td><strong>0.40</strong></td><td><strong>20.00</strong></td><td>&nbsp;</td></tr><tr><td><strong>Servicios de Banca Electrónica</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>Emisión inicial de tarjeta o por renovación</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Personalización de tarjetas magnéticas por apertura de cuentas de ahorro a la vista</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr><tr><td>Pérdida, deterioro y desmagnetización de tarjeta o pérdida de PIN. Todos los productos <strong>(excepto subsidios,&nbsp;jubilados y pensionados)</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>20.00</td></tr><tr><td><strong>Tarjetas de Telebanca</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Contratación de Tarjetas de Telebanca</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr><tr><td><strong>Pérdida, deterioro y desmagnetización de tarjeta o PIN</strong></td><td><strong>&nbsp;</strong></td><td><strong>&nbsp;</strong><strong></strong></td><td><strong>Libre</strong></td></tr><tr><td><strong>Servicios de Información</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Solicitud de localización de cuentas y depósitos para herederos o beneficiarios en el mismo banco</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>20.00</strong><strong></strong></td></tr><tr><td>Solicitud de localización de cuentas y depósito para herederos o beneficiarios en otros bancos</td><td>&nbsp;</td><td>&nbsp;</td><td><strong>50.00</strong><strong></strong></td></tr><tr><td>Copia por extravío o deterioro de otros documentos no contemplados</td><td></td><td>&nbsp;</td><td><strong>60.00</strong><strong></strong></td></tr><tr><td><strong>Servicios de Comunicaciones</strong></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Correo electrónico</td><td>&nbsp;</td><td>&nbsp;</td><td>Libre</td></tr></tbody><tfoot><tr><td></td><td></td><td></td><td></td></tr></tfoot></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Tarifas, Comisiones y Otros cargos', '', 'inherit', 'closed', 'closed', '', '2079-revision-v1', '', '', '2024-06-19 02:35:29', '2024-06-19 02:35:29', '', 2079, 'http://localhost/banco-actual/?p=2095', 0, 'revision', '', 0),
