l,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a910e476\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a910e476\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-3eafa5d1\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-3eafa5d1\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-3eafa5d1\"><strong>Telebanca</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Es el canal por excelencia para atender y gestionar las inquietudes o reclamaciones relacionadas con los servicios asociados a la banca electrónica y los canales de pagos digitales con el empleo de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A través del <strong>centro de llamadas</strong> pueden ser atendidas las solicitudes de información general de los productos o servicios que ofrece el <strong>Banco Metropolitano</strong>, gestionar servicios bancarios, pagar la electricidad, la telefonía fija, el agua, impuestos, pagos de multas y contravenciones.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-4fb46f15\",\"columns\":3,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"60px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":\"-3px\",\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"dividerTopWidth\":100,\"dividerTopWidthTablet\":100,\"dividerTopWidthMobile\":100,\"dividerTopHeight\":100,\"dividerTopHeightTablet\":100,\"dividerTopHeightMobile\":100,\"dividerBottomWidth\":100,\"dividerBottomWidthTablet\":100,\"dividerBottomWidthMobile\":100,\"dividerBottomHeight\":100,\"dividerBottomHeightTablet\":100,\"dividerBottomHeightMobile\":100,\"align\":\"full\",\"className\":\"has-