io. </h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:themeisle-blocks/icon-list {\"id\":\"wp-block-themeisle-blocks-icon-list-5132cf4c\",\"defaultSize\":14,\"className\":\"is-style-horizontal\"} -->\n<div id=\"wp-block-themeisle-blocks-icon-list-5132cf4c\" class=\"wp-block-themeisle-blocks-icon-list is-style-horizontal\"><!-- wp:themeisle-blocks/icon-list-item {\"id\":\"wp-block-themeisle-blocks-icon-list-item-4c119fd7\",\"content\":\"\\u003cstrong\\u003e2 CHIYODA, CHIYODA-KU, TŌKYŌ-TO\\u003c/strong\\u003e\",\"library\":\"fontawesome\",\"iconPrefix\":\"fas\",\"icon\":\"map-marker-alt\"} -->\n<div id=\"wp-block-themeisle-blocks-icon-list-item-4c119fd7\" class=\"wp-block-themeisle-blocks-icon-list-item\"><i class=\"fas fa-map-marker-alt wp-block-themeisle-blocks-icon-list-item-icon\"></i><p class=\"wp-block-themeisle-blocks-icon-list-item-content\"><strong>2 CHIYODA, CHIYODA-KU, TŌKYŌ-TO</strong></p></div>\n<!-- /wp:themeisle-blocks/icon-list-item --></div>\n<!-- /wp:themeisle-blocks/icon-list -->\n\n<!-- wp:spacer {\"height\":\"50px\"} -->\n<div style=\"height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:social-links {\"iconColor\":\"nv-site-bg\",\"iconColorValue\":\"var(\\u002d\\u002dnv-site-bg)\",\"iconBackgroundColor\":\"neve-link-color\",\"iconBackgroundColorValue\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"is-style-default\"} -->\n<ul class=\"wp-block-social-links has-icon-color has-icon-background-color is-style-default\"><!-- wp:social-link {\"url\":\"#\",\"service\":\"facebook\",\"hasCustomCSS\":true} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"twitter\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"google\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"pinterest\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"instagram\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:t