label\":\"Email\",\"isRequired\":true} -->\n<div id=\"wp-block-themeisle-blocks-form-input-78aab247\" class=\"wp-block-themeisle-blocks-form-input\"><label for=\"wp-block-themeisle-blocks-form-input-78aab247-input\" class=\"otter-form-input-label\"><span class=\"otter-form-input-label__label\">Email</span><span class=\"required\">*</span></label><input type=\"email\" id=\"wp-block-themeisle-blocks-form-input-78aab247-input\" required class=\"otter-form-input\"/></div>\n<!-- /wp:themeisle-blocks/form-input -->\n<!-- wp:themeisle-blocks/form-nonce {\"formId\":\"wp-block-themeisle-blocks-form-bc819deb\"} /-->\n<!-- wp:themeisle-blocks/form-textarea {\"id\":\"wp-block-themeisle-blocks-form-textarea-8b7d97e4\",\"label\":\"Message\"} -->\n<div id=\"wp-block-themeisle-blocks-form-textarea-8b7d97e4\" class=\"wp-block-themeisle-blocks-form-textarea\"><label for=\"wp-block-themeisle-blocks-form-textarea-8b7d97e4-input\" class=\"otter-form-textarea-label\"><span class=\"otter-form-textarea-label__label\">Message</span></label><textarea id=\"wp-block-themeisle-blocks-form-textarea-8b7d97e4-input\" rows=\"10\" class=\"otter-form-textarea-input\"></textarea></div>\n<!-- /wp:themeisle-blocks/form-textarea -->\n<div class=\"wp-block-button\"><button class=\"wp-block-button__link\" type=\"submit\">Submit</button></div></form></div>\n<!-- /wp:themeisle-blocks/form --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"right\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a910e476\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a910e476\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:spacer {\"height\":\"0px\"} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-3eafa5d1\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-3eafa5d1\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-3eafa5d1\"><strong>Telebanca</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>A través del <strong>centro de llamadas</strong> pueden ser atendidas las solicitudes de información general de los productos o servicios que ofrece el <strong>Banco Metropolitano</strong>, gestionar servicios bancarios, pagar la electricidad, la telefonía fija, el agua, impuestos, pagos de multas y contravenciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es el canal por excelencia para atender y gestionar las inquietudes o reclamaciones relacionadas con los servicios asociados a la banca electrónica y los canales de pagos digitales con el empleo de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7868-3535, 7866-0606</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: clientes@banmet.cu</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-6c86ac21\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-6c86ac21\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-b5a1e3ad\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-b5a1e3ad\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-feb2b9c6\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-feb2b9c6\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-feb2b9c6\"><strong><strong>Atención a clientes sobre quejas, sugerencias y reclamaciones</strong></strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Las inquietudes, quejas, sugerencias y reclamaciones son gestionadas por especialistas del departamento de <strong>Atención a Clientes</strong> en calle Cuba 225 esquina a O’ Reilly, La Habana Vieja, La Habana, Cuba.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7801-3418 y 7801-3333 extensiones 1121 y 1124</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: atencionalapoblacion@banmet.cu </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-43db9348\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-43db9348\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-5f5fe8aa\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-5f5fe8aa\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-09969818\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-09969818\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-09969818\"><strong><strong><strong>Atención a clientes del segmento de personas jurídicas: empresarios, mipymes, trabajadores por cuenta propia, cooperativas no agropecuarias, otras formas de gestión no estatal</strong></strong></strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Para empresarios, cooperativas, otras formas de gestión no estatal</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:negocios@banmet.cu\">negocios@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para trabajadores por cuenta propia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:tcp@banmet.cu\">tcp@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para micro, pequeñas y medianas empresas (mipymes)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:mipymes@banmet.cu\">mipymes@banmet.cu</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-77331213\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-77331213\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-3d2c1928\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-3d2c1928\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-455bc1a2\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-455bc1a2\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-455bc1a2\"><strong><strong><strong><strong>Atencion a clientes. Gestión de créditos bancarios</strong></strong></strong></strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Se ofrece asesoramiento, otorgamiento y seguimiento a las solicitudes en las <strong>Oficinas de Crédito</strong>. También pueden visitar las <strong>sucursales bancarias</strong> en todos los municipios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Plaza de la Revolución</strong>, calle 23 entre P y Malecón, La Rampa, Vedado</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7833-2316</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Diez de Octubre</strong>, Juan Delgado esquina a Lacret, Díez de Octubre</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7649-5215</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Contáctenos', '', 'inherit', 'closed', 'closed', '', '744-revision-v1', '', '', '2024-05-02 20:56:10', '2024-05-02 20:56:10', '', 744, 'http://localhost/banco-actual/?p=810', 0, 'revision', '', 0);
INSERT INTO `banmetx_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2115, 1, '2024-06-19 03:00:42', '2024-06-19 03:00:42', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"columnsHeight\":\"custom\",\"columnsHeightCustom\":420,\"columnsHeightCustomMobile\":200,\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":500,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2023/11/slide-banca-movil.jpg\"},\"backgroundPosition\":{\"x\":0.55,\"y\":0.4},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"backgroundOverlayOpacity\":5,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-d86c0863\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-d86c0863\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Tarifas, Comisiones y Otros cargos</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"40px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1b193dd3\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7969f93c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7969f93c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El <strong>Banco Metropolitano</strong> aplica las <strong>tasas y comisiones</strong> para los servicios que ofrecen las sucursales a las <strong>Representaciones Diplomáticas</strong> y <strong>Consulares</strong>, <strong>Entidades Comerciales Privadas</strong>, <strong>Cubanas</strong>, <strong>Extranjeras </strong>o<strong> Mixtas, </strong>a <strong>ciudadanos extranjeros</strong> radicados en Cuba, a <strong>turistas</strong> y a otras <strong>personas naturales</strong> que sean <strong>titulares </strong>de<strong> cuentas bancarias</strong> en <strong>pesos cubanos</strong> (CUP), en <strong>monedas libremente convertibles</strong> (MLC) u otras que requieran de la prestación de un servicio determinado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>precios</strong> de las <strong>tarifas</strong>, <strong>comisiones</strong> y <strong>otros cargos</strong> se <strong>reconocen </strong>en<strong> CUP</strong>,con independencia de la moneda en que se ejecute el pago.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;<strong>Condiciones generales:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El banco se reserva el derecho de cargar comisiones por servicios bancarios no contemplados en la relación que aparecen a continuación y, de realizar las modificaciones sin previo aviso.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los servicios que requieran el uso adicional de las comunicaciones, se le sumarán a su comisión inicial.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos rehusados y/o reclamados por otras contrapartes o bancos serán a cargo del cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los gastos que se originan en el exterior y se exijan por los bancos corresponsales, se cargan a la cuenta del ordenante.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-54e9a28c\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-54e9a28c\" class=\"wp-block-themeisle-blocks-advanced-columns has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-6727c3e6\",\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-6727c3e6\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-f9333d82\",\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"titleBackground\":\"var(\\u002d\\u002dnv-site-bg)\",\"alwaysOpen\":false,\"activeTitleColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"activeTitleBackground\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"is-style-default  has-light-active-title-bg has-light-title-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-f9333d82\" class=\"wp-block-themeisle-blocks-accordion exclusive is-style-default  has-light-active-title-bg has-light-title-bg\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de Cuentas Bancarias\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio de Cuentas Bancarias</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:table {\"className\":\"is-style-stripes\"} -->\n<figure class=\"wp-block-table is-style-stripes\"><table><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\"><strong>Apertura de cuentas</strong><br>Porciento:<br>Mínimo:<br>Máximo: <strong>Libre</strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes del mes de apertura. Excepto las cuentas en USD que pueden variar por la tasa de cambio<br>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Cierre de cuentas de todo tipo antes los tres meses de apertura. Excepto las en USD que puedan variar por la tasa de cambio<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Deterioro de libreta de ahorro (se excluyen los modelos de depósito a plazo fijo y certificado de depósito)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>20.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Extravío de Libreta de Ahorro<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas adicionales de Cuentas Corrientes (persona natural)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Estados de Cuentas y Certificación de Cuentas (Personas Naturales con Cuentas de Ahorro)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>100.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de Saldos a Clientes. (Cuenta de ahorro o corriente, por cada cuenta que solicite el titular. Se incluye la certificación de cobro de jubilación o pensión)<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>40.00</strong></strong></strong></td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Certificación de adeudos a clientes<br><strong>Porciento:<br>Mínimo:<br>Máximo: <strong><strong>10.00</strong></strong></strong></td></tr></tbody></table></figure>\n<!-- /wp:table --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003eServicio de Cheques y Giros\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>Servicio 