ll,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Modalidades de ahorro para personas naturales</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:paragraph -->\n<p><strong>Apertura de cuentas de ahorro (Generales):</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>A ciudadanos cubanos o extranjeros mayores de 18 años de edad, previa presentación de sus documentos de identidad (carné de identidad o pasaporte), según sea el caso.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En pesos cubanos (CUP) o en dólares estadounidenses (USD). En el caso de las cuentas en USD se puede extraer en monedas libremente convertibles (MLC) diferentes a los USD, vigentes en el país. Ante la solicitud de extracciones en USD, se aplicará la reservación del efectivo.&nbsp;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Podrán ser operadas mediante <strong>PODER NOTARIAL ESPECÍFICO</strong>, excepto la apertura.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pueden ser de tipo:</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Individual</strong>: abiertas a nombre de una persona natural. Admiten designación de beneficiarios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Indistintas o Solidarias</strong>: a nombre de dos o tres personas naturales con carácter solidario; las extracciones y cierre de cuentas pueden efectuarse indistintamente por uno de sus titulares. La titulación de la cuenta se compone de los nombres y apellidos de cada uno de los titulares, consignándose la palabra “<strong>INDISTINTAMENTE</strong>”. No admiten la designación de beneficiarios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Conjuntas o Mancomunadas</strong>: a nombre de dos o tres personas con carácter mancomunado; las extracciones y cierre de la cuenta requieren las firmas de todos sus titulares conjuntamente. Su titulación se compone de los nombres y apellidos de cada uno de ellos, consignándose la palabra “<strong>CONJUNTAMENTE</strong>”. No se designan beneficiarios, solo operan con <strong>Libretas de Ahorro</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->', 'Modalidades de ahorro para personas naturales', '', 'inherit', 'closed', 'closed', '', '922-revision-v1', '', '', '2024-05-07 20:26:36', '2024-05-07 20:26:36', '', 922, 'http://localhost/banco-actual/?p=934', 0, 'revision', '', 0),
