bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Cuentas de ahorro A LA VISTA</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-7bd1f247\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-7bd1f247\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-aaea5e08\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-aaea5e08\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Es un depósito que puede ser utilizado total o parcialmente en el momento deseado. Pueden ser en soporte de tarjeta magnética <strong>RED</strong> o <strong>Libreta</strong>, en el caso de las cuentas en USD <strong>solo podrán abrirse en soporte de libreta de ahorro.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Estas cuentas devengan intereses a partir de 200,00 CUP o USD;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El importe mínimo al abrir la cuenta en libreta de ahorro es de 50,00 CUP o 50,00 USD, en el caso de efectivo es en moneda libremente convertible (MLC)<strong>;</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las cuentas que se abran con tarjeta magnética <strong>RED</strong> es en saldo 0.00, solo <strong>en CUP;</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>La cantidad mínima a depositar <strong>en efectivo</strong> posterior a la apertura, es de importes superiores a 1,00 CUP o MLC, tanto en soporte de libreta de ahorro como de tarjeta magnética RED;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los depósitos pueden realizarse en efectivo en CUP y MLC, cheques, transferencias desde otros bancos comerciales (cubanos o extranjeros), transferencias entre cuentas de la misma moneda o desde cuentas de monedas libremente convertibles aplicando el tipo de cambio vigente de depositarse en una cuenta en CUP, del mismo banco o de otros bancos del país;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Operaciones a realizar con <strong>libreta de ahorro</strong> en otros bancos comerciales de otras provincias:</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>En el Banco Popular de Ahorro (BPA): </strong>una extracción de hasta 5 000,00 CUP, manteniendo en la cuenta un saldo de 50,00 CUP.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>En el Banco de Crédito y Comercio (BANDEC)</strong>: una extracción de hasta 5 000,00 CUP manteniendo en la cuenta un saldo de 50,00 CUP.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pueden constituirse como garantía en créditos bancarios excepto las de menores y discapacitados con representación legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Las cuentas de ahorro en CUP se pueden utilizar como garantías para la solicitud de créditos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las cuentas en tarjeta magnética <strong>RED</strong> le permiten pagar las compras de bienes y servicios, utilizando los canales de pagos electrónicos del servicio <strong>Banca MÓVIL</strong> mediante las aplicaciones Transfermóvil y EnZona.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Cuentas de Formación de Fondos:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La formación de fondos es una cuenta que se incrementa mediante descuento de importes fijos mensuales del salario, jubilación o pensión de seguridad social u otro pago. Puede abrirse soportada en libreta de ahorro o por tarjeta magnética.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Está a disposición de las personas naturales residentes en el territorio nacional, para los jubilados y pensionados de la Seguridad Social y de centros de pagos, vinculados a las sucursales del Banco Metropolitano, tanto trabajadores estatales como de otras formas de gestión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se abrirán solo de tipo Individual.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas de ahorro A LA VISTA', '', 'publish', 'closed', 'closed', '', 'cuentas-de-ahorro-a-la-vista', '', '', '2024-05-07 21:29:34', '2024-05-07 21:29:34', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=970', 0, 'portafolio', '', 0),
