\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-76cbffc8\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-76cbffc8\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a84e485e\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a84e485e\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>En libreta de ahorro: </strong>Precisa de un depósito inicial en efectivo (10,00 CUP para jubilados y pensionados y para los trabajadores a partir de 30,00 CUP). Los depósitos se realizarán mediante descuentos por nóminas de las mensualidades acordadas por el cliente o titular de la cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>En tarjeta RED: </strong>Se abren con saldo cero y depósitos iniciales por descuentos de nómina a partir de 10,00 CUP (jubilados y/o pensionados) y para el resto de los trabajadores a partir de 30,00 CUP.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En ambos casos:</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Podrán efectuar depósitos adicionales sin restricción de importe ni frecuencia, en efectivo, o por traspasos electrónicos;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se recibirá un interés anual de un 2% sobre cualquier saldo. De no extraerse ningún importe durante un año natural, se bonifica con un 2% adicional, así como, de no realizar extracciones durante al menos de 3 años naturales desde su apertura, se bonifica con un 1 % adicional, lo que permite ganar un interés total del 5%;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se pueden realizar hasta 4 extracciones por año natural, considerado a partir de la fecha de apertura, la quinta extracción representa el cierre de la misma;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>La mensualidad podrá ser modificada por comunicación de la entidad o por presentación del titular en la sucursal de apertura de la cuenta.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Puede constituirse como garantía de créditos bancarios.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas PARA EL FUTURO', '', 'inherit', 'closed', 'closed', '', '976-revision-v1', '', '', '2024-05-07 21:35:46', '2024-05-07 21:35:46', '', 976, 'http://localhost/banco-actual/?p=981', 0, 'revision', '', 0),
