bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Ahorros para las vacaciones</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-a3a350b6\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-a3a350b6\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-39446176\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-39446176\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>La apertura se efectuará a personas naturales, desde cuentas asociadas a <strong>tarjetas magnéticas RED</strong> de salario, jubilación y ahorro, por:</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Transfermóvil; en el mensaje llega la confirmación con el número de cuenta;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>De forma presencial, se entrega un comprobante con número de la cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No requiere soporte documental por lo que no se imprimirá tarjeta RED;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se abrirán en saldo cero y el primer depósito es por descuento, la mensualidad será como mínimo 200,00 CUP, así como, el saldo a tener en cuenta tanto en la apertura presencial, como a través de Transfermóvil;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El plazo es de 1 año, prorrogable de forma automática, acreditando los intereses y el principal a la cuenta de donde provienen los descuentos;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Devengarán intereses de 4% anual abonándose al vencimiento del plazo del año, transfiriéndose a la cuenta de donde provienen los descuentos, comenzando nuevamente el ciclo anual de la cuenta y, de 0.5% anual, de cerrarse antes del año por decisión del titular;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No admite depósitos adicionales y de realizarse alguna extracción antes del vencimiento del plazo, ésta constituye su cierre;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las mensualidades serán acreditadas:</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Por descuentos en tarjetas RED de trabajadores estatales o no, asociados a un centro de pago y por jubilados;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En el resto de las personas naturales (estudiantes, amas de casa, trabajadores por cuenta propia, desvinculados) se descontarán de las cuentas de ahorro del 5 al 10 de cada mes, de forma automática;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En los trabajadores que no perciban sus ingresos en tarjeta RED, se realizarán en la fecha acordada con el centro de pago.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Puede constituirse como garantía de créditos bancarios.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'AHORROS VERNO', '', 'inherit', 'closed', 'closed', '', '987-revision-v1', '', '', '2024-05-07 21:42:22', '2024-05-07 21:42:22', '', 987, 'http://localhost/banco-actual/?p=990', 0, 'revision', '', 0),
