bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Cuentas de DEPÓSITO A PLAZO FIJO</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f342a8d4\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f342a8d4\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0c7832c6\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0c7832c6\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Es un depósito de determinada cantidad de efectivo en pesos cubanos (CUP), y dólares estadounidenses (USD) durante el plazo acordado entre el cliente y el banco, con el compromiso de no extraer ni depositar hasta el vencimiento del plazo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Una misma persona puede abrir cuantos depósitos desee y a los plazos que estime;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El importe mínimo de apertura es de 200,00 CUP y 100,00 USD;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las tasas de interés vigentes en el momento de la apertura dependen del plazo de imposición. Los plazos pueden ser de 3, 6, 12, 24, 36, 60 y 72 meses y el interés a devengar <strong>por plazos vencidos</strong> transita desde el 2 hasta el 7% con el principio de a mayor plazo, mayor interés. El plazo de 72 meses es solo para depósitos en pesos cubanos (CUP);</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El cobro de los intereses y el cierre de la cuenta se pueden realizar en sucursales del mismo centro contable que la oficina de apertura. El titular podrá cobrar los intereses en efectivo, capitalizarlos al principal si lo solicita o depositarlos en una cuenta de ahorro a la vista;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Al vencimiento del plazo se prorroga de oficio de no presentarse el titular y la tasa de interés será la vigente en el momento de la prórroga, la que puede no coincidir con la que estaba en el momento de la apertura;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si se cerrara el depósito antes del plazo de vencimiento inicial o de uno prorrogado, se perderá el derecho al cobro de los intereses del plazo no vencido.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Puede constituirse como garantía de créditos bancarios.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-67e7d5b9\",\"tag\":\"h3\",\"className\":\"\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-67e7d5b9\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-67e7d5b9\"><strong>DEPÓSITO A PLAZO FIJO por Transfermóvil (inversión temporal)</strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Constituyen una facilidad que el Banco Metropolitano ofrece a sus clientes, a través de la aplicación Transfermóvil. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Es para el cliente con una cuenta de ahorro en CUP con tarjeta magnética RED, ordenando desde esa cuenta ordenar el importe de la apertura del Depósito a Plazo Fijo (origen);</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las tasas de interés vigentes en el momento de la apertura dependen del plazo de imposición. Los plazos pueden ser de 12, 24, 36, 60 y el interés a devengar <strong>por plazos vencidos</strong> transita desde el 4 hasta el 6.5% con el principio de a mayor plazo, mayor interés, liquidándose a la misma cuenta de ahorro a la vista desde donde se originó, siempre en períodos vencidos;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los beneficiarios serán los mismos que tiene designados en la cuenta de donde se originó el depósito;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No contarán con documentación ni soporte alguno.<strong> </strong>Su registro se mantendrá en la Sucursal Electrónica con las medidas de seguridad requeridas para la conservación y archivo de la apertura de forma digital; </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Podrán cerrarse en el momento que el titular lo determine desde la aplicación Transfermóvil. El saldo con que cuente en el momento del cierre será acreditado de forma automática en la cuenta desde la que se ordenó la apertura del Depósito a Plazo Fijo;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si el cierre interrumpe los plazos seleccionados al abrir el Depósito a Plazo Fijo, pierde los intereses.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong> Puede constituirse como garantía de créditos bancarios.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas de DEPÓSITO A PLAZO FIJO', '', 'publish', 'closed', 'closed', '', 'cuentas-de-deposito-a-plazo-fijo', '', '', '2024-05-07 23:21:17', '2024-05-07 23:21:17', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=994', 0, 'portafolio', '', 0),
