"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Cuentas en USD CON RESPALDO MLC</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-10908a8f\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-10908a8f\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-96633cef\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-96633cef\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Producto a disposición de las personas naturales cubanas o extranjeras, con tarjeta magnética RED como medio de pago de bienes o servicios a través de los terminales de puntos de venta (TPV o POS) habilitados en los establecimientos y oficinas comerciales, donde los precios son en USD.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La pueden abrir las personas naturales residentes permanentes o no en Cuba, nacionales o extranjeros, se incluyen las que presenten, como medio de identificación, pasaporte con visa turística.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Se pueden abrir con saldo cero;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los depósitos podrán ser en efectivo o por transferencias bancarias de monedas libremente convertibles (MLC) que se aceptan en el país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No devengan interés; </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se podrá obtener efectivo en CUP a través de los cajeros automáticos (ATM) y por las ventanillas de las sucursales USD, EUR y CUP.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Utilizar los canales de pagos electrónicos disponibles: Transfermóvil, EnZona, Telebanca.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Extraer efectivo en la red de cajeros automáticos en CUP, al tipo de cambio vigente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Extraer efectivo MLC o CUP en cajeros de línea de las sucursales del Banco Metropolitano, al tipo de cambio vigente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar pagos por terminales de puntos de venta (TPV o POS).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar pagos en línea mediante códigos QR.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Recibir transferencias de otras cuentas en USD de bancos comerciales cubanos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas en USD CON RESPALDO MLC', '', 'publish', 'closed', 'closed', '', 'cuentas-en-usd-con-respaldo-mlc', '', '', '2024-05-07 23:29:33', '2024-05-07 23:29:33', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1009', 0, 'portafolio', '', 0),
