"left\":\"30px\"},\"backgroundOverlayOpacity\":60,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayBlend\":\"difference\",\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-096d673d\" class=\"wp-block-themeisle-blocks-advanced-column\"><div class=\"wp-block-themeisle-blocks-advanced-column-overlay\"></div><!-- wp:themeisle-blocks/posts-grid {\"id\":\"wp-block-themeisle-blocks-posts-grid-c6c16ce0\",\"style\":\"list\",\"categories\":[{\"id\":37,\"name\":\"Destacada\",\"slug\":\"destacada\"}],\"postsToShow\":2,\"displayFeaturedImage\":false,\"titleTag\":\"h2\",\"displayUpdatedDate\":true,\"displayAuthor\":false,\"textColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"borderColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"borderWidth\":\"1px\",\"textAlign\":\"left\",\"enableFeaturedPost\":false,\"className\":\" is-style-boxed\"} /--></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-fa9918bf\",\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-fa9918bf\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-e5c9bbe4\",\"columns\":1,\"layout\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-e5c9bbe4\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-twoOne-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"