:\"equal\",\"padding\":{\"top\":\"80px\",\"bottom\":\"60px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":600,\"horizontalAlign\":\"center\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-2eeda035\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-23a2196c\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"10px\",\"right\":\"10px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"100\",\"className\":\"nl-form\",\"hasCustomCSS\":true} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-23a2196c\" class=\"wp-block-themeisle-blocks-advanced-column nl-form\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"neve-text-color\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-neve-text-color-color has-text-color\">Nuestro Boletín</h2>\n<!-- /wp:heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-b0a1497c\",\"tag\":\"p\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":0,\"className\":\"\"} -->\n<p id=\"wp-block-themeisle-blocks-advanced-heading-b0a1497c\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-b0a1497c\">Desea recibir noticias e informaciones de los productos y servicios del Banco Metropolitano</p>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:html -->\n<style>\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview {\n      display: flex !important;\n      flex-direction: column !important;\n      justify-content: center !important;\n      margin-top: 0px !important;\n      padding: clamp(17px, 5%, 40px) clamp(17px, 7%, 50px) !important;\n      max-width: none !important;\n      border-radius: 0px !important;\n      box-shadow: none;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview,\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview *{\n      box-sizing: border-box !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-heading {\n      width: 100% !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-heading h5{\n      margin-top: 0 !important;\n      margin-bottom: 0