anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Tarjeta magnética RED</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Corporativa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-4b43525a\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-4b43525a\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a660d8af\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a660d8af\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>La <strong>tarjeta magnética</strong> RED le permite disponer de su dinero sin tener que llevarlo en efectivo, recibir transferencias monetarias, así como acceder a los canales de pagos electrónicos <strong>Transfermóvil</strong>, <strong>EnZona</strong>, <strong>Telebanca</strong>, <strong>Cajeros Automáticos</strong>, <strong>Terminales de Puntos de Venta</strong> (TPV o POS), entre otros beneficios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Disponible para los segmentos de clientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Jubilados y pensionados de la seguridad social.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Trabajadores del sector estatal para el pago de salarios y utilidades.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Trabajadores del sector no estatal (cooperativas no agropecuarias, trabajadores por cuenta propia, mipymes, agricultores pequeños, otras formas de gestión no estatal).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Renovación por pérdidas o deterioro.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Características:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Las cuentas se abren a personas naturales, ciudadanos cubanos y extranjeros residentes en el país de 18 o más años de edad.<ul><li>Sus saldos están representados en pesos cubanos (CUP) o en dólares estadounidenses (USD).</li></ul><ul><li>Pueden recibir depósitos mediante efectivo, cheques de cuentas corrientes si la sucursal que lo recibe en calidad de depósito tiene la cuenta corriente del girador del cheque, cheques certificados y cheques de gerencia del Banco Metropolitano u otros bancos.</li></ul><ul><li>Estos depósitos se pueden efectuar en la sucursal más cercana o de su preferencia, entregándose como constancia un comprobante acuñado y firmado por el cajero.</li></ul><ul><li>Se pueden efectuar transferencias de fondos a favor del titular en CUP desde otras localidades del país y desde el extranjero cuando son cuentas en USD u otra moneda libremente convertible (MLC) que se acepten en el país.</li></ul><ul><li>Las extracciones en efectivo se realizan por los cajeros automáticos en cantidades enteras, sin centavos.</li></ul><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Devengan igual interés como las cuentas de <strong>Ahorro a la Vista</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Al realizar transacciones con las tarjetas magnéticas se exige:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La presentación de la misma debidamente firmada. La identificación del cliente o titular mediante carné de&nbsp;identidad para la compra de&nbsp;bienes o servicios en los comercios con&nbsp;terminales de puntos de venta (TPV o POS). Se exigirá que el comprobante que emita el TPV, sea firmado por el cliente con la misma firma de la tarjeta.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Ahorrar dinero y ganar intereses. No tiene necesidad de portar efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Medio de pago con alcance nacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seguridad y rapidez en las transacciones, en las compras de bienes y servicios en establecimientos con códigos QR mediante las aplicaciones <strong>Transfermóvil</strong> o <strong>EnZona</strong> del servicio <strong>Banca MÓVIL</strong> o mediante los terminales de puntos de venta (TPV o POS).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Posibilidad de operar las <strong>24 horas</strong> del día en la red de cajeros automáticos del país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Telebanca</strong>, para el pago de los servicios de agua, teléfono fijo, multas, electricidad, pago de impuestos, transferencias entre cuentas o del propio cliente. Consultar el saldo de las cuentas y de las últimas operaciones realizadas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Banca MÓVIL</strong> mediante las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong> para el pago de los servicios de agua, teléfono, multas, electricidad, pago de impuestos, realizar transferencias entre cuentas. Realizar consultas del saldo en las cuentas y las últimas operaciones realizadas. Gestionar servicios de telefónica celular y otros asociados a la <strong>Empresa de Telecomunicaciones de Cuba S.A.</strong> (Etecsa).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Incrementar el saldo de su cuenta a través de depósitos por transferencias o en efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar transferencias monetarias hacia otra cuenta en tarjeta de igual moneda, emitida por bancos comerciales cubanos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Extraer dinero en las sucursales bancarias y en CADECA a través de los TPV o POS y en los establecimientos comerciales habilitados con el servicio <strong>Caja EXTRA</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Cuentas en Dólares estadounidenses (USD) con tarjeta magnética:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El titular puede comprar bienes y servicios en la red de establecimientos comerciales con <strong>TPV </strong>o<strong> POS</strong>, realizar pagos en línea mediante los <strong>códigos QR</strong>, así como la extracción de efectivo en CUP al tipo de cambio vigente en la red de <strong>cajeros automáticos</strong> en el país, las <strong>24 horas del día</strong>. También puede extraer efectivo en las ventanillas del <strong>Banco Metropolitano</strong> y de <strong>CADECA</strong> los días y horarios laborables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Disponible en la actualidad para el segmento de clientes:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Jubilados y pensionados de la seguridad social.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Trabajadores del sector estatal para el pago de salarios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Trabajadores de cooperativas no agropecuarias, trabajadores por cuenta propia, agricultores pequeños, mipymes y otras formas de gestión no estatal.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Renovación por pérdidas o deterioro.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Características:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Las cuentas se abren a personas naturales, ciudadanos cubanos y extranjeros residentes y no residentes en el país con 18 o más años de edad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sus saldos están representados en pesos cubanos (CUP) y en dólares estadounidenses (USD) con respaldo en monedas libremente convertibles (MLC) para la compra de bienes y servicios en los establecimientos con precios en USD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los depósitos se pueden efectuar en cualquier sucursal del Banco Metropolitano, entregándose como constancia un comprobante acuñado y firmado por el cajero.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las extracciones en efectivo se realizan en cantidades enteras, sin centavos, en CUP por los cajeros automáticos, por las terminales de puntos de venta (TPV o POS), por ventanilla en las sucursales y en los establecimientos comerciales que tengan habilitados el servicio de Caja EXTRA.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las cuentas de ahorro en USD devengan el interés correspondiente para ese tipo de cuentas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las cuentas en USD con respaldo en MLC para la compra en establecimientos con precios en esa moneda, no reciben interés ni bonificaciones.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Al realizar operaciones mediante la tarjeta se exige:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>La presentación de la misma debidamente firmada.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Identificación del cliente mediante carné de identidad para la compra de bienes o servicios en tiendas y oficinas comerciales a través de los TPV o POS.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al pago de productos y extracción de efectivo mediante <strong>códigos QR</strong> en establecimientos comerciales donde esté habilitado el servicio de <strong>Caja EXTRA</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se exigirá además que el comprobante que emita el TPV o POS sea firmado por el cliente con la misma firma de la tarjeta.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Tarjeta magnética RED', '', 'inherit', 'closed', 'closed', '', '1075-revision-v1', '', '', '2024-05-08 03:47:18', '2024-05-08 03:47:18', '', 1075, 'http://localhost/banco-actual/?p=1078', 0, 'revision', '', 0),
(1079, 1, '2024-05-08 03:49:42', '2024-05-08 03:49:42', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"columnsHeight\":\"custom\",\"columnsHeightCustom\":420,\"columnsHeightCustomMobile\":200,\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":533,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2024/01/hero-section.jpg\"},\"backgroundPosition\":{\"x\":0.55,\"y\":0.4},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"backgroundOverlayOpacity\":5,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-d86c0863\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-d86c0863\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Cambio de PIN digital</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Electrónica</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-bc85404c\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-bc85404c\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-3714155a\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-3714155a\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>CLAVE o PIN de la tarjeta magnética</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>PIN digital</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para <strong>activar</strong> el uso de la <strong>tarjeta magnética</strong> RED para utilizarla por los <strong>canales de pagos electrónicos</strong> (Transfermóvil, EnZona, Telebanca, TPV o POS, Cajeros Automáticos) el cliente o titular deberá cambiar el <strong>PIN digital</strong> inicial (también conocido como <strong>PIN no impreso</strong>).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El <strong>PIN</strong> digital es la <strong>CLAVE</strong> de la tarjeta magnética y lo puede obtener a través de la aplicación <strong>Transfermóvil</strong> del servicio <strong>Banca MÓVIL</strong> o por <strong>Telebanca</strong> (servicio de banca telefónica).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Requisito para obtener la CLAVE o PIN de la tarjeta magnética:</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Tener <strong>activa</strong> la tarjeta de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Pasos a seguir para obtener de la CLAVE o PIN de la tarjeta magnética:</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Recibir la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seleccionar la aplicación <strong>Transfermóvil </strong>o el servicio <strong>Telebanca </strong>para obtener el <strong>PIN inicial</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para obtener el PIN digital de la tarjeta magnética a través de Telebanca:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 1: </strong>comuníquese con el centro de llamadas de <strong>Telebanca</strong> por los números telefónicos <strong>7868-3535</strong> o <strong>7866-0606</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tiene DOS OPCIONES:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Opción 1:</strong>&nbsp; <strong>Teclee 1</strong> para ser atendido por una operadora y siga sus instrucciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Opción 2:</strong> <strong>Teclee 2</strong> para acceder al sistema automático de <strong>respuesta de voz interactiva</strong> (IVR) de <strong>Telebanca</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>número de la tarjeta</strong> (aparece al dorso) de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>PIN</strong> de la tarjeta de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee 3</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>número</strong> de la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El cliente recibirá dos <strong>coordenadas</strong> de la tarjeta <strong>Telebanca</strong> para formar la <strong>CLAVE inicial</strong> de la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Para obtener la <strong>CLAVE definitiva</strong> debe dirigirse a un cajero automático donde:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Introducirá</strong> la tarjeta con la <strong>CLAVE inicial</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cambiará la <strong>CLAVE inicial</strong> asignada por otra que pueda memorizar fácilmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para obtener el PIN digital de la tarjeta magnética a través de la Banca Móvil:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 1: autentíquese</strong> en la aplicación <strong>Transfermóvil</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 2:</strong> ir a módulo <strong>Banco Metropolitano</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 3:</strong> ir a <strong>Configuración</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 4:</strong> seleccione la <strong>Opción</strong>: <strong>Generar Código PIN / PIN no impreso</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 5: </strong>llene los <strong>campos indicados</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 6:</strong> recibirá un <strong>mensaje</strong> con <strong>dos coordenadas</strong> de la tarjeta de <strong>Telebanca</strong> para formar la <strong>CLAVE inicial</strong> de la <strong>tarjeta magnética</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para obtener la <strong>CLAVE definitiva</strong> debe dirigirse a un <strong>cajero automático</strong> donde:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Introducirá</strong> la <strong>tarjeta magnética</strong> con la <strong>CLAVE inicial</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cambiará la <strong>CLAVE inicial</strong> asignada por otra que pueda memorizar fácilmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Ahorrar dinero y ganar intereses en las cuentas de ahorro en CUP y USD (excepto las cuentas en USD con respaldo en MLC que no ganan interés).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Medio de pago con alcance nacional. No tiene necesidad de portar efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seguridad y rapidez en las transacciones y compras de bienes y servicios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Posibilidad de operar las <strong>24 horas</strong> del día en la red de cajeros automáticos del país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Telebanca</strong>, para el pago de los servicios de agua, teléfono, multas, electricidad, pago de impuestos, realizar transferencias entre cuentas o del propio cliente por vía telefónica.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Banca MÓVIL</strong> mediante las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>, para recibir los beneficios del comercio electrónico.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Consultar el saldo de las cuentas y de las últimas operaciones realizadas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar compras en la red comercial de todo el país con TPV o POS, recibiendo bonificaciones promocionales.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Incrementar el saldo de su cuenta mediante depósitos por transferencias o depósitos en efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Recibir transferencias monetarias desde el exterior.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar transferencias monetarias hacia otra cuenta con tarjeta magnética de igual moneda emitida por bancos comerciales cubanos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Extraer dinero en las sucursales bancarias y en las de CADECA.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cambio de PIN digital', 'Para activar el uso de la tarjeta magnética RED para utilizarla por los ', 'publish', 'closed', 'closed', '', 'cambio-de-pin-digital', '', '', '2024-05-08 14:49:44', '2024-05-08 14:49:44', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1079', 0, 'portafolio', '', 0),
