anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Domiciliación de nóminas</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Electrónica</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-5c5c9da7\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-5c5c9da7\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-885ff410\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-885ff410\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Cuentas que se abren a trabajadores fijos, vinculados a <strong>entidades estatales</strong> con quienes el banco haya firmado <strong>contrato</strong> para domiciliar nóminas, también a pensionados y jubilados de la Seguridad Social.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">&nbsp;</h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Características:</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En esta cuenta se reciben depósitos ordenados por la empresa o entidad. correspondiente y la dependencia municipal del MTSS, mediante domiciliación   del salario o pensión, no se incluyen los importes por descuentos de pensiones alimenticias.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Permite agilizar los pagos de salarios y cobros de diferentes servicios estatales.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las extracciones se realizan en la red de cajeros automáticos mediante el empleo de la tarjeta magnética, solamente en pesos, sin centavos, manteniéndose estos últimos en el saldo del submayor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las extracciones a través de los cajeros automáticos, solo se dispensan hasta 40 billetes como máximo en dependencia del importe solicitado.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las tarjetas de débito se entregan sin costo para el cliente a pesar de su renovación periódica. En los casos de pérdida, deterioro o robo, el cliente pagará una comisión, excepto los jubilados y pensionados, según las <strong>Tarifas de Comisiones y Otros cargos</strong> vigentes en el <strong>Banco Metropolitano</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las cuentas son de tipo individual.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Admite designar beneficiarios, se efectúa la transmisión del saldo por herencia o beneficiarios, de acuerdo con las regulaciones legales vigentes.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>&nbsp;</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Valor agregado:</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Le facilita la <strong>gestión de pago</strong> de servicios estatales.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Accede al <strong>comercio electrónico</strong> con el uso de los medios de pagos digitales <strong>Transfermóvil</strong>, <strong>EnZona</strong>, también a través de <strong>Telebanca</strong>, <strong>cajeros automáticos</strong> y <strong>TPV</strong> o <strong>POS</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar <strong>pagos en línea</strong> de bienes y servicios mediante <strong>códigos QR</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Domiciliación de nóminas', '', 'publish', 'closed', 'closed', '', 'domiciliacion-de-nominas', '', '', '2024-05-08 04:06:07', '2024-05-08 04:06:07', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1098', 0, 'portafolio', '', 0),
