l,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9f8863c7\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9f8863c7\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7e7f595d\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7e7f595d\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-5633ce3b\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-5633ce3b\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-5633ce3b\"><strong>Pago electrónico</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"className\":\"\"} -->\n<p>Le facilita de manera rápida y segura, realizar el pago a través de <strong>códigos QR</strong> en establecimientos y oficinas comerciales donde se encuentren habilitados.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-1d2c8081\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-1d2c8081\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-1d2c8081\"><strong>Servicio de Caja EXTRA</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"className\":\"\"} -->\n<p>En los comercios donde se encuentre habilitado el servicio de <strong>Caja EXTRA</strong>, podrá como una alternativa, obtener hasta <strong>5 000,00 CUP</strong> de la tarjeta magnética de salario, de ahorro, de jubilación o pensión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"\"} -->\n<p>Recibirá un mensaje de operación exitosa y le será entregado su efectivo.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Pago electrónico y Caja EXTRA', '', 'publish', 'closed', 'closed', '', 'pago-electronico-y-caja-extra', '', '', '2024-05-08 04:10:51', '2024-05-08 04:10:51', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1100', 0, 'portafolio', '', 0),
(1101, 1, '2024-05-08 04:09:36', '2024-05-08 04:09:36', '<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-5633ce3b\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-5633ce3b\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-5633ce3b\"><strong>Pago electrónico</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Le facilita de manera rápida y segura, realizar el pago a través de <strong>códigos QR</strong> en establecimientos y oficinas comerciales donde se encuentren habilitados.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-1d2c8081\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-1d2c8081\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-1d2c8081\"><strong>Servicio de Caja EXTRA</strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>En los comercios donde se encuentre habilitado el servicio de <strong>Caja EXTRA</strong>, podrá como una alternativa, obtener hasta <strong>5 000,00 CUP</strong> de la tarjeta magnética de salario, de ahorro, de jubilación o pensión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Recibirá un mensaje de operación exitosa y le será entregado su efectivo.</p>\n<!-- /wp:paragraph -->', 'Pago electrónico y Caja EXTRA', '', 'inherit', 'closed', 'closed', '', '1100-revision-v1', '', '', '2024-05-08 04:09:36', '2024-05-08 04:09:36', '', 1100, 'http://localhost/banco-actual/?p=1101', 0, 'revision', '', 0),
