anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Estados de cuentas por correo electrónico</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Electrónica</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f748c593\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f748c593\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-cc131908\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-cc131908\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Para recibir los <strong>estados de cuenta por correo electrónico</strong>, una vez solicitada la suscripción en la sucursal donde opera su cuenta bancaria, informando en esa ocasión, la dirección electrónica (correo-e) por donde recibirá los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información le será enviada como documento adjunto en <strong>formato PDF</strong>, al correo-e de destino acordado, por lo que deberá tener instalado en la terminal informática (PC, laptop), el software adecuado para poder abrirlo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El banco se compromete a enviar la información con la frecuencia convenida, siempre que existan movimientos en cuenta que lo justifiquen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Este servicio, que se ofrece sin costo alguno, le reporta ahorro de tiempo y le facilita recibir en su escritorio, los <strong>estados de cuenta</strong> sin tener que acudir a la sucursal. Si el documento se solicita de impreso, se cobra una <strong>comisión adicional</strong> en CUP o USD, según la moneda de la cuenta y la periodicidad con que lo solicite, según las <strong>Tarifas de Comisiones y Otros gastos</strong>, vigente en el <strong>Banco Metropolitano</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En la actualidad, es un servicio que se ofrece al segmento de clientes jurídicos: empresas estatales, unidades presupuestadas, cooperativas, trabajadores por cuenta propia, mipymes, agricultores pequeños.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>&nbsp;</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Valor agregado:</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Inmediatez.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seguridad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Confiabilidad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ahorro de tiempo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Protección del fichero.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Estados de cuentas por correo electrónico', '', 'inherit', 'closed', 'closed', '', '1094-revision-v1', '', '', '2024-05-08 04:18:10', '2024-05-08 04:18:10', '', 1094, 'http://localhost/banco-actual/?p=1116', 0, 'revision', '', 0),
(1122, 1, '2024-05-08 04:25:07', '2024-05-08 04:25:07', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-839f2f0d\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-839f2f0d\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-cc327f32\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-cc327f32\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Depósito de determinada cantidad de dinero en <strong>moneda libremente convertible</strong> (MLC) que se ordena desde el exterior y se recibe en Cuba en <strong>pesos cubanos</strong> (CUP) y en <strong>dólares estadounidenses</strong> (USD).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para enviar la transferencia bancaria o remesa de dinero a Cuba, el interesado debe dirigirse a la sucursal bancaria más cercana de la ciudad o localidad de donde se encuentre, solicitándola enviarla a través de uno de los <a href=\"http://www.banco-metropolitano.com.cu/bancos-corresponsales/\">bancos corresponsales</a> del <strong>Banco Metropolitano</strong> que se informan en esta aplicación. <strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Datos de nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre:</strong> Banco Metropolitano S.A.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT:</strong> BMNBCUHH. No utilizamos los códigos BIC o IBAN.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de la cuenta bancaria o de la tarjeta magnética.</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si no posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dirección de residencia:</strong> calle o avenida, número de la casa o apartamento, entre calles, reparto o localidad, código postal, municipio, provincia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de identidad personal:</strong> carné de identidad o pasaporte.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teléfono</strong>: donde se pueda localizar al beneficiario de la transferencia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT del Banco Metropolitano:</strong> BMNBCUHH.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código <a href=\"http://www.banco-metropolitano.com.cu/directorio-red-de-sucursales/\">de la sucursal</a></strong>: donde desea cobrar la transferencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Para enviar la transferencia bancaria o remesa de dinero a Cuba:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"start\":1} -->\n<ol start=\"1\"><!-- wp:list-item -->\n<li>Al enviar la transferencia a beneficiarios residentes en La Habana, deberá especificar al banco ordenante que su interés es enviar el dinero a través del Banco Metropolitano, S.A. De utilizarse otros bancos comerciales, se incrementan los gastos por comisiones.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Gestionamos transferencias hacia el resto del país.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">&nbsp;</h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">&nbsp;</h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">&nbsp;</h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Importante:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Antes de ordenar la transferencia en el banco emisor, se debe revisar detalladamente todos los datos del beneficiario en Cuba, para evitar demoras o molestias. </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las transferencias bancarias o remesas de dinero pueden enviarse para depositarse en cuentas en CUP (al tipo de cambio vigente) o en USD. También a cuentas en USD con respaldo en monedas libremente convertibles (MLC), habilitadas para las compras de bienes y servicios en establecimientos comerciales en esa moneda.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También pueden cobrarse en efectivo en la sucursal bancaria que elija el beneficiario.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si el beneficiario tiene una cuenta en el Banco Metropolitano, S.A. se le cobrarán comisiones más económicas, aunque no es necesaria para recibir dinero desde otro país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contamos con sucursales en los 15 municipios de la capital.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El beneficiario puede cobrar el dinero en Euros, en efectivo, si la transferencia está denominada en esa moneda originalmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Valor agregado:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Abrir cuentas de <strong>Ahorro a la Vista</strong>, <strong>Depósitos a Plazos Fijos</strong>, <strong>Certificados de Depósitos</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Enviar transferencias dentro del país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Transferir a otras cuentas de <strong>Ahorro a la Vista</strong> con tarjetas magnéticas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pagar bienes y servicios en USD o CUP (al tipo de cambio vigente) en establecimientos y oficinas comerciales con <strong>terminales de puntos de venta</strong> (TPV o POS) o realizar <strong>pagos en línea</strong> por <strong>códigos QR</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Transferencias monetarias desde el exterior', '', 'inherit', 'closed', 'closed', '', '1117-revision-v1', '', '', '2024-05-08 04:25:07', '2024-05-08 04:25:07', '', 1117, 'http://localhost/banco-actual/?p=1122', 0, 'revision', '', 0),
