"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Cambio de PIN digital</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Electrónica</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-bc85404c\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-bc85404c\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-3714155a\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-3714155a\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>CLAVE o PIN de la tarjeta magnética</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>PIN digital</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para <strong>activar</strong> el uso de la <strong>tarjeta magnética</strong> RED para utilizarla por los <strong>canales de pagos electrónicos</strong> (Transfermóvil, EnZona, Telebanca, TPV o POS, Cajeros Automáticos) el cliente o titular deberá cambiar el <strong>PIN digital</strong> inicial (también conocido como <strong>PIN no impreso</strong>).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El <strong>PIN</strong> digital es la <strong>CLAVE</strong> de la tarjeta magnética y lo puede obtener a través de la aplicación <strong>Transfermóvil</strong> del servicio <strong>Banca MÓVIL</strong> o por <strong>Telebanca</strong> (servicio de banca telefónica).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Requisito para obtener la CLAVE o PIN de la tarjeta magnética:</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Tener <strong>activa</strong> la tarjeta de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Pasos a seguir para obtener de la CLAVE o PIN de la tarjeta magnética:</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Recibir la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seleccionar la aplicación <strong>Transfermóvil </strong>o el servicio <strong>Telebanca </strong>para obtener el <strong>PIN inicial</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para obtener el PIN digital de la tarjeta magnética a través de Telebanca:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 1: </strong>comuníquese con el centro de llamadas de <strong>Telebanca</strong> por los números telefónicos <strong>7868-3535</strong> o <strong>7866-0606</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tiene DOS OPCIONES:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Opción 1:</strong>&nbsp; <strong>Teclee 1</strong> para ser atendido por una operadora y siga sus instrucciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Opción 2:</strong> <strong>Teclee 2</strong> para acceder al sistema automático de <strong>respuesta de voz interactiva</strong> (IVR) de <strong>Telebanca</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>número de la tarjeta</strong> (aparece al dorso) de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>PIN</strong> de la tarjeta de <strong>Telebanca</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee 3</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teclee</strong> el <strong>número</strong> de la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El cliente recibirá dos <strong>coordenadas</strong> de la tarjeta <strong>Telebanca</strong> para formar la <strong>CLAVE inicial</strong> de la <strong>tarjeta magnética</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Para obtener la <strong>CLAVE definitiva</strong> debe dirigirse a un cajero automático donde:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Introducirá</strong> la tarjeta con la <strong>CLAVE inicial</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cambiará la <strong>CLAVE inicial</strong> asignada por otra que pueda memorizar fácilmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para obtener el PIN digital de la tarjeta magnética a través de la Banca Móvil:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 1: autentíquese</strong> en la aplicación <strong>Transfermóvil</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 2:</strong> ir a módulo <strong>Banco Metropolitano</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 3:</strong> ir a <strong>Configuración</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 4:</strong> seleccione la <strong>Opción</strong>: <strong>Generar Código PIN / PIN no impreso</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 5: </strong>llene los <strong>campos indicados</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Paso 6:</strong> recibirá un <strong>mensaje</strong> con <strong>dos coordenadas</strong> de la tarjeta de <strong>Telebanca</strong> para formar la <strong>CLAVE inicial</strong> de la <strong>tarjeta magnética</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para obtener la <strong>CLAVE definitiva</strong> debe dirigirse a un <strong>cajero automático</strong> donde:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Introducirá</strong> la <strong>tarjeta magnética</strong> con la <strong>CLAVE inicial</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cambiará la <strong>CLAVE inicial</strong> asignada por otra que pueda memorizar fácilmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Ahorrar dinero y ganar intereses en las cuentas de ahorro en CUP y USD (excepto las cuentas en USD con respaldo en MLC que no ganan interés).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Medio de pago con alcance nacional. No tiene necesidad de portar efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seguridad y rapidez en las transacciones y compras de bienes y servicios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Posibilidad de operar las <strong>24 horas</strong> del día en la red de cajeros automáticos del país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Telebanca</strong>, para el pago de los servicios de agua, teléfono, multas, electricidad, pago de impuestos, realizar transferencias entre cuentas o del propio cliente por vía telefónica.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acceder al servicio de <strong>Banca MÓVIL</strong> mediante las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>, para recibir los beneficios del comercio electrónico.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Consultar el saldo de las cuentas y de las últimas operaciones realizadas.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar compras en la red comercial de todo el país con TPV o POS, recibiendo bonificaciones promocionales.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Incrementar el saldo de su cuenta mediante depósitos por transferencias o depósitos en efectivo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Recibir transferencias monetarias desde el exterior.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar transferencias monetarias hacia otra cuenta con tarjeta magnética de igual moneda emitida por bancos comerciales cubanos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Extraer dinero en las sucursales bancarias y en las de CADECA.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cambio de PIN digital', 'Para activar el uso de la tarjeta magnética RED para utilizarla por los canales de pagos electrónicos (Transfermóvil, EnZona, Telebanca, TPV o POS, Cajeros Automáticos) el cliente o titular deberá cambiar el PIN digital inicial (también conocido como PIN no impreso).', 'inherit', 'closed', 'closed', '', '1079-revision-v1', '', '', '2024-05-08 14:46:39', '2024-05-08 14:46:39', '', 1079, 'http://localhost/banco-actual/?p=1166', 0, 'revision', '', 0);
