anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Préstamos</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Corporativa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-0b773abf\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-0b773abf\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ad60887f\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ad60887f\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>Para CAPITAL DE TRABAJO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Personas jurídicas nacionales, empresas estatales, sociedades mercantiles, Unidades Básicas de Producción Cooperativa (UBPC), Cooperativas de Créditos y Servicios (CCS), Trabajadores por Cuenta Propia (TCP), Agricultores Pequeños (AP) y Cooperativas no Agropecuarias (CNA), Micro, Pequeñas y Medianas Empresas (Mipymes) que se desempeñan en la actividad económica, con capacidad y solvencia reconocida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se relacionan con las necesidades de recursos a corto y mediano plazo de las entidades económicas, para cubrir la diferencia entre los ingresos y egresos corrientes de su ciclo de producción y comercialización, entre ellos, para la adquisición de materias primas, materiales y servicios, mantenimiento de las existencias, entre otras, mediante contrato entre las partes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Documentación necesaria para&nbsp;obtener un Préstamo:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cliente debe presentar la documentación que acredite su identidad y legalidad para asumir los compromisos que puedan surgir al recibir el préstamo solicitado, ofrecer una caracterización de la actividad que realiza, motivo o fin del préstamo, estados financieros, preferiblemente auditados, flujo de tesorería real y proyectado u otra información que resulte necesaria para el análisis de la solicitud.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Condiciones para el otorgamiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El sistema de amortización es negociado entre las partes, a partir de la política de riesgos del banco y la capacidad real de devolución de las deudas según el flujo de tesorería proyectado. El plazo máximo de amortización, así como la amortización anticipada y la cancelación anticipada es, según arreglo con el cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los saldos deudores devengarán intereses desde la fecha de su otorgamiento hasta su total amortización. La liquidación de intereses es según se pacte y se negocian individualmente con cada cliente, según el riesgo que tenga la operación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las comisiones y tasas de interés que se cobran por los préstamos otorgados son las comprendidas en las Tarifas de Comisiones y Otros cargos del Banco Metropolitano.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>La tasa de interés que se aplica a los préstamos en pesos cubanos (CUP) está en el rango del 2.5% al 10 %, con una sobretasa por mora máxima del 4%.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para el análisis de riesgo se tendrá en cuenta:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Análisis cualitativo de la empresa<strong>: </strong>situación económica actual y perspectiva, posicionamiento en el mercado, calidad de la producción, clientes y suministradores, cumplimiento de las obligaciones de pago, confiabilidad de la contabilidad, entre otras.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis cuantitativo de la situación financiera de la empresa: solvencia, liquidez, rentabilidad, efectividad en la utilización de los recursos, valoración del flujo de tesorería proyectado, entre otras.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis del riesgo de la operación: plazos, importe, destino, entorno económico, calidad del financiamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El banco establecerá el control de todas las operaciones vivas, enfatizando en la situación financiera de la empresa y las garantías otorgadas. Con este objetivo el cliente debe proporcionar periódicamente la información que a tales efectos el banco requiera.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tipos de garantía:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Nota de autorizo de débito en cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pignoración: se aplica sobre los saldos de cuentas bancarias del solicitante del crédito de un tercero efectuadas en la misma institución.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cesión: es una transmisión no del derecho al crédito sino del título mismo del certificado de depósito que tiene el valor incorporado al documento.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Títulos de créditos: avalados por instituciones financieras debidamente endosados al banco con responsabilidad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cuentas colaterales: cuentas que crea el banco donde se reserva un porciento o un importe fijo, según lo pactado en el contrato, de los fondos existentes en la cuenta corriente del deudor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Otras previstas en la práctica bancaria.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para INVERSIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Segmento de mercado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Personas jurídicas cubanas estatales y no estatales, Trabajadores por Cuenta Propia (TCP), Agricultores Pequeños (AP), Micro, Pequeñas y Medianas Empresas (Mipymes) y personas naturales que ejercen otras formas de gestión no estatal con capacidad y solvencia reconocida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se financian las necesidades de recursos que impliquen incremento de la capacidad productiva o de servicios a partir de la reposición, ampliación, modernización o nueva inversión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Documentación necesaria para obtener un Préstamo:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cliente debe presentar la documentación que acredite su identidad y legalidad de las relaciones contractuales que pueden surgir de la solicitud, caracterización de la actividad que realiza, información sobre la operación concreta que motiva la solicitud, estados financieros, preferiblemente auditados, flujo de tesorería real y proyectado y otra que resulte necesaria para el análisis de dicha solicitud.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Condiciones para el otorgamiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El sistema de amortización es negociado entre las partes a partir de la política de riesgos del banco y la capacidad real de devolución de las deudas según el flujo de tesorería proyectado. El plazo máximo de amortización, así como la amortización anticipada y la cancelación anticipada es según arreglo con el cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los saldos deudores devengarán intereses desde la fecha de su otorgamiento hasta su total amortización. La liquidación de intereses es según se pacte y se negocian individualmente con cada cliente, según el riesgo que tenga la operación.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Las comisiones y tasas de interés que se cobran por los préstamos otorgados son las comprendidas en las <strong>Tarifas de Comisiones y Otros cargos</strong> del Banco Metropolitano.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Para el análisis de riesgo se tendrá en cuenta:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Análisis cualitativo de la empresa: situación económica actual y perspectiva, posicionamiento en el mercado, calidad de la producción, clientes y suministradores, cumplimiento de las obligaciones de pago, confiabilidad de la contabilidad, etc.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis cuantitativo de la situación financiero de la empresa: Solvencia, liquidez, rentabilidad, efectividad en la utilización de los recursos, valoración del flujo de tesorería proyectado, etc.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis del riesgo de la operación: plazos, importe, destino, entorno económico, calidad del financiamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El Banco establecerá el control de todas las operaciones enfatizando en la situación financiera de la empresa y en las garantías otorgadas de acuerdo a las establecidas en la legislación vigentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tipos de garantía:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Nota de autorizo de débito en cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pignoración; se aplica sobre los saldos de cuentas bancarias del solicitante del crédito de un tercero efectuadas en la misma institución.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cesión; es una transmisión no del derecho al crédito sino del título mismo del certificado de depósito que tiene el valor incorporado al documento.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Títulos de créditos; avalados por instituciones financieras debidamente endosados al Banco con responsabilidad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cuentas colaterales; cuentas internas que crea el Banco donde se reserva un porciento o un importe fijo, según lo pactado en contrato, de los fondos existentes en la cuenta corriente del deudor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Otras previstas en la práctica bancaria.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Línea de CRÉDITOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Modalidad de financiamiento que, de ser aprobada por el Comité de Crédito, se legaliza mediante contrato entre las partes, con lo cual el banco se obliga, dentro del límite pactado, a poner a disposición del cliente y a medida de su requerimiento, los recursos financieros que podrá utilizar total o parcialmente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El análisis de la operación se realiza, previa presentación de la solicitud por escrito al banco, acompañándose de los balances, flujo de caja, finalidad del crédito, garantías, así como otros documentos que resulten de interés para el banco.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El destino del financiamiento debe estar en correspondencia con las actividades recogidas dentro del objeto social de la documentación legal del cliente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>La línea de crédito puede ser:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong><u>Revolvente</u></strong><strong>:</strong> permite al acreditado (solicitante) disponer del financiamiento aprobado y realizar liquidaciones parciales del saldo que le restituye su capacidad de endeudamiento dentro del plazo pactado. Este crédito generalmente no podrá exceder de 1 año. El cliente podrá solicitar renovar la línea llegada su vencimiento 30 días antes de la fecha pactada, de lo contrario se le formalizará un crédito simple por el importe adeudado, presentando al banco la propuesta de los plazos de amortización.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong><u>No Revolvente</u></strong><strong>:</strong> permite al acreditado (solicitante) hacer disposiciones de la línea de crédito hasta el monto autorizado, sin que tenga derecho a volver a disponer de él, aun cuando haya realizado liquidaciones anticipadas dentro del plazo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Préstamos', '', 'publish', 'closed', 'closed', '', 'prestamos', '', '', '2024-05-10 19:33:30', '2024-05-10 19:33:30', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1173', 0, 'portafolio', '', 0),
(1176, 1, '2024-05-10 19:30:56', '2024-05-10 19:30:56', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-0b773abf\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-0b773abf\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ad60887f\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ad60887f\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>Para CAPITAL DE TRABAJO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Personas jurídicas nacionales, empresas estatales, sociedades mercantiles, Unidades Básicas de Producción Cooperativa (UBPC), Cooperativas de Créditos y Servicios (CCS), Trabajadores por Cuenta Propia (TCP), Agricultores Pequeños (AP) y Cooperativas no Agropecuarias (CNA), Micro, Pequeñas y Medianas Empresas (Mipymes) que se desempeñan en la actividad económica, con capacidad y solvencia reconocida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se relacionan con las necesidades de recursos a corto y mediano plazo de las entidades económicas, para cubrir la diferencia entre los ingresos y egresos corrientes de su ciclo de producción y comercialización, entre ellos, para la adquisición de materias primas, materiales y servicios, mantenimiento de las existencias, entre otras, mediante contrato entre las partes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Documentación necesaria para&nbsp;obtener un Préstamo:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cliente debe presentar la documentación que acredite su identidad y legalidad para asumir los compromisos que puedan surgir al recibir el préstamo solicitado, ofrecer una caracterización de la actividad que realiza, motivo o fin del préstamo, estados financieros, preferiblemente auditados, flujo de tesorería real y proyectado u otra información que resulte necesaria para el análisis de la solicitud.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Condiciones para el otorgamiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El sistema de amortización es negociado entre las partes, a partir de la política de riesgos del banco y la capacidad real de devolución de las deudas según el flujo de tesorería proyectado. El plazo máximo de amortización, así como la amortización anticipada y la cancelación anticipada es, según arreglo con el cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los saldos deudores devengarán intereses desde la fecha de su otorgamiento hasta su total amortización. La liquidación de intereses es según se pacte y se negocian individualmente con cada cliente, según el riesgo que tenga la operación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las comisiones y tasas de interés que se cobran por los préstamos otorgados son las comprendidas en las Tarifas de Comisiones y Otros cargos del Banco Metropolitano.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>La tasa de interés que se aplica a los préstamos en pesos cubanos (CUP) está en el rango del 2.5% al 10 %, con una sobretasa por mora máxima del 4%.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para el análisis de riesgo se tendrá en cuenta:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Análisis cualitativo de la empresa<strong>: </strong>situación económica actual y perspectiva, posicionamiento en el mercado, calidad de la producción, clientes y suministradores, cumplimiento de las obligaciones de pago, confiabilidad de la contabilidad, entre otras.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis cuantitativo de la situación financiera de la empresa: solvencia, liquidez, rentabilidad, efectividad en la utilización de los recursos, valoración del flujo de tesorería proyectado, entre otras.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis del riesgo de la operación: plazos, importe, destino, entorno económico, calidad del financiamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El banco establecerá el control de todas las operaciones vivas, enfatizando en la situación financiera de la empresa y las garantías otorgadas. Con este objetivo el cliente debe proporcionar periódicamente la información que a tales efectos el banco requiera.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tipos de garantía:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Nota de autorizo de débito en cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pignoración: se aplica sobre los saldos de cuentas bancarias del solicitante del crédito de un tercero efectuadas en la misma institución.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cesión: es una transmisión no del derecho al crédito sino del título mismo del certificado de depósito que tiene el valor incorporado al documento.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Títulos de créditos: avalados por instituciones financieras debidamente endosados al banco con responsabilidad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cuentas colaterales: cuentas que crea el banco donde se reserva un porciento o un importe fijo, según lo pactado en el contrato, de los fondos existentes en la cuenta corriente del deudor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Otras previstas en la práctica bancaria.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Para INVERSIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Segmento de mercado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Personas jurídicas cubanas estatales y no estatales, Trabajadores por Cuenta Propia (TCP), Agricultores Pequeños (AP), Micro, Pequeñas y Medianas Empresas (Mipymes) y personas naturales que ejercen otras formas de gestión no estatal con capacidad y solvencia reconocida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se financian las necesidades de recursos que impliquen incremento de la capacidad productiva o de servicios a partir de la reposición, ampliación, modernización o nueva inversión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Documentación necesaria para obtener un Préstamo:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cliente debe presentar la documentación que acredite su identidad y legalidad de las relaciones contractuales que pueden surgir de la solicitud, caracterización de la actividad que realiza, información sobre la operación concreta que motiva la solicitud, estados financieros, preferiblemente auditados, flujo de tesorería real y proyectado y otra que resulte necesaria para el análisis de dicha solicitud.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Condiciones para el otorgamiento:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El sistema de amortización es negociado entre las partes a partir de la política de riesgos del banco y la capacidad real de devolución de las deudas según el flujo de tesorería proyectado. El plazo máximo de amortización, así como la amortización anticipada y la cancelación anticipada es según arreglo con el cliente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los saldos deudores devengarán intereses desde la fecha de su otorgamiento hasta su total amortización. La liquidación de intereses es según se pacte y se negocian individualmente con cada cliente, según el riesgo que tenga la operación.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Las comisiones y tasas de interés que se cobran por los préstamos otorgados son las comprendidas en las <strong>Tarifas de Comisiones y Otros cargos</strong> del Banco Metropolitano.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Para el análisis de riesgo se tendrá en cuenta:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Análisis cualitativo de la empresa: situación económica actual y perspectiva, posicionamiento en el mercado, calidad de la producción, clientes y suministradores, cumplimiento de las obligaciones de pago, confiabilidad de la contabilidad, etc.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis cuantitativo de la situación financiero de la empresa: Solvencia, liquidez, rentabilidad, efectividad en la utilización de los recursos, valoración del flujo de tesorería proyectado, etc.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Análisis del riesgo de la operación: plazos, importe, destino, entorno económico, calidad del financiamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El Banco establecerá el control de todas las operaciones enfatizando en la situación financiera de la empresa y en las garantías otorgadas de acuerdo a las establecidas en la legislación vigentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Tipos de garantía:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Nota de autorizo de débito en cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pignoración; se aplica sobre los saldos de cuentas bancarias del solicitante del crédito de un tercero efectuadas en la misma institución.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cesión; es una transmisión no del derecho al crédito sino del título mismo del certificado de depósito que tiene el valor incorporado al documento.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Títulos de créditos; avalados por instituciones financieras debidamente endosados al Banco con responsabilidad.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cuentas colaterales; cuentas internas que crea el Banco donde se reserva un porciento o un importe fijo, según lo pactado en contrato, de los fondos existentes en la cuenta corriente del deudor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Otras previstas en la práctica bancaria.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Línea de CRÉDITOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Modalidad de financiamiento que, de ser aprobada por el Comité de Crédito, se legaliza mediante contrato entre las partes, con lo cual el banco se obliga, dentro del límite pactado, a poner a disposición del cliente y a medida de su requerimiento, los recursos financieros que podrá utilizar total o parcialmente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El análisis de la operación se realiza, previa presentación de la solicitud por escrito al banco, acompañándose de los balances, flujo de caja, finalidad del crédito, garantías, así como otros documentos que resulten de interés para el banco.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El destino del financiamiento debe estar en correspondencia con las actividades recogidas dentro del objeto social de la documentación legal del cliente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>La línea de crédito puede ser:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong><u>Revolvente</u></strong><strong>:</strong> permite al acreditado (solicitante) disponer del financiamiento aprobado y realizar liquidaciones parciales del saldo que le restituye su capacidad de endeudamiento dentro del plazo pactado. Este crédito generalmente no podrá exceder de 1 año. El cliente podrá solicitar renovar la línea llegada su vencimiento 30 días antes de la fecha pactada, de lo contrario se le formalizará un crédito simple por el importe adeudado, presentando al banco la propuesta de los plazos de amortización.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong><u>No Revolvente</u></strong><strong>:</strong> permite al acreditado (solicitante) hacer disposiciones de la línea de crédito hasta el monto autorizado, sin que tenga derecho a volver a disponer de él, aun cuando haya realizado liquidaciones anticipadas dentro del plazo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Préstamos', '', 'inherit', 'closed', 'closed', '', '1173-revision-v1', '', '', '2024-05-10 19:30:56', '2024-05-10 19:30:56', '', 1173, 'http://localhost/banco-actual/?p=1176', 0, 'revision', '', 0);
