"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Aval de Riesgo para Apertura de CARTA DE CRÉDITO INTERNACIONAL</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Corporativa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-3659a02f\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-3659a02f\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a7f399e2\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a7f399e2\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>La aprobación a un cliente de una línea de aval de riesgo para la emisión de cartas de crédito internacionales, es una modalidad que permite que sean abiertas cartas de créditos al amparo de contratos internacionales de importación, pagaderas a favor de proveedores de clientes de Banco Metropolitano, sin que el mismo (usualmente empresa estatal) tenga que inmovilizar dinero en cuenta colateral y/o acceder al crédito bancario desde el momento de la emisión de este instrumento, asumiendo gastos financieros anticipados asociados tanto al crédito como a la inmovilización de liquidez en colaterales, cuando el pago al proveedor extranjero puede ser&nbsp; entre 360 a 720 días posteriores de haber recibido la mercancía.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cliente beneficiario de la importación, presenta la solicitud de línea de aval de riesgo, solicitud de emisión de carta de crédito, estados financieros y flujos de caja real y proyectado. Se realiza el análisis de riesgo de la operación, valorando los ingresos a obtener a partir de la recepción de la mercancía importada (reflejada en la carta de crédito), producción y venta, donde se define el % y periodo para la retención de sus ingresos en una cuenta scrow, que les permita tener el respaldo para el pago de la Carta Crédito en el momento del pago al proveedor extranjero.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El comité de crédito evalúa la solicitud y de aprobarse la línea de aval, define que, si llegado el momento del pago al exterior no se cuenta en la scrow con fondos suficientes para cubrir el valor total de la carta de crédito, se formalizará un crédito simple por el déficit, a 360 días, bajo los términos y condiciones que se aprueben.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si en el momento del pago no se ha acumulado el 100% del monto a pagar en la cuenta colateral, se otorgará un crédito simple.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Cuenta Corriente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Financiamientos para cooperativas no agropecuarias, MYPIMES, trabajadores por cuenta propia, pequeños agricultores y otras formas de gestión no estatal.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cuentas corrientes y cuentas corrientes fiscales para cooperativas no agropecuarias, MIPYMES, trabajadores por cuenta propia, pequeños agricultores y otras formas de gestión no estatal.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Aval de Riesgo para Apertura de CARTA DE CRÉDITO INTERNACIONAL', '', 'inherit', 'closed', 'closed', '', '1203-revision-v1', '', '', '2024-05-10 20:10:35', '2024-05-10 20:10:35', '', 1203, 'http://localhost/banco-actual/?p=1206', 0, 'revision', '', 0),
