anced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Pago a beneficiarios y herederos</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">OTROS TRÁMITES Y SERVICIOS</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-ba0bed27\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-ba0bed27\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a167e7a6\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a167e7a6\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Se pueden designar todos los beneficiarios que se deseen, cuando se trata de las cuentas de <strong>Ahorro a la Vista</strong> y <strong>Depósito a Plazo Fijo</strong>, de tipo individual. En ambos casos, entre todas las cuentas de un tipo u otro que posea el cliente en pesos cubanos (CUP) o dólares estadounidenses (USD), los beneficiarios podrán cobrar sólo hasta <strong>5 000.00</strong> de la suma total de los saldos de los depósitos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En caso de estar casado (a) el (la) titular fallecido (a), su viuda (o) tendrá derecho a cobrar el <strong>50 %</strong> del saldo durante la vigencia del matrimonio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La parte restante del saldo quedará a disposición de los <strong>beneficiarios designados</strong> y luego de que éstos cobren, el resto puede ser solicitado por los <strong>herederos</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Valor agregado:</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Abrir cuentas de <strong>Ahorro a la Vista</strong>, <strong>Depósitos a Plazos Fijos</strong>, <strong>Certificados de Depósitos</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Realizar <strong>transferencias bancarias</strong> dentro del país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Solicitar <strong>créditos bancarios</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Acceder a los servicios de <strong>comercio electrónico</strong> a través de las pasarelas de pagos electrónicos <strong>Transfermóvil</strong>, <strong>EnZona</strong> y el servicio de banca telefónica <strong>Telebanca</strong>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Pago a beneficiarios y herederos', '', 'inherit', 'closed', 'closed', '', '1214-revision-v1', '', '', '2024-05-10 20:25:16', '2024-05-10 20:25:16', '', 1214, 'http://localhost/banco-actual/?p=1218', 0, 'revision', '', 0),
(1219, 1, '2024-05-10 20:28:14', '2024-05-10 20:28:14', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"columnsHeight\":\"custom\",\"columnsHeightCustom\":420,\"columnsHeightCustomMobile\":200,\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":533,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2024/01/hero-section.jpg\"},\"backgroundPosition\":{\"x\":0.55,\"y\":0.4},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"backgroundOverlayOpacity\":5,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-d86c0863\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-d86c0863\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Ley General de la Vivienda</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">OTROS TRÁMITES Y SERVICIOS</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-5dda0ca4\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-5dda0ca4\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-32732ba4\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-32732ba4\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El Banco Metropolitano, S.A. en representación del Estado, transfiere las propiedades de las viviendas estatales, en los casos procedentes, mediante Contrato de compraventa a plazos, en el que el comprador se constituye en deudor del Estado por el importe del precio legal de la vivienda, pagadero en mensualidades fijas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Contrato se otorga a favor de la persona a la cual se le asigne la vivienda y si esta fuere casada, a favor de ambos cónyuges. En caso de que el cónyuge no resida permanentemente en la vivienda el contrato se expide a nombre del titular, consignándose una nota aclaratoria en el Contrato de compraventa.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En el mismo contrato se constituirán&nbsp;en codeudores solidarios para el pago del precio aplazado a favor del Estado, todas las demás personas mayores de 18 años, que con el comprador pasen a residir en el inmueble en la fecha de la compraventa, y tengan ingresos propios. También puede constituirse como codeudor solidario, voluntariamente, cualquier otra persona. Como garantía de pago para la transferencia de la propiedad se exigirán al menos dos codeudores solidarios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Al precio legal de una vivienda, fijado por la Dirección Municipal de la Vivienda (DMV), se le agrega el importe de los intereses bancarios. La DMV también determina el importe de las mensualidades a pagar, sobre la base de amortizar el precio y la transferencia de la propiedad en veinte años, si se tratara de edificios altos, o en quince en los demás casos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El cobro de las mensualidades a cuenta del precio de la compraventa se hace a solicitud del Banco Metropolitano, S.A. mediante retenciones en los salarios, sueldos, haberes, pensiones, cualquier otra retribución periódica y otros ingresos que perciba el comprador, y en caso de que resulte imposible en algún momento realizar dichos descuentos, se realizarán mediante retenciones en cualquier ingreso de los codeudores solidarios. Si en algún momento el cobro fuera imposible mediante las retenciones anteriores, el Banco puede pactar con el comprador otra forma de garantizar el pago, y si la imposibilidad resultara de la reducción de los ingresos de este, puede reducirse el importe de la cantidad mensual a pagar, extendiéndose el término de pago del precio total por el tiempo necesario.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En caso de que el comprador no percibiera ingresos sobre los cuales practicar las retenciones, o aun percibiéndolos no tuviera codeudores solidarios, estará obligado a realizar los pagos de las mensualidades en la&nbsp; Sucursal correspondiente a su domicilio y en este supuesto, el comprador se considera como ARRENDATARIO ADQUIRENTE, entregándose un Contrato de Arrendamiento con opción de compra hasta la liquidación total del adeudo, momento en el cual se procede a la entrega del Título de Propiedad – Contrato de Compraventa.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>En caso de extravío del Contrato el titular puede pedir al Banco copia certificada. Se cobra una comisión de 10,00 pesos cubanos (CUP) y sellos timbrados por valor de 15,00 pesos cubanos (CUP).</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Las tasas de descuentos son aplicables a aquellas personas cuyas deudas hayan sido contraídas en o antes de la fecha del Acuerdo (8 de agosto de 1995), del siguiente modo:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table><tbody><tr><td><strong>Si el cliente liquida en la fecha en que se presenta en el Banco</strong></td><td><strong>Descuento como bonificación</strong></td></tr><tr><td>El 100 % de la deuda</td><td>El 25% de la deuda</td></tr><tr><td>Entre el 60 % y menos del 100 % de la deuda</td><td>El 20% de la deuda</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph -->\n<p><strong>Situaciones Posteriores a la Transferencia de Propiedad por el Banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En caso de divorcio de los propietarios, el tribunal competente determina a quién se adjudica la propiedad de la vivienda ocupada por ambos ex cónyuges, e igualmente procede en caso de liquidación de la comunidad matrimonial de bienes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En los supuestos mencionados, si existieren adeudos, el Banco Metropolitano está obligado a ajustarlos, de acuerdo a la liquidación de la comunidad matrimonial de bienes, siempre que esta operación resulte garantizada con la capacidad de pago de cada ex cónyuge.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En caso de permutas, el Banco Metropolitano, S.A. puede autorizar el traspaso total o parcial de adeudos entre los permutantes, siempre que la capacidad de pago del nuevo deudor y las de sus codeudores solidarios ofrezca garantía suficiente para el cobro total de la deuda que asume.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando se trate de permutas múltiples realizadas con el objetivo de liquidar la comunidad matrimonial de bienes, el Banco Metropolitano está obligado a dividir el adeudo pendiente, entre los dos ex cónyuges siempre que esta operación resulte garantizada con la capacidad de pago de ambos propietarios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En caso de permutas administrativas, cuando el propietario que permuta resultará obligado a pagar una diferencia de precio, esto se realizará en la misma forma y mensualidades que venía abonando al banco.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si como consecuencia del aumento del precio de la deuda, se sobrepasa el término de 15 años en el momento de la permuta, se incrementará el importe de la mensualidad para ajustar a ese término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En los casos en que se unifiquen dos viviendas por decisión de sus propietarios, acto que se efectúa ante un notario público, si estuviere pendiente de pagar el precio de una o de ambas viviendas, se mantienen respecto al Banco Metropolitano, las mismas obligaciones que mantenían sus propietarios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien reciba, en condición de heredero, una vivienda que perteneciera a un propietario fallecido que no haya liquidado su deuda con el Banco, está obligado a amortizar la misma, en iguales términos en que el fallecido efectuaba los pagos, sin perjuicio de que en los casos correspondientes se aplique lo dispuesto en el segundo párrafo del apartado 3. Por tal motivo es obligatorio que cuando se presente una persona con derecho a la transferencia del inmueble, está presente además de la Resolución que le da derecho a la titularidad el documento que acredite su estado conyugal.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Ley General de la Vivienda', '', 'publish', 'closed', 'closed', '', 'ley-general-de-la-vivienda', '', '', '2024-05-10 20:28:51', '2024-05-10 20:28:51', '', 0, 'http://localhost/banco-actual/?post_type=portafolio&#038;p=1219', 0, 'portafolio', '', 0);
