s/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Derechos y deberes de los clientes</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-3d22a30c\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-3d22a30c\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-1195c58f\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-1195c58f\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>Derechos básicos de los clientes</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Recibir un trato cordial y profesional, un servicio diligente y eficiente.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tener a su disposición la publicidad e información transparente, clara, veraz, oportuna y verificable, sobre las características de los productos y servicios.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Recibir productos y servicios con estándares de seguridad y calidad, de acuerdo con las condiciones ofrecidas y las obligaciones asumidas por la institución.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Concluir, en cualquier momento la relación con el banco, sin menoscabo del cumplimiento de sus obligaciones, ni de los cargos previamente pactados.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Exigir la debida diligencia en la prestación del servicio.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Confidencialidad en lo que respecta a su relación con el banco y su privacidad frente a terceros.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Presentar de manera respetuosa consultas, peticiones, solicitudes, quejas o reclamaciones y obtener respuestas oportunas.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Obligaciones o deberes de los clientes</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Informarse sobre los productos o servicios que desea recibir, conocer las condiciones generales de las operaciones, es decir, los derechos, obligaciones y costos, exigiendo las explicaciones verbales y escritas necesarias.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Suministrar información cierta, suficiente y oportuna en los momentos en que se le solicite.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Acudir al banco cuando se le solicite ante algún reclamo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Revisar los términos y condiciones del contrato o documento de la transacción realizada, conservando las copias de dichos documentos y las constancias de pagos realizados, los recibos o comprobantes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mantener al día sus pagos y adeudos, aunque existan reclamaciones pendientes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Informarse sobre las vías y canales de comunicación que dispone la institución para la gestión y atención de peticiones, solicitudes, quejas o reclamaciones.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mantener la disciplina, el respeto y el orden dentro de las oficinas, según las normas de comportamiento cívico.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Concurrir con un vestuario adecuado a las instalaciones bancarias, evitar el uso de short, camisetas, chancletas o prendas similares.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No realizar ni recibir llamadas por los teléfonos celulares durante su permanencia en las oficinas bancarias.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Derechos y deberes de los clientes', '', 'inherit', 'closed', 'closed', '', '1297-revision-v1', '', '', '2024-05-13 18:46:12', '2024-05-13 18:46:12', '', 1297, 'http://localhost/banco-actual/?p=1301', 0, 'revision', '', 0);
