s/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>La Debida Diligencia</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0a6e019c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0a6e019c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Representan medidas de debida diligencia, las prácticas y procesos para prevenir el uso indebido de los servicios bancarios de manera intencional o no, en la comisión de delitos de Lavado de Activos, Financiamiento al Terrorismo, a la Proliferación de Armas y otros con similar gravedad, al amparo del <strong>Decreto Ley 317 </strong>de<strong> 2014 </strong>y <strong>Resolución 51/2013 </strong>del<strong> Banco Central de Cuba </strong>(BCC).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dentro de estas acciones se incluyen, <strong>identificar</strong> y <strong>verificar</strong> la información del cliente y del beneficiario final, ya sean personas naturales o jurídicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es una<strong> práctica internacional </strong>aplicarla<strong> debida diligencia </strong>en los<strong> bancos </strong>y<strong> dentro de ella, establecer límites </strong>en las<strong> transacciones de los clientes,</strong>&nbsp;de acuerdo con la naturaleza de las operaciones, en atención a si estas se tratan de personas naturales o jurídicas, la cual se extiende a los países signatarios de las convenciones: <strong>Viena</strong> - Convención de Naciones Unidas contra el Tráfico Ilícito de Estupefacientes y Sustancias Controladas; <strong>Palermo</strong> - Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional; <strong>Mérida</strong> - Convención de Naciones Unidas contra la corrupción.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se pone en práctica correcta la <strong>Debida Diligencia</strong>, durante el momento de vincularse con el cliente, durante la prestación del servicio, convirtiéndose en la principal herramienta de trabajo del banco, en primer lugar, para el conocimiento real sobre el cliente y, en segundo lugar, para corroborar la correspondencia entre lo que se conoce y la naturaleza de las operaciones realizadas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para las <strong>operaciones</strong> de las <strong>cuentas personales</strong> relacionadas con <strong>salario</strong>, <strong>jubilación</strong>, <strong>ahorro</strong>, <strong>formación de fondos</strong> y <strong>colaboración</strong>, desde las cuales se ejecutan movimientos entre personas naturales, los límites actuales establecen <strong>diariamente por operación</strong> de hasta <strong>80 000 pesos cubanos</strong> (CUP), y un máximo de <strong>hasta 120 000 CUP al mes</strong>; en el caso de la <strong>moneda libremente convertible</strong> (MLC) el <strong>límite diario por operación</strong> es de <strong>hasta 1 000</strong>, y un máximo de <strong>hasta 5 000 al mes</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Son <strong>medidas </strong>que se<strong> dirigen </strong>a<strong> fortalecer </strong>el <strong>uso de las cuentas </strong>según su naturaleza, ya sean <strong>personales </strong>o<strong> corporativas </strong>y a<strong> establecer mayor trasparencia.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Los clientes que requieran realizar operaciones entre personas naturales por montos superiores a los especificados anteriormente, lo solicitan de manera presencial en las sucursales bancarias.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>personas naturales</strong> no tienen limitación alguna para transitar recursos financieros desde sus cuentas personales para ejecutar pagos a las personas jurídicas y otros agentes económicos por cualquier concepto (reservaciones en instalaciones turísticas, mercancías o servicios adquiridos, entre otros), lo cual transita sin restricción por los canales de pagos electrónicos, aspectos que se seguirán desarrollando por el sistema bancario y sin limitación para la actividad económica.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>transacciones</strong> que tienen lugar <strong>entre personas jurídicas</strong> y <strong>otros agentes de la economía</strong> desde sus <strong>cuentas corporativas</strong>, que son aquellas <strong>vinculadas a los negocios</strong> y se relacionan con los <strong>pagos y actividades autorizadas</strong> en su <strong>objeto social o empresarial</strong>, desde las cuales se establecen las <strong>obligaciones con el fisco</strong>, que son la de mayor volumen, <strong>NO</strong> se aplican limitaciones distintas a las relacionadas con su operatoria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Declaración sobre Origen y Destino</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>límites</strong> antes mencionados, se aplican en Cuba <strong>desde 1997</strong> y <strong>se han ido adecuando</strong> de acuerdo con el desarrollo del mercado financiero, en la actualidad, se <strong>adaptan</strong> al auge del uso de la <strong>tecnología digital</strong>, con vistas a <strong>preservar</strong> la <strong>disciplina del mercado</strong> y en modo alguno, constituyen limitaciones dirigidas a menoscabar los derechos sobre los recursos financieros, sino, se encaminan a reforzar la <strong>educación financiera</strong> de los ciudadanos y a evitar que puedan involucrarse, con conocimiento o no, en acciones ilícitas o en la evasión fiscal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los formularios vinculados con la <strong>Debida Diligencia</strong>,&nbsp;ofrecen información necesaria al <strong>Banco Metropolitano</strong> sobre el origen de los fondos que transitan por la institución. Estos se cumplimentan:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En el momento de abrir una cuenta mediante la confección del modelo <strong>CONOZCA A SU CLIENTE</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cumplimentar el modelo <strong>DECLARACION DE ORIGEN </strong>y <strong>DESTINO DE LOS FONDOS</strong> según lo establece la <strong>Instrucción 26/2022</strong> de la <strong>Oficina de Supervisión Bancaria</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Limites en las transacciones en efectivo</strong> de personas naturales en las sucursales bancarias, en el umbral de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El equivalente en <strong>moneda libremente convertible</strong> (MLC) a <strong>5 000.00 dólares estadounidenses</strong> (USD).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>125 000.00 pesos cubanos</strong> (CUP).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>A tenor de lo dispuesto en la propia Instrucción del <strong>Banco Central de Cuba</strong>, faculta al <strong>Banco Metropolitano</strong> y al resto de las <strong>instituciones financieras</strong>, la facultad de exigir evidencias documentales verificables de considerarlas necesarias a las personas naturales, según corresponda.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios', '', 'publish', 'closed', 'closed', '', 'medidas-practicas-y-procesos-para-prevenir-el-uso-indebido-de-los-servicios-bancarios', '', '', '2024-05-13 18:51:12', '2024-05-13 18:51:12', '', 0, 'http://localhost/banco-actual/?page_id=1302', 0, 'page', '', 0),
(1305, 1, '2024-05-13 18:50:51', '2024-05-13 18:50:51', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"columnsHeight\":\"custom\",\"columnsHeightCustom\":420,\"columnsHeightCustomMobile\":200,\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":500,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2023/11/slide-banca-movil.jpg\"},\"backgroundPosition\":{\"x\":0.55,\"y\":0.4},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"backgroundOverlayOpacity\":5,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-d86c0863\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-d86c0863\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>La Debida Diligencia</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0a6e019c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0a6e019c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Representan medidas de debida diligencia, las prácticas y procesos para prevenir el uso indebido de los servicios bancarios de manera intencional o no, en la comisión de delitos de Lavado de Activos, Financiamiento al Terrorismo, a la Proliferación de Armas y otros con similar gravedad, al amparo del <strong>Decreto Ley 317 </strong>de<strong> 2014 </strong>y <strong>Resolución 51/2013 </strong>del<strong> Banco Central de Cuba </strong>(BCC).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dentro de estas acciones se incluyen, <strong>identificar</strong> y <strong>verificar</strong> la información del cliente y del beneficiario final, ya sean personas naturales o jurídicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es una<strong> práctica internacional </strong>aplicarla<strong> debida diligencia </strong>en los<strong> bancos </strong>y<strong> dentro de ella, establecer límites </strong>en las<strong> transacciones de los clientes,</strong>&nbsp;de acuerdo con la naturaleza de las operaciones, en atención a si estas se tratan de personas naturales o jurídicas, la cual se extiende a los países signatarios de las convenciones: <strong>Viena</strong> - Convención de Naciones Unidas contra el Tráfico Ilícito de Estupefacientes y Sustancias Controladas; <strong>Palermo</strong> - Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional; <strong>Mérida</strong> - Convención de Naciones Unidas contra la corrupción.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se pone en práctica correcta la <strong>Debida Diligencia</strong>, durante el momento de vincularse con el cliente, durante la prestación del servicio, convirtiéndose en la principal herramienta de trabajo del banco, en primer lugar, para el conocimiento real sobre el cliente y, en segundo lugar, para corroborar la correspondencia entre lo que se conoce y la naturaleza de las operaciones realizadas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para las <strong>operaciones</strong> de las <strong>cuentas personales</strong> relacionadas con <strong>salario</strong>, <strong>jubilación</strong>, <strong>ahorro</strong>, <strong>formación de fondos</strong> y <strong>colaboración</strong>, desde las cuales se ejecutan movimientos entre personas naturales, los límites actuales establecen <strong>diariamente por operación</strong> de hasta <strong>80 000 pesos cubanos</strong> (CUP), y un máximo de <strong>hasta 120 000 CUP al mes</strong>; en el caso de la <strong>moneda libremente convertible</strong> (MLC) el <strong>límite diario por operación</strong> es de <strong>hasta 1 000</strong>, y un máximo de <strong>hasta 5 000 al mes</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Son <strong>medidas </strong>que se<strong> dirigen </strong>a<strong> fortalecer </strong>el <strong>uso de las cuentas </strong>según su naturaleza, ya sean <strong>personales </strong>o<strong> corporativas </strong>y a<strong> establecer mayor trasparencia.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Los clientes que requieran realizar operaciones entre personas naturales por montos superiores a los especificados anteriormente, lo solicitan de manera presencial en las sucursales bancarias.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>personas naturales</strong> no tienen limitación alguna para transitar recursos financieros desde sus cuentas personales para ejecutar pagos a las personas jurídicas y otros agentes económicos por cualquier concepto (reservaciones en instalaciones turísticas, mercancías o servicios adquiridos, entre otros), lo cual transita sin restricción por los canales de pagos electrónicos, aspectos que se seguirán desarrollando por el sistema bancario y sin limitación para la actividad económica.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>transacciones</strong> que tienen lugar <strong>entre personas jurídicas</strong> y <strong>otros agentes de la economía</strong> desde sus <strong>cuentas corporativas</strong>, que son aquellas <strong>vinculadas a los negocios</strong> y se relacionan con los <strong>pagos y actividades autorizadas</strong> en su <strong>objeto social o empresarial</strong>, desde las cuales se establecen las <strong>obligaciones con el fisco</strong>, que son la de mayor volumen, <strong>NO</strong> se aplican limitaciones distintas a las relacionadas con su operatoria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Declaración sobre Origen y Destino</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>límites</strong> antes mencionados, se aplican en Cuba <strong>desde 1997</strong> y <strong>se han ido adecuando</strong> de acuerdo con el desarrollo del mercado financiero, en la actualidad, se <strong>adaptan</strong> al auge del uso de la <strong>tecnología digital</strong>, con vistas a <strong>preservar</strong> la <strong>disciplina del mercado</strong> y en modo alguno, constituyen limitaciones dirigidas a menoscabar los derechos sobre los recursos financieros, sino, se encaminan a reforzar la <strong>educación financiera</strong> de los ciudadanos y a evitar que puedan involucrarse, con conocimiento o no, en acciones ilícitas o en la evasión fiscal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los formularios vinculados con la <strong>Debida Diligencia</strong>,&nbsp;ofrecen información necesaria al <strong>Banco Metropolitano</strong> sobre el origen de los fondos que transitan por la institución. Estos se cumplimentan:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En el momento de abrir una cuenta mediante la confección del modelo <strong>CONOZCA A SU CLIENTE</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cumplimentar el modelo <strong>DECLARACION DE ORIGEN </strong>y <strong>DESTINO DE LOS FONDOS</strong> según lo establece la <strong>Instrucción 26/2022</strong> de la <strong>Oficina de Supervisión Bancaria</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Limites en las transacciones en efectivo</strong> de personas naturales en las sucursales bancarias, en el umbral de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El equivalente en <strong>moneda libremente convertible</strong> (MLC) a <strong>5 000.00 dólares estadounidenses</strong> (USD).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>125 000.00 pesos cubanos</strong> (CUP).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>A tenor de lo dispuesto en la propia Instrucción del <strong>Banco Central de Cuba</strong>, faculta al <strong>Banco Metropolitano</strong> y al resto de las <strong>instituciones financieras</strong>, la facultad de exigir evidencias documentales verificables de considerarlas necesarias a las personas naturales, según corresponda.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios', '', 'inherit', 'closed', 'closed', '', '1302-revision-v1', '', '', '2024-05-13 18:50:51', '2024-05-13 18:50:51', '', 1302, 'http://localhost/banco-actual/?p=1305', 0, 'revision', '', 0),
(1306, 1, '2024-05-13 18:51:11', '2024-05-13 18:51:11', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"columnsHeight\":\"custom\",\"columnsHeightCustom\":420,\"columnsHeightCustomMobile\":200,\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":500,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2023/11/slide-banca-movil.jpg\"},\"backgroundPosition\":{\"x\":0.55,\"y\":0.4},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"backgroundOverlayOpacity\":5,\"backgroundOverlayColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f0bf6fda\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-d86c0863\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-d86c0863\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>La Debida Diligencia</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-1e97fb03\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0a6e019c\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0a6e019c\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Representan medidas de debida diligencia, las prácticas y procesos para prevenir el uso indebido de los servicios bancarios de manera intencional o no, en la comisión de delitos de Lavado de Activos, Financiamiento al Terrorismo, a la Proliferación de Armas y otros con similar gravedad, al amparo del <strong>Decreto Ley 317 </strong>de<strong> 2014 </strong>y <strong>Resolución 51/2013 </strong>del<strong> Banco Central de Cuba </strong>(BCC).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dentro de estas acciones se incluyen, <strong>identificar</strong> y <strong>verificar</strong> la información del cliente y del beneficiario final, ya sean personas naturales o jurídicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es una<strong> práctica internacional </strong>aplicarla<strong> debida diligencia </strong>en los<strong> bancos </strong>y<strong> dentro de ella, establecer límites </strong>en las<strong> transacciones de los clientes,</strong>&nbsp;de acuerdo con la naturaleza de las operaciones, en atención a si estas se tratan de personas naturales o jurídicas, la cual se extiende a los países signatarios de las convenciones: <strong>Viena</strong> - Convención de Naciones Unidas contra el Tráfico Ilícito de Estupefacientes y Sustancias Controladas; <strong>Palermo</strong> - Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional; <strong>Mérida</strong> - Convención de Naciones Unidas contra la corrupción.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se pone en práctica correcta la <strong>Debida Diligencia</strong>, durante el momento de vincularse con el cliente, durante la prestación del servicio, convirtiéndose en la principal herramienta de trabajo del banco, en primer lugar, para el conocimiento real sobre el cliente y, en segundo lugar, para corroborar la correspondencia entre lo que se conoce y la naturaleza de las operaciones realizadas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para las <strong>operaciones</strong> de las <strong>cuentas personales</strong> relacionadas con <strong>salario</strong>, <strong>jubilación</strong>, <strong>ahorro</strong>, <strong>formación de fondos</strong> y <strong>colaboración</strong>, desde las cuales se ejecutan movimientos entre personas naturales, los límites actuales establecen <strong>diariamente por operación</strong> de hasta <strong>80 000 pesos cubanos</strong> (CUP), y un máximo de <strong>hasta 120 000 CUP al mes</strong>; en el caso de la <strong>moneda libremente convertible</strong> (MLC) el <strong>límite diario por operación</strong> es de <strong>hasta 1 000</strong>, y un máximo de <strong>hasta 5 000 al mes</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Son <strong>medidas </strong>que se<strong> dirigen </strong>a<strong> fortalecer </strong>el <strong>uso de las cuentas </strong>según su naturaleza, ya sean <strong>personales </strong>o<strong> corporativas </strong>y a<strong> establecer mayor trasparencia.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Los clientes que requieran realizar operaciones entre personas naturales por montos superiores a los especificados anteriormente, lo solicitan de manera presencial en las sucursales bancarias.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>personas naturales</strong> no tienen limitación alguna para transitar recursos financieros desde sus cuentas personales para ejecutar pagos a las personas jurídicas y otros agentes económicos por cualquier concepto (reservaciones en instalaciones turísticas, mercancías o servicios adquiridos, entre otros), lo cual transita sin restricción por los canales de pagos electrónicos, aspectos que se seguirán desarrollando por el sistema bancario y sin limitación para la actividad económica.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Las <strong>transacciones</strong> que tienen lugar <strong>entre personas jurídicas</strong> y <strong>otros agentes de la economía</strong> desde sus <strong>cuentas corporativas</strong>, que son aquellas <strong>vinculadas a los negocios</strong> y se relacionan con los <strong>pagos y actividades autorizadas</strong> en su <strong>objeto social o empresarial</strong>, desde las cuales se establecen las <strong>obligaciones con el fisco</strong>, que son la de mayor volumen, <strong>NO</strong> se aplican limitaciones distintas a las relacionadas con su operatoria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Declaración sobre Origen y Destino</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los <strong>límites</strong> antes mencionados, se aplican en Cuba <strong>desde 1997</strong> y <strong>se han ido adecuando</strong> de acuerdo con el desarrollo del mercado financiero, en la actualidad, se <strong>adaptan</strong> al auge del uso de la <strong>tecnología digital</strong>, con vistas a <strong>preservar</strong> la <strong>disciplina del mercado</strong> y en modo alguno, constituyen limitaciones dirigidas a menoscabar los derechos sobre los recursos financieros, sino, se encaminan a reforzar la <strong>educación financiera</strong> de los ciudadanos y a evitar que puedan involucrarse, con conocimiento o no, en acciones ilícitas o en la evasión fiscal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los formularios vinculados con la <strong>Debida Diligencia</strong>,&nbsp;ofrecen información necesaria al <strong>Banco Metropolitano</strong> sobre el origen de los fondos que transitan por la institución. Estos se cumplimentan:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En el momento de abrir una cuenta mediante la confección del modelo <strong>CONOZCA A SU CLIENTE</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cumplimentar el modelo <strong>DECLARACION DE ORIGEN </strong>y <strong>DESTINO DE LOS FONDOS</strong> según lo establece la <strong>Instrucción 26/2022</strong> de la <strong>Oficina de Supervisión Bancaria</strong>.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Limites en las transacciones en efectivo</strong> de personas naturales en las sucursales bancarias, en el umbral de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El equivalente en <strong>moneda libremente convertible</strong> (MLC) a <strong>5 000.00 dólares estadounidenses</strong> (USD).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>125 000.00 pesos cubanos</strong> (CUP).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>A tenor de lo dispuesto en la propia Instrucción del <strong>Banco Central de Cuba</strong>, faculta al <strong>Banco Metropolitano</strong> y al resto de las <strong>instituciones financieras</strong>, la facultad de exigir evidencias documentales verificables de considerarlas necesarias a las personas naturales, según corresponda.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Medidas, prácticas y procesos para prevenir el uso indebido de los servicios bancarios', '', 'inherit', 'closed', 'closed', '', '1302-revision-v1', '', '', '2024-05-13 18:51:11', '2024-05-13 18:51:11', '', 1302, 'http://localhost/banco-actual/?p=1306', 0, 'revision', '', 0),
