s/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\",\"columns\":2,\"layout\":\"equal\",\"layoutTablet\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1140,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"ticss-af0b49bf has-light-bg\",\"hasCustomCSS\":true,\"customCSS\":\".ticss-af0b49bf {\\nz-index: 999;\\n}\\n\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-9a38cbaa\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-twoOne-layout has-mobile-collapsedRows-layout has-vertical-unset ticss-af0b49bf has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-ea20ba02\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"80px\",\"right\":\"80px\"},\"paddingTablet\":{},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Facilidades en la atención a los jubilados y pensionados</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Servicios a Jubilados y Pensionados</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-0a740066\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-0a740066\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0a3d8ef8\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0a3d8ef8\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El <strong>Calendario</strong><strong> </strong><strong>de</strong><strong> </strong><strong>pago</strong><strong> </strong><strong>a jubilados y pensionados de la seguridad social</strong>, es una matriz en <strong>cinco grupos</strong>,<strong> </strong>donde se organizan las fechas, según el monto a cobrar por el cliente y el año de nacimiento del beneficiario.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El <strong>Banco Metropolitano</strong> mantiene una <strong>atención priorizada</strong> a ese sensible segmento poblacional, durante los días de pago del calendario, en el horario de <strong>8:30 a.m. </strong>a las <strong>11:00 a.m.</strong> Luego de este horario, se continúa atendiendo a los jubilados y al resto de los clientes, hasta concluir el servicio del día.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Fechas de pago a jubilados y pensionados por nómina electrónica</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pueden cobrar en una de las sucursales ubicadas en el mismo municipio de residencia. Podrán acumular el mes de pago y el mes anterior. La <strong>nómina electrónica </strong>tiene una <strong>fecha de inicio </strong>y <strong>otra de culminación</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los que acudan a las sucursales del <strong>Banco Metropolitano </strong>a cobrar sus pensiones, deberán presentar su carné de identidad y la matriz de la chequera, si la poseen, ya que en ella aparece el número de control bancario e identificador de la seguridad social.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>Valor agregado:</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>&nbsp;</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Los <strong>jubilados</strong> y <strong>pensionados</strong> que cobran a través de los <strong>cajeros automáticos</strong>, también se acogen a la <strong>programación de pago</strong> del <strong>calendario</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los que les corresponda cobrar los <strong>sábados</strong>, si lo desean, lo pueden hacer desde el <strong>viernes</strong> anterior.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los beneficiarios con <strong>créditos otorgados</strong> por el banco, pueden pagar su <strong>deuda</strong> mensual en una de las sucursales de su municipio de residencia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pueden cobrar durante cualquier día del mes, siempre a partir de la fecha que le corresponda según el <strong>calendario de pago</strong> en los <strong>cajeros automáticos</strong>, las <strong>sucursales </strong>del<strong> Banco Metropolitano</strong>, en las oficinas comerciales de <strong>Correos de Cuba</strong> y en las sucursales de<strong> CADECA</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Se mantiene la vigencia de la <strong>Providencia</strong> y el <strong>Autorizo para Actuar por Cuenta Ajena</strong>, emitidos por las sedes municipales del <strong>Instituto Nacional de Seguridad Social</strong> (INASS) en los casos de los jubilados y pensionados que <strong>no cobran</strong> sus pensiones de manera personal. El <strong>periodo de validez</strong> de los documentos es de <strong>uno </strong>a <strong>dos años</strong>, permitiéndole a terceros, realizar el trámite de cobro.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Los <strong>beneficiarios</strong> de la <strong>seguridad social</strong> que no se encuentren en su municipio o provincia de residencia, deberán presentarse en las <strong>sedes</strong><strong> </strong><strong>municipales</strong> del <strong>INASS</strong> a solicitar, para cobrar, el traslado correspondiente. Una vez de regreso a su lugar de origen, deberán acudir a la <strong>filial municipal</strong> de su localidad.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Facilidades en la atención a los jubilados y pensionados', '', 'inherit', 'closed', 'closed', '', '1325-revision-v1', '', '', '2024-05-13 20:18:06', '2024-05-13 20:18:06', '', 1325, 'http://localhost/banco-actual/?p=1328', 0, 'revision', '', 0);
