er[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-input-field input {\n      color: var(--nv-text-color) !important;\n      font-family: \"Arial\" !important;\n      font-size: 14px !important;\n      font-weight: 400 !important;\n      line-height: 20px !important;\n      text-align: center !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-input-field input::placeholder {\n      color: var(--nv-text-color) !important;\n      opacity: 1 !important;\n    }\n    \n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-input-field input:-ms-input-placeholder {\n      color: #000000 !important;\n    }\n    \n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-input-field input::-ms-input-placeholder {\n      color: #000000 !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-submit-button {\n      margin-top: 10px !important;\n      width: 100% !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-submit-button button {\n      width: 100% !important;\n      height: 40px !important;\n      border: 0 !important;\n      border-radius: 0px !important;\n      line-height: 0px !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .form-preview .preview-submit-button button:hover {\n      cursor: pointer !important;\n      background-color: var(--nv-secondary-accent);\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .powered-by-line {\n      color: #231f20 !important;\n      font-family: \"Arial\" !important;\n      font-size: 13px !important;\n      font-weight: 400 !important;\n      line-height: 25px !important;\n      text-align: center !important;\n      text-decoration: none !important;\n      display: flex !important;\n      width: 100% !important;\n      justify-content: center !important;\n      align-items: center !important;\n      margin-top: 10px !important;\n    }\n    .followit--follow-form-container[attr-a][attr-b][attr-c][attr-d][attr-e][attr-f] .powered-by-line img {\n      margin-left: 10px !important;\n      height: 1.13em !important;\n      max-height: 1.13em !important;\n    }\n    </style><div class=\"followit--follow-form-container\" attr-a=\"\" attr-b=\"\" attr-c=\"\" attr-d=\"\" attr-e=\"\" attr-f=\"\"><form data-v-390679af=\"\" action=\"https://api.follow.it/subscribe?pub=a6Lh6PN9w3iW6I80Efmg-g\" method=\"post\"><div data-v-390679af=\"\" class=\"form-preview\" style=\"background-color: var(--nv-site-bg); position: relative;\"> <div data-v-390679af=\"\" class=\"preview-input-field\"><input data-v-390679af=\"\" type=\"email\" name=\"email\" required=\"required\" placeholder=\"awesomemail@gmail.com\" spellcheck=\"false\" style=\"text-transform: none !important; font-family: Arial; font-weight: normal; color: var(--nv-text-color); font-size: 14px; text-align: center; background-color: rgb(255, 255, 255);\"></div> <div data-v-390679af=\"\" class=\"preview-submit-button\"><button data-v-390679af=\"\" type=\"submit\" style=\"text-transform: none !important; font-family: Arial; font-weight: bold; color: rgb(255, 255, 255); font-size: 16px; text-align: center; background-color: var(--nv-primary-accent);\">Suscríbete</button></div></div></form><a href=\"https://follow.it\" class=\"powered-by-line\"> <img src=\"https://follow.it/static/img/colored-logo.svg\" alt=\"follow.it\" height=\"17px\"></a></div>\n<!-- /wp:html --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Inicio', '', 'inherit', 'closed', 'closed', '', '316-revision-v1', '', '', '2024-05-14 16:09:40', '2024-05-14 16:09:40', '', 316, 'http://local