"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\"><strong>Cuentas de CERTIFICADO DE DEPÓSITO A TÉRMINO</strong></h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Personal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-00690a1a\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-00690a1a\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-85793d53\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-85793d53\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Son instrumentos de ahorro, que por sus características particulares constituyen&nbsp;una modalidad especial del Depósito a Plazo Fijo y se aceptan como negociación por los Bancos del Sistema Bancario Nacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>No admite designación de beneficiarios ni en los de tipo individual;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El importe mínimo de apertura es de 100,00 CUP o 500,00 USD y son negociables solamente en el territorio nacional;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Devengan intereses fijos de acuerdo a las tasas vigentes en el momento de la apertura y de acuerdo al contrato con el titular, los plazos podrán ser de 3, 6, 12, 24, 36, 48, 60 y los intereses desde el 2 hasta el 6.50 % con el principio de, a mayor plazo mayor interés. Las operaciones de cierre y cobro de interés se pueden hacer en cualquier sucursal del mismo centro contable que la oficina de apertura y podrán cobrarse en efectivo o depositarse en una cuenta de ahorro a la vista;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En los plazos de 3, 6 y 12 meses si se interrumpe antes de haber concurrido el 50 % del término pactado, sólo se le pagará el principal y pierde el derecho al cobro del interés;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si ha transcurrido el 50 % o más del término pactado, se le pagará el importe principal y el 50% del interés acumulado hasta el cierre del día anterior;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si ha transcurrido el 100 % del término pactado, se le pagará el importe principal y el 100% del interés acumulado hasta el cierre del certificado;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Para los plazos de 24, 36 y 60 meses si se interrumpe antes de haber transcurrido el 25% del término pactado, sólo se le pagará el importe principal y pierde el derecho al cobro del interés;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si ha transcurrido el 25% o más del término pactado, se le pagará el importe principal y el 50% de interés acumulado hasta el cierre del día anterior;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si ha transcurrido el 100% del término pactado, se le pagará el importe principal y el 100% interés acumulado hasta el cierre;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sólo son prorrogables con la presencia del titular o titulares, los que deben presentarse en la sucursal de apertura en la fecha del vencimiento del certificado;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Todas las operaciones de endoso y cancelación, se efectuarán en la sucursal de apertura.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Valor agregado:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Puede constituirse como garantía de créditos bancarios.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas de Certificado de Depósito a Término', '', 'inherit', 'closed', 'closed', '', '999-revision-v1', '', '', '2024-05-14 21:35:29', '2024-05-14 21:35:29', '', 999, 'http://localhost/banco-actual/?p=1428', 0, 'revision', '', 0);
