"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Cuentas CORRIENTES y cuentas CORRIENTES FISCALES para formas de gestión no estatal</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Banca Corporativa</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-579fa5ae\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-579fa5ae\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-21f0f9ea\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-21f0f9ea\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><strong>Cuentas CORRIENTES y cuentas CORRIENTES FISCALES para cooperativas no agropecuarias, mipymes, trabajadores por cuenta propia, pequeños agricultores y otras formas de gestión no estatal</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuentas donde se acreditan ingresos y se debitan los pagos que se ejecutan por decisión propia o por decisiones legales de terceros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los TCP, APE y GNE pueden operar cuentas corrientes en pesos cubanos (CUP) y en dólares estadounidenses (USD), para la cual no necesitan autorización del <strong>BCC</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Los titulares de cuentas corrientes pueden facultar a otras personas naturales mediante poder notarial, para actuar como firma autorizada de la cuenta.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pueden autorizar, además, sin cumplir el requisito anterior, a otras personas naturales a realizar depósitos en sus cuentas, así como a entregar y recibir documentos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Dichas cuentas como norma no devengarán intereses.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El banco emitirá un <strong>Estado de Cuentas</strong> mensuales sin costo alguno para el cliente. Si el cliente los solicita diarios, semanales y quincenales se les cobra una comisión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para la apertura de la cuenta el banco exigirá la presentación de los documentos establecidos en la legislación vigente según el status legal de la entidad jurídica, TCP, CNA, APE, Mipymes y GNE.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los titulares de estas cuentas son responsables de depositar solamente los fondos obtenidos por las actividades autorizadas, según la legislación vigente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El flujo de las cuentas corrientes puede ser dado en garantía para los créditos que soliciten los titulares de las cuentas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Cuentas corrientes fiscales (Resolución 904/2018 del Ministerio de Finanzas y Precios (MFP):</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Las <strong>cuentas CORRIENTES FISCALES</strong> solo podrán tener titularidad individual.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Actividades obligadas a operar cuenta fiscal.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Servicios gastronómicos en restaurantes,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Servicios gastronómicos en cafeterías,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Servicio de bar y recreación,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Arrendadores de viviendas, habitaciones o espacios,</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Servicios de construcción, reparación y mantenimiento de inmuebles.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Transporte de carga y pasajeros.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>La apertura de estas cuentas tendrá lugar en una de las sucursales radicadas en el municipio del domicilio fiscal, o sea en el municipio donde se encuentre inscrito en la ONAT.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La cuenta bancaria fiscal se apertura en pesos cubanos (CUP) y debe mantener un saldo mínimo equivalente a dos (2) cuotas mensuales a cuenta del Impuesto sobre los Ingresos Personales, a cuyo pago está obligado su titular. En caso de que al cierre del mes el saldo mínimo de esta cuenta sea inferior al establecido, por operaciones vinculadas al ejercicio de la actividad económica, su titular dispone de un término de cinco (5) días hábiles para restablecer el mencionado saldo mínimo.&nbsp;</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Cuentas CORRIENTES y cuentas CORRIENTES FISCALES', '', 'inherit', 'closed', 'closed', '', '1198-autosave-v1', '', '', '2024-05-14 21:58:01', '2024-05-14 21:58:01', '', 1198, 'http://localhost/banco-actual/?p=1436', 0, 'revision', '', 0),
