(1574, 1, '2024-05-21 17:46:34', '2024-05-21 17:46:34', '<!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":80,\"overlayColor\":\"nv-light-bg\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.46,\"y\":0.76},\"minHeight\":281,\"minHeightUnit\":\"px\",\"contentPosition\":\"bottom center\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-custom-content-position is-position-bottom-center\" style=\"padding-top:0px;padding-bottom:0px;min-height:281px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-nv-light-bg-background-color has-background-dim-80 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66.66%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:20px;padding-right:10px;padding-bottom:20px;padding-left:10px;flex-basis:66.66%\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"textColor\":\"neve-text-color\"} -->\n<h1 class=\"wp-block-heading has-text-align-left has-neve-text-color-color has-text-color\">Tipo de Cambio</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-text-align-left has-neve-text-color-color has-text-color\">Moneda Libremente Convertible vs Peso Cubano</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:themeisle-blocks/font-awesome-icons {\"id\":\"wp-block-themeisle-blocks-font-awesome-icons-d2a287da\",\"align\":{\"desktop\":\"flex-start\"},\"prefix\":\"far\",\"icon\":\"calendar-alt\",\"textColor\":\"var(\\u002d\\u002dnv-secondary-accent)\"} -->\n<div id=\"wp-block-themeisle-blocks-font-awesome-icons-d2a287da\" class=\"wp-block-themeisle-blocks-font-awesome-icons\"><span class=\"wp-block-themeisle-blocks-font-awesome-icons-container\"><i class=\"far fa-calendar-alt\"></i></span></div>\n<!-- /wp:themeisle-blocks/font-awesome-icons -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|neve-text-color\"}}}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color has-link-color\">Vigente Hasta:22/05/2024</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-ffa404f9\",\"columns\":1,\"layout\":\"equal\",\"margin\":{\"top\":\"10px\",\"bottom\":\"10px\"},\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-ffa404f9\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-89af68a0\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-89af68a0\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>Usted puede consultar los Tipos de Cambio de Monedas utilizando los siguientes canales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li> En la aplicación Transfermóvil del servicio Banca Móvil, por la opción <strong>CONSULTAS</strong>/<strong>TIPO DE CAMBIO</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Perfil institucional en Twitter, Telegram, Facebook: @BanmetCuba.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li> En la Web oficial <a href=\"http://www.banco-metropolitano.com.cu/\" target=\"_blank\" rel=\"noreferrer noopener\">www.banco-metropolitano.com.cu</a> </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>SMS</strong> al <strong>8888</strong> con el texto <strong>CAMBIO</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Por el centro de llamadas de <strong>Telebanca</strong> por los números telefónicos <strong>7868-3535</strong> y <strong>7866-0606</strong>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>En la sucursal más cercana o de su preferencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Tipo de Cambio', '', 'inherit', 'closed', 'closed', '', '730-revision-v1', '', '', '2024-05-21 17:46:34', '2024-05-21 17:46:34', '', 730, 'http://localhost/banco-actual/?p=1574', 0, 'revision', '', 0),
