ows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-28c3d287\",\"padding\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"40px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-28c3d287\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-a02f8e43\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"fontSize\":\"18px\",\"marginBottom\":20,\"marginBottomMobile\":14,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-a02f8e43\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-a02f8e43\">ACTIVO LAS 24 HORAS  </h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-e0cd839c\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":20,\"marginBottomMobile\":10,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-e0cd839c\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-e0cd839c\">Telebanca</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Telebanca puede utilizarse desde cualquier teléfono, privado o público y permite el pago de más de una factura, que puede ser suya o de otra persona, con cargo a la tarjeta magnética del que lo solicita si el saldo disponible lo permite.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-64136abe\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"backgroundType\":\"image\",\"backgroundImage\":{\"id\":555,\"url\":\"http://localhost/banco-actual/wp-content/uploads/2024/01/telebanca.jpg\"},\"backgroundPosition\":{\"x\":\"0.50\",\"y\":\"0.50\"},\"backgroundRepeat\":\"no-repeat\",\"backgroundSize\":\"cover\",\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-64136abe\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:spacer {\"height\":\"250px\"} -->\n<div style=\"height:250px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanc