(1662, 1, '2024-05-24 16:19:18', '2024-05-24 16:19:18', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\",\"columns\":2,\"layout\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-twoOne-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-78c641ed\",\"padding\":{\"top\":\"40px\",\"bottom\":\"0px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"66.66\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-78c641ed\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-ce95b243\",\"tag\":\"span\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"fontSize\":\"14px\",\"letterSpacing\":4,\"marginBottomMobile\":15,\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-ce95b243\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-ce95b243\">¿<strong>QUÉ NECESITAS CONOCER?</strong> </span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":50,\"marginBottomMobile\":45,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8c6e4149\">Preguntas Frecuentes</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8dbcc3ca has-light-bg\"><strong><strong>Transferencias bancarias desde el exterior</strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-26dc5bab\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-26dc5bab\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El código que utiliza es el SWIFT: BMNBCUHH. No utiliza los códigos BIC o IBAN.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La comisión es 0,5 %. Si el dinero es a depositar en una cuenta en el banco: mínimo 5,00 CUC – máximo 100,00 CUC. Si es a cobrar en efectivo: mínimo 6,00 CUC – máximo 300,00 CUC.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El Banco no cobra comisión por estas transacciones.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>VISA Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>MASTERCARD Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>VISA y MASTERCARD International NO PERSONALIZADAS.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AMERICAN INTERNATIONAL SERVICE (AIS).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AIS – RIA.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>TRAN$CARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>CABAL.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>UNIONPAY.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>OCEANCARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>BANCEL (BFI).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Dónde opera el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Dónde opera el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Operamos en la capital del país, es decir, La Habana.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué debe conocer una persona para enviar una transferencia bancaria?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué debe conocer una persona para enviar una transferencia bancaria?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Para enviar la transferencia bancaria o remesa de dinero a Cuba, el interesado debe dirigirse a la sucursal bancaria más cercana de la ciudad o localidad donde se encuentre, solicitando el envío a través de uno de los <a href=\"http://www.banco-metropolitano.com.cu/bancos-corresponsales/\">bancos corresponsales</a> del <strong>Banco Metropolitano</strong> que se informan en la <strong>Web oficial</strong> o en la aplicación <strong>Banmet APK</strong>. <strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Datos necesarios:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre:</strong> Banco Metropolitano S.A.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT:</strong> BMNBCUHH. No utilizamos códigos BIC o IBAN.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de la cuenta bancaria o de la tarjeta magnética.</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si no posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dirección de residencia:</strong> calle o avenida, número de la casa o apartamento, entre calles, reparto o localidad, código postal, municipio, provincia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de identidad personal:</strong> carné de identidad o pasaporte.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teléfono</strong>: donde se pueda localizar al beneficiario de la transferencia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT del Banco Metropolitano:</strong> BMNBCUHH.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código </strong><strong><a href=\"http://www.banco-metropolitano.com.cu/directorio-red-de-sucursales/\">de la sucursal</a></strong>: donde desea cobrar la transferencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Para enviar la transferencia bancaria o remesa de dinero a Cuba:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"start\":1} -->\n<ol start=\"1\"><!-- wp:list-item -->\n<li>Al enviar la transferencia a beneficiarios residentes en La Habana, deberá especificar al banco ordenante que su interés es enviar el dinero a través del <strong>Banco Metropolitano, S.A.</strong> De utilizarse otros bancos comerciales, se incrementan los gastos por comisiones.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También gestionamos transferencias hacia el resto del país.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Importante:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Antes de ordenar la transferencia en el banco emisor, se debe revisar detalladamente todos los datos del beneficiario en Cuba, para evitar demoras o molestias. </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las transferencias bancarias o remesas de dinero pueden enviarse para depositarse en cuentas en CUP (al tipo de cambio vigente) o en USD. También a cuentas en USD con respaldo en monedas libremente convertibles (MLC), habilitadas para las compras de bienes y servicios en establecimientos comerciales en esa moneda.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También pueden cobrarse en efectivo en la sucursal bancaria que elija el beneficiario.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si el beneficiario tiene una cuenta en el <strong>Banco Metropolitano, S.A.</strong> se le cobrarán comisiones más económicas, aunque no es necesaria para recibir dinero desde otro país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contamos con sucursales en los 15 municipios de la capital.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El beneficiario puede cobrar el dinero en Euros, en efectivo, si la transferencia está denominada en esa moneda originalmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿A quién reclamar en caso de error en una transferencia?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿A quién reclamar en caso de error en una transferencia?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La persona que envía el dinero debe acudir al banco donde ordenó la transferencia y enmendar el error de los datos del beneficiario en Cuba. Como corresponde en los procedimientos bancarios, es el banco emisor quien enviará la modificación del mensaje con los arreglos realizados. O sea, la solicitud de modificación se realizará de Banco a Banco.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Debe dirigirse a su sucursal bancaria y solicitar se realice la transferencia a través de uno de nuestros bancos corresponsales que aparecen publicados en este sitio Web.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Puede recibir la transferencia en Euro, para cobrar en efectivo, si está denominada en esa moneda y haya disponibilidad en la sucursal cuando el beneficiario acuda a cobrar la remesa. Si la transferencia se ordena a una cuenta de ahorro, esta se deposita en pesos cubanos (CUP) o dólares estadounidenses (USD) con respaldo en moneda libremente convertible (MLC), según el tipo corresponda.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-fd0c65ac has-light-bg\"><strong><strong><strong>Cuentas en USD con respaldo en moneda libremente convertible (MLC)</strong></strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-4645f51c\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-4645f51c\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>En la sucursal bancaria de su preferencia.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las personas naturales residentes permanentes en el territorio nacional, solo con la presentación de su carné de identidad.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No se exige un saldo mínimo, es decir, pueden abrirse con saldo cero.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El importe y cantidad de operaciones por día de la cuenta asociada a la tarjeta magnética, la puede definir el cliente en el momento de abrir la cuenta. En los casos en que no se precisa por el solicitante, los bancos la definen por oficio como medida de seguridad en caso de pérdida de su tarjeta. Este límite puede ser cambiado en cualquier momento por el titular de la tarjeta.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo se pueden cambiar los límites de las operaciones diarias?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo se pueden cambiar los límites de las operaciones diarias?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Los límites de operaciones diarias, tanto la cantidad de éstas, como el importe diario se modifican por el titular de la tarjeta utilizando las vías siguientes:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En la sucursal bancaria donde abrió la cuenta si desea que los cambios sean permanentes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Por la aplicación Transfermóvil, del servicio Banca MÓVIL, con una duración de 24 horas.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Pueden abrirse sin efectuar un depósito inicial y no tendrán saldo mínimo. No devengan intereses, ni se cobran comisiones por su utilización. No tienen el beneficio de la bonificación que el Banco Metropolitano S.A. aplica a otras tarjetas RED. Es un medio de pago que da acceso a las compras en los comercios habilitados para la venta de mercancías en dólares estadounidenses (USD).</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Además de utilizarse para la compra de mercancías en USD en los comercios habilitados con ese propósito, puede utilizar la tarjeta en el resto de los servicios disponibles por el Banco Metropolitano S.A. a través de los canales electrónicos de pago: compra por los terminales de puntos de venta (TPV o POS), pago de servicios públicos, comercios y oficinas comerciales, extraer dinero en efectivo por los cajeros automáticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En el caso del pago de bienes y servicios en comercios en CUP y extracciones por los cajeros automáticos, se aplica el tipo de cambio oficial vigente.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No. Las tarjetas magnéticas RED emitidas por el Banco Metropolitano S.A. son válidas exclusivamente para operaciones en el territorio nacional.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Sí. Puede asociar la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca, para su autenticación en los canales electrónicos de cobros y pagos.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-10be9dbd\",\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"20px\",\"right\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"33.34\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-10be9dbd\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:image {\"id\":830,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-circle-mask is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-style-circle-mask is-style-rounded\"><img src=\"http://localhost/banco-actual/wp-content/uploads/2024/05/b-corporativa.jpg\" alt=\"\" class=\"wp-image-830\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\",\"tag\":\"h3\",\"align\":\"center\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-dcb009c0\">FAQs</h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-c9309dda\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-c9309dda\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-c9309dda\">Atención a clientes</span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8125decd\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"16px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-8125decd\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8125decd\"><strong><strong>7868-3535</strong> / <strong>7866-0606</strong></strong></span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/button-group {\"id\":\"wp-block-themeisle-blocks-button-group-b10d43a4\",\"align\":\"center\",\"spacing\":0,\"paddingTopBottom\":10,\"paddingLeftRight\":20,\"fontSize\":13} -->\n<div id=\"wp-block-themeisle-blocks-button-group-b10d43a4\" class=\"wp-block-themeisle-blocks-button-group wp-block-buttons align-center\"><!-- wp:themeisle-blocks/button {\"id\":\"wp-block-themeisle-blocks-button-f5de91a7\",\"color\":\"\",\"background\":\"var(\\u002d\\u002dnv-primary-accent)\",\"border\":\"\",\"hoverColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"hoverBackground\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"hoverBorder\":\"\",\"borderRadius\":0,\"boxShadowColor\":\"\",\"hoverBoxShadowColor\":\"\",\"prefix\":\"\",\"icon\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-button-f5de91a7\" class=\"wp-block-themeisle-blocks-button wp-block-button\"><a href=\"\" target=\"_self\" rel=\"noopener noreferrer\" class=\"wp-block-button__link\"><span>MAS INFORMACION</span></a></div>\n<!-- /wp:themeisle-blocks/button --></div>\n<!-- /wp:themeisle-blocks/button-group --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Preguntas Frecuentes', '', 'inherit', 'closed', 'closed', '', '1616-revision-v1', '', '', '2024-05-24 16:19:18', '2024-05-24 16:19:18', '', 1616, 'http://localhost/banco-actual/?p=1662', 0, 'revision', '', 0);
INSERT INTO `banmetx_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1664, 1, '2024-05-24 16:20:48', '2024-05-24 16:20:48', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\",\"columns\":2,\"layout\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-twoOne-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-78c641ed\",\"padding\":{\"top\":\"40px\",\"bottom\":\"0px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"66.66\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-78c641ed\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-ce95b243\",\"tag\":\"span\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"fontSize\":\"14px\",\"letterSpacing\":4,\"marginBottomMobile\":15,\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-ce95b243\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-ce95b243\">¿<strong>QUÉ NECESITAS CONOCER?</strong> </span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":50,\"marginBottomMobile\":45,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8c6e4149\">Preguntas Frecuentes</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8dbcc3ca has-light-bg\"><strong><strong>Transferencias bancarias desde el exterior</strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-26dc5bab\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-26dc5bab\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El código que utiliza es el SWIFT: BMNBCUHH. No utiliza los códigos BIC o IBAN.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La comisión es 0,5 %. Si el dinero es a depositar en una cuenta en el banco: mínimo 5,00 CUC – máximo 100,00 CUC. Si es a cobrar en efectivo: mínimo 6,00 CUC – máximo 300,00 CUC.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El Banco no cobra comisión por estas transacciones.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>VISA Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>MASTERCARD Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>VISA y MASTERCARD International NO PERSONALIZADAS.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AMERICAN INTERNATIONAL SERVICE (AIS).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AIS – RIA.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>TRAN$CARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>CABAL.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>UNIONPAY.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>OCEANCARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>BANCEL (BFI).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Dónde opera el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Dónde opera el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Operamos en la capital del país, es decir, La Habana.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué debe conocer una persona para enviar una transferencia bancaria?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué debe conocer una persona para enviar una transferencia bancaria?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Para enviar la transferencia bancaria o remesa de dinero a Cuba, el interesado debe dirigirse a la sucursal bancaria más cercana de la ciudad o localidad donde se encuentre, solicitando el envío a través de uno de los <a href=\"http://www.banco-metropolitano.com.cu/bancos-corresponsales/\">bancos corresponsales</a> del <strong>Banco Metropolitano</strong> que se informan en la <strong>Web oficial</strong> o en la aplicación <strong>Banmet APK</strong>. <strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Datos necesarios:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre:</strong> Banco Metropolitano S.A.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT:</strong> BMNBCUHH. No utilizamos códigos BIC o IBAN.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de la cuenta bancaria o de la tarjeta magnética.</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si no posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dirección de residencia:</strong> calle o avenida, número de la casa o apartamento, entre calles, reparto o localidad, código postal, municipio, provincia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de identidad personal:</strong> carné de identidad o pasaporte.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teléfono</strong>: donde se pueda localizar al beneficiario de la transferencia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT del Banco Metropolitano:</strong> BMNBCUHH.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código </strong><strong><a href=\"http://www.banco-metropolitano.com.cu/directorio-red-de-sucursales/\">de la sucursal</a></strong>: donde desea cobrar la transferencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Para enviar la transferencia bancaria o remesa de dinero a Cuba:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"start\":1} -->\n<ol start=\"1\"><!-- wp:list-item -->\n<li>Al enviar la transferencia a beneficiarios residentes en La Habana, deberá especificar al banco ordenante que su interés es enviar el dinero a través del <strong>Banco Metropolitano, S.A.</strong> De utilizarse otros bancos comerciales, se incrementan los gastos por comisiones.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También gestionamos transferencias hacia el resto del país.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Importante:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Antes de ordenar la transferencia en el banco emisor, se debe revisar detalladamente todos los datos del beneficiario en Cuba, para evitar demoras o molestias. </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las transferencias bancarias o remesas de dinero pueden enviarse para depositarse en cuentas en CUP (al tipo de cambio vigente) o en USD. También a cuentas en USD con respaldo en monedas libremente convertibles (MLC), habilitadas para las compras de bienes y servicios en establecimientos comerciales en esa moneda.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También pueden cobrarse en efectivo en la sucursal bancaria que elija el beneficiario.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si el beneficiario tiene una cuenta en el <strong>Banco Metropolitano, S.A.</strong> se le cobrarán comisiones más económicas, aunque no es necesaria para recibir dinero desde otro país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contamos con sucursales en los 15 municipios de la capital.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El beneficiario puede cobrar el dinero en Euros, en efectivo, si la transferencia está denominada en esa moneda originalmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿A quién reclamar en caso de error en una transferencia?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿A quién reclamar en caso de error en una transferencia?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La persona que envía el dinero debe acudir al banco donde ordenó la transferencia y enmendar el error de los datos del beneficiario en Cuba. Como corresponde en los procedimientos bancarios, es el banco emisor quien enviará la modificación del mensaje con los arreglos realizados. O sea, la solicitud de modificación se realizará de Banco a Banco.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Debe dirigirse a su sucursal bancaria y solicitar se realice la transferencia a través de uno de nuestros bancos corresponsales que aparecen publicados en este sitio Web.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Puede recibir la transferencia en Euro, para cobrar en efectivo, si está denominada en esa moneda y haya disponibilidad en la sucursal cuando el beneficiario acuda a cobrar la remesa. Si la transferencia se ordena a una cuenta de ahorro, esta se deposita en pesos cubanos (CUP) o dólares estadounidenses (USD) con respaldo en moneda libremente convertible (MLC), según el tipo corresponda.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-fd0c65ac has-light-bg\"><strong><strong><strong>Cuentas en USD con respaldo en moneda libremente convertible (MLC)</strong></strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-4645f51c\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-4645f51c\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>En la sucursal bancaria de su preferencia.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las personas naturales residentes permanentes en el territorio nacional, solo con la presentación de su carné de identidad.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No se exige un saldo mínimo, es decir, pueden abrirse con saldo cero.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El importe y cantidad de operaciones por día de la cuenta asociada a la tarjeta magnética, la puede definir el cliente en el momento de abrir la cuenta. En los casos en que no se precisa por el solicitante, los bancos la definen por oficio como medida de seguridad en caso de pérdida de su tarjeta. Este límite puede ser cambiado en cualquier momento por el titular de la tarjeta.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo se pueden cambiar los límites de las operaciones diarias?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo se pueden cambiar los límites de las operaciones diarias?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Los límites de operaciones diarias, tanto la cantidad de éstas, como el importe diario se modifican por el titular de la tarjeta utilizando las vías siguientes:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En la sucursal bancaria donde abrió la cuenta si desea que los cambios sean permanentes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Por la aplicación Transfermóvil, del servicio Banca MÓVIL, con una duración de 24 horas.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Pueden abrirse sin efectuar un depósito inicial y no tendrán saldo mínimo. No devengan intereses, ni se cobran comisiones por su utilización. No tienen el beneficio de la bonificación que el Banco Metropolitano S.A. aplica a otras tarjetas RED. Es un medio de pago que da acceso a las compras en los comercios habilitados para la venta de mercancías en dólares estadounidenses (USD).</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Además de utilizarse para la compra de mercancías en USD en los comercios habilitados con ese propósito, puede utilizar la tarjeta en el resto de los servicios disponibles por el Banco Metropolitano S.A. a través de los canales electrónicos de pago: compra por los terminales de puntos de venta (TPV o POS), pago de servicios públicos, comercios y oficinas comerciales, extraer dinero en efectivo por los cajeros automáticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En el caso del pago de bienes y servicios en comercios en CUP y extracciones por los cajeros automáticos, se aplica el tipo de cambio oficial vigente.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No. Las tarjetas magnéticas RED emitidas por el Banco Metropolitano S.A. son válidas exclusivamente para operaciones en el territorio nacional.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Sí. Puede asociar la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca, para su autenticación en los canales electrónicos de cobros y pagos.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Las cuentas en USD habilitadas para las compras minoristas solo se pueden abrir en esta moneda o existe también la apertura en Euros?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Las cuentas en USD habilitadas para las compras minoristas solo se pueden abrir en esta moneda o existe también la apertura en Euros?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las cuentas se denominan en USD y se pueden efectuar depósitos en euros u otra de las monedas extranjeras (monedas libremente convertibles) que se aceptan en el país, tales como: libras esterlinas, dólares canadienses, francos suizos, pesos mexicanos, coronas danesas, coronas noruegas, coronas suecas y yenes japoneses.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-10be9dbd\",\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"20px\",\"right\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"33.34\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-10be9dbd\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:image {\"id\":830,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-circle-mask is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-style-circle-mask is-style-rounded\"><img src=\"http://localhost/banco-actual/wp-content/uploads/2024/05/b-corporativa.jpg\" alt=\"\" class=\"wp-image-830\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\",\"tag\":\"h3\",\"align\":\"center\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-dcb009c0\">FAQs</h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-c9309dda\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-c9309dda\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-c9309dda\">Atención a clientes</span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8125decd\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"16px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-8125decd\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8125decd\"><strong><strong>7868-3535</strong> / <strong>7866-0606</strong></strong></span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/button-group {\"id\":\"wp-block-themeisle-blocks-button-group-b10d43a4\",\"align\":\"center\",\"spacing\":0,\"paddingTopBottom\":10,\"paddingLeftRight\":20,\"fontSize\":13} -->\n<div id=\"wp-block-themeisle-blocks-button-group-b10d43a4\" class=\"wp-block-themeisle-blocks-button-group wp-block-buttons align-center\"><!-- wp:themeisle-blocks/button {\"id\":\"wp-block-themeisle-blocks-button-f5de91a7\",\"color\":\"\",\"background\":\"var(\\u002d\\u002dnv-primary-accent)\",\"border\":\"\",\"hoverColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"hoverBackground\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"hoverBorder\":\"\",\"borderRadius\":0,\"boxShadowColor\":\"\",\"hoverBoxShadowColor\":\"\",\"prefix\":\"\",\"icon\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-button-f5de91a7\" class=\"wp-block-themeisle-blocks-button wp-block-button\"><a href=\"\" target=\"_self\" rel=\"noopener noreferrer\" class=\"wp-block-button__link\"><span>MAS INFORMACION</span></a></div>\n<!-- /wp:themeisle-blocks/button --></div>\n<!-- /wp:themeisle-blocks/button-group --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Preguntas Frecuentes', '', 'inherit', 'closed', 'closed', '', '1616-revision-v1', '', '', '2024-05-24 16:20:48', '2024-05-24 16:20:48', '', 1616, 'http://localhost/banco-actual/?p=1664', 0, 'revision', '', 0);
INSERT INTO `banmetx_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1666, 1, '2024-05-24 16:21:56', '2024-05-24 16:21:56', '<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\",\"columns\":2,\"layout\":\"twoOne\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-6cbb0867\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-twoOne-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-78c641ed\",\"padding\":{\"top\":\"40px\",\"bottom\":\"0px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"66.66\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-78c641ed\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-ce95b243\",\"tag\":\"span\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"fontSize\":\"14px\",\"letterSpacing\":4,\"marginBottomMobile\":15,\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-ce95b243\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-ce95b243\">¿<strong>QUÉ NECESITAS CONOCER?</strong> </span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\",\"alignMobile\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":50,\"marginBottomMobile\":45,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-8c6e4149\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8c6e4149\">Preguntas Frecuentes</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-8dbcc3ca\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8dbcc3ca has-light-bg\"><strong><strong>Transferencias bancarias desde el exterior</strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-26dc5bab\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-26dc5bab\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es el código SWIFT del Banco Metropolitano para realizar una transferencia de dinero hacia Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El código que utiliza es el SWIFT: BMNBCUHH. No utiliza los códigos BIC o IBAN.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuál es la comisión por transferencia que cobra el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La comisión es 0,5 %. Si el dinero es a depositar en una cuenta en el banco: mínimo 5,00 CUC – máximo 100,00 CUC. Si es a cobrar en efectivo: mínimo 6,00 CUC – máximo 300,00 CUC.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué comisión cobra el Banco por las transacciones a través de los cajeros automáticos (ATMs)?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El Banco no cobra comisión por estas transacciones.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles tarjetas pueden operar en los cajeros automáticos (ATM) o terminales de puntos de venta (TPV) en Cuba?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>VISA Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>MASTERCARD Internacional.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>VISA y MASTERCARD International NO PERSONALIZADAS.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AMERICAN INTERNATIONAL SERVICE (AIS).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>AIS – RIA.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>TRAN$CARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>CABAL.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>UNIONPAY.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>OCEANCARD.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>BANCEL (BFI).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Dónde opera el Banco Metropolitano?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Dónde opera el Banco Metropolitano?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Operamos en la capital del país, es decir, La Habana.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué debe conocer una persona para enviar una transferencia bancaria?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué debe conocer una persona para enviar una transferencia bancaria?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Para enviar la transferencia bancaria o remesa de dinero a Cuba, el interesado debe dirigirse a la sucursal bancaria más cercana de la ciudad o localidad donde se encuentre, solicitando el envío a través de uno de los <a href=\"http://www.banco-metropolitano.com.cu/bancos-corresponsales/\">bancos corresponsales</a> del <strong>Banco Metropolitano</strong> que se informan en la <strong>Web oficial</strong> o en la aplicación <strong>Banmet APK</strong>. <strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Datos necesarios:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre:</strong> Banco Metropolitano S.A.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT:</strong> BMNBCUHH. No utilizamos códigos BIC o IBAN.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de la cuenta bancaria o de la tarjeta magnética.</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Si no posee cuenta en nuestro banco:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Nombre (s) y Apellidos: </strong>como aparecen en su documento de identidad personal (carné de identidad o pasaporte).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dirección de residencia:</strong> calle o avenida, número de la casa o apartamento, entre calles, reparto o localidad, código postal, municipio, provincia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Número de identidad personal:</strong> carné de identidad o pasaporte.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teléfono</strong>: donde se pueda localizar al beneficiario de la transferencia.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código SWIFT del Banco Metropolitano:</strong> BMNBCUHH.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Código </strong><strong><a href=\"http://www.banco-metropolitano.com.cu/directorio-red-de-sucursales/\">de la sucursal</a></strong>: donde desea cobrar la transferencia.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Para enviar la transferencia bancaria o remesa de dinero a Cuba:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"start\":1} -->\n<ol start=\"1\"><!-- wp:list-item -->\n<li>Al enviar la transferencia a beneficiarios residentes en La Habana, deberá especificar al banco ordenante que su interés es enviar el dinero a través del <strong>Banco Metropolitano, S.A.</strong> De utilizarse otros bancos comerciales, se incrementan los gastos por comisiones.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También gestionamos transferencias hacia el resto del país.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Importante:</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Antes de ordenar la transferencia en el banco emisor, se debe revisar detalladamente todos los datos del beneficiario en Cuba, para evitar demoras o molestias. </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Las transferencias bancarias o remesas de dinero pueden enviarse para depositarse en cuentas en CUP (al tipo de cambio vigente) o en USD. También a cuentas en USD con respaldo en monedas libremente convertibles (MLC), habilitadas para las compras de bienes y servicios en establecimientos comerciales en esa moneda.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>También pueden cobrarse en efectivo en la sucursal bancaria que elija el beneficiario.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Si el beneficiario tiene una cuenta en el <strong>Banco Metropolitano, S.A.</strong> se le cobrarán comisiones más económicas, aunque no es necesaria para recibir dinero desde otro país.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contamos con sucursales en los 15 municipios de la capital.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>El beneficiario puede cobrar el dinero en Euros, en efectivo, si la transferencia está denominada en esa moneda originalmente.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿A quién reclamar en caso de error en una transferencia?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿A quién reclamar en caso de error en una transferencia?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>La persona que envía el dinero debe acudir al banco donde ordenó la transferencia y enmendar el error de los datos del beneficiario en Cuba. Como corresponde en los procedimientos bancarios, es el banco emisor quien enviará la modificación del mensaje con los arreglos realizados. O sea, la solicitud de modificación se realizará de Banco a Banco.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo solicitar el envío de una transferencia a través del Banco Metropolitano, si en mi país no existen bancos corresponsales?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Debe dirigirse a su sucursal bancaria y solicitar se realice la transferencia a través de uno de nuestros bancos corresponsales que aparecen publicados en este sitio Web.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿El beneficiario de una transferencia bancaria puede cobrar el dinero en Euro?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Puede recibir la transferencia en Euro, para cobrar en efectivo, si está denominada en esa moneda y haya disponibilidad en la sucursal cuando el beneficiario acuda a cobrar la remesa. Si la transferencia se ordena a una cuenta de ahorro, esta se deposita en pesos cubanos (CUP) o dólares estadounidenses (USD) con respaldo en moneda libremente convertible (MLC), según el tipo corresponda.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-dark-bg)\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"className\":\"has-light-bg\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-fd0c65ac\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-fd0c65ac has-light-bg\"><strong><strong><strong>Cuentas en USD con respaldo en moneda libremente convertible (MLC)</strong></strong></strong></h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-4645f51c\",\"borderColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"padding\":{\"top\":\"24px\",\"right\":\"0px\",\"bottom\":\"16px\",\"left\":\"0px\"},\"alwaysOpen\":false,\"className\":\" is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-4645f51c\" class=\"wp-block-themeisle-blocks-accordion exclusive  is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Dónde se pueden abrir las cuentas bancarias en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>En la sucursal bancaria de su preferencia.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Quiénes podrán abrir cuentas bancarias en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las personas naturales residentes permanentes en el territorio nacional, solo con la presentación de su carné de identidad.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>¿Con qué saldo se puede abrir una cuenta en USD con respaldo en MLC?</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No se exige un saldo mínimo, es decir, pueden abrirse con saldo cero.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuántas operaciones puedo realizar diariamente con la tarjeta magnética?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>El importe y cantidad de operaciones por día de la cuenta asociada a la tarjeta magnética, la puede definir el cliente en el momento de abrir la cuenta. En los casos en que no se precisa por el solicitante, los bancos la definen por oficio como medida de seguridad en caso de pérdida de su tarjeta. Este límite puede ser cambiado en cualquier momento por el titular de la tarjeta.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cómo se pueden cambiar los límites de las operaciones diarias?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cómo se pueden cambiar los límites de las operaciones diarias?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Los límites de operaciones diarias, tanto la cantidad de éstas, como el importe diario se modifican por el titular de la tarjeta utilizando las vías siguientes:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En la sucursal bancaria donde abrió la cuenta si desea que los cambios sean permanentes.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Por la aplicación Transfermóvil, del servicio Banca MÓVIL, con una duración de 24 horas.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Cuáles son las características fundamentales de las cuentas en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Pueden abrirse sin efectuar un depósito inicial y no tendrán saldo mínimo. No devengan intereses, ni se cobran comisiones por su utilización. No tienen el beneficio de la bonificación que el Banco Metropolitano S.A. aplica a otras tarjetas RED. Es un medio de pago que da acceso a las compras en los comercios habilitados para la venta de mercancías en dólares estadounidenses (USD).</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Qué ventajas adicionales me ofrece la tarjeta magnética asociada a una cuenta en USD con respaldo en MLC?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Además de utilizarse para la compra de mercancías en USD en los comercios habilitados con ese propósito, puede utilizar la tarjeta en el resto de los servicios disponibles por el Banco Metropolitano S.A. a través de los canales electrónicos de pago: compra por los terminales de puntos de venta (TPV o POS), pago de servicios públicos, comercios y oficinas comerciales, extraer dinero en efectivo por los cajeros automáticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En el caso del pago de bienes y servicios en comercios en CUP y extracciones por los cajeros automáticos, se aplica el tipo de cambio oficial vigente.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Con la cuenta en USD con respaldo en MLC se podrán realizar pagos en el exterior?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>No. Las tarjetas magnéticas RED emitidas por el Banco Metropolitano S.A. son válidas exclusivamente para operaciones en el territorio nacional.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Podrá asociarse la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca para ser operada a través del servicio de Banca Móvil por las pasarelas electrónicas de pago Transfermóvil, EnZona y Metropolitano en LÍNEA?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Sí. Puede asociar la cuenta en USD con respaldo en MLC a la tarjeta de Telebanca, para su autenticación en los canales electrónicos de cobros y pagos.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿Las cuentas en USD habilitadas para las compras minoristas solo se pueden abrir en esta moneda o existe también la apertura en Euros?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿Las cuentas en USD habilitadas para las compras minoristas solo se pueden abrir en esta moneda o existe también la apertura en Euros?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las cuentas se denominan en USD y se pueden efectuar depósitos en euros u otra de las monedas extranjeras (monedas libremente convertibles) que se aceptan en el país, tales como: libras esterlinas, dólares canadienses, francos suizos, pesos mexicanos, coronas danesas, coronas noruegas, coronas suecas y yenes japoneses.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item -->\n\n<!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e¿De las cuentas en USD con respaldo en MLC se pueden hacer extracciones en las sucursales bancarias? ¿Cuál es el límite y en cuánto tiempo puedo disponer de ese efectivo?\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong>¿De las cuentas en USD con respaldo en MLC se pueden hacer extracciones en las sucursales bancarias? ¿Cuál es el límite y en cuánto tiempo puedo disponer de ese efectivo?</strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Sí. Se pueden realizar extracciones de USD en efectivo de estas cuentas. El banco no establece límites para las extracciones, la cantidad a extraer dependerá del saldo existente en su cuenta y la disponibilidad de la moneda en el momento de solicitar la operación. No obstante, el banco siempre dará respuesta a la solicitud en el menor plazo posible. Los bancos garantizan a los clientes los saldos de las cuentas abiertas.</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-10be9dbd\",\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\",\"right\":\"40px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"20px\",\"right\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"4px\",\"right\":\"4px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"33.34\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-10be9dbd\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:image {\"id\":830,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-circle-mask is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-style-circle-mask is-style-rounded\"><img src=\"http://localhost/banco-actual/wp-content/uploads/2024/05/b-corporativa.jpg\" alt=\"\" class=\"wp-image-830\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\",\"tag\":\"h3\",\"align\":\"center\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-dcb009c0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-dcb009c0\">FAQs</h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-c9309dda\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-c9309dda\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-c9309dda\">Atención a clientes</span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-8125decd\",\"tag\":\"span\",\"align\":\"center\",\"fontSize\":\"14px\",\"margin\":{\"top\":\"0px\",\"bottom\":\"16px\"},\"className\":\"\"} -->\n<span id=\"wp-block-themeisle-blocks-advanced-heading-8125decd\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-8125decd\"><strong><strong>7868-3535</strong> / <strong>7866-0606</strong></strong></span>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/button-group {\"id\":\"wp-block-themeisle-blocks-button-group-b10d43a4\",\"align\":\"center\",\"spacing\":0,\"paddingTopBottom\":10,\"paddingLeftRight\":20,\"fontSize\":13} -->\n<div id=\"wp-block-themeisle-blocks-button-group-b10d43a4\" class=\"wp-block-themeisle-blocks-button-group wp-block-buttons align-center\"><!-- wp:themeisle-blocks/button {\"id\":\"wp-block-themeisle-blocks-button-f5de91a7\",\"color\":\"\",\"background\":\"var(\\u002d\\u002dnv-primary-accent)\",\"border\":\"\",\"hoverColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"hoverBackground\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"hoverBorder\":\"\",\"borderRadius\":0,\"boxShadowColor\":\"\",\"hoverBoxShadowColor\":\"\",\"prefix\":\"\",\"icon\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-button-f5de91a7\" class=\"wp-block-themeisle-blocks-button wp-block-button\"><a href=\"\" target=\"_self\" rel=\"noopener noreferrer\" class=\"wp-block-button__link\"><span>MAS INFORMACION</span></a></div>\n<!-- /wp:themeisle-blocks/button --></div>\n<!-- /wp:themeisle-blocks/button-group --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Preguntas Frecuentes', '', 'inherit', 'closed', 'closed', '', '1616-revision-v1', '', '', '2024-05-24 16:21:56', '2024-05-24 16:21:56', '', 1616, 'http://localhost/banco-actual/?p=1666', 0, 'revision', '', 0);
