(1703, 1, '2024-05-27 20:51:27', '2024-05-27 20:51:27', '<!-- wp:navigation-link {\"label\":\"Derechos y deberes de los clientes\",\"type\":\"portafolio\",\"id\":1297,\"url\":\"http://localhost/banco-actual/portafolio/derechos-y-deberes-de-los-clientes/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"La debida Diligencia\",\"type\":\"page\",\"id\":1302,\"url\":\"http://localhost/banco-actual/medidas-practicas-y-procesos-para-prevenir-el-uso-indebido-de-los-servicios-bancarios/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Medidas de seguridad en el uso de su tarjeta magnética RED\",\"type\":\"page\",\"id\":819,\"url\":\"http://localhost/banco-actual/medidas-de-seguridad-en-el-uso-de-su-tarjeta-magnetica-red/\",\"kind\":\"post-type\",\"isTopLevelLink\":true} /-->', 'De interés', '', 'publish', 'closed', 'closed', '', 'de-interes', '', '', '2024-05-27 20:51:27', '2024-05-27 20:51:27', '', 0, 'http://localhost/banco-actual/?p=1703', 0, 'wp_navigation', '', 0),
