l,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Bancarización</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Información de Interés</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-97ddd9f7\",\"columns\":1,\"layout\":\"equal\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-97ddd9f7\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-1791aae7\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-1791aae7\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p><em>¿Qué es la bancarización?</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se define como <strong>el uso de los medios de pago del sistema bancario y financiero, por parte de las personas naturales o empresas estatales, mipymes, cooperativas, trabajadores independientes y otras formas de gestión no estatal, para realizar operaciones comerciales</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Le permite el acceso a los servicios bancarios y financieros, tales como: pagos de bienes y servicios, ahorro de los recursos financieros temporalmente libres y otorgamiento de créditos a las personas naturales o jurídicas que, aunque pueden obtenerse del modo presencial en las sucursales bancarias, se promueve cada vez más, el uso de los canales electrónicos de cobros y pagos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>¿Cuál es el objetivo de la Bancarización?</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es, principalmente, el de normalizar las operaciones económicas, con el fin de mejorar los sistemas de fiscalización y la detección del fraude tributario.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Entre sus ventajas se encuentran, hacer uso del efectivo en menor cantidad, la mejora de la distribución de los ingresos, disminuyendo el costo a los segmentos de menos recursos financieros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>¿Qué es bancarizar a una persona?</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Una persona está bancarizada <strong>cuando usa de forma activa uno o más productos </strong>o<strong> servicios bancarios</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>¿Cuáles son los medios de pago?</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Son las diferentes formas con las cuales se puede pagar un producto o servicio adquirido. Entre ellos, están las <strong>tarjetas de débito y crédito, el dinero en efectivo, cheques bancarios, pagos instantáneos (en línea por código QR o por terminal de punto de venta), entre otros</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Bancarización de las transacciones</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Se refiere al <strong>grado de utilización</strong>, mediante el empleo de los canales electrónicos de cobros y pagos de manera legal, en la realización de transacciones financieras, en lugar de utilizar dinero en efectivo, a través de las instituciones bancarias y financieras formales.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Bancarización', '', 'publish', 'closed', 'closed', '', 'bancarizacion', '', '', '2024-05-28 03:19:09', '2024-05-28 03:19:09', '', 0, 'http://localhost/banco-actual/?page_id=1727', 0, 'page', '', 0),
