nced-heading-5677dff3\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-5677dff3\">Banca Móvil </h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\">Le garantiza agilidad, comodidad y seguridad en las transacciones,con el uso de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-5376f978\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"33.33\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-5376f978\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/font-awesome-icons {\"id\":\"wp-block-themeisle-blocks-font-awesome-icons-a92e1471\",\"align\":\"left\",\"prefix\":\"fas\",\"icon\":\"plug\",\"fontSize\":28,\"padding\":10,\"margin\":0,\"textColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"borderColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"borderSize\":3,\"borderRadius\":100} -->\n<div id=\"wp-block-themeisle-blocks-font-awesome-icons-a92e1471\" class=\"wp-block-themeisle-blocks