-- wp:paragraph -->\n<p>Oficina Central</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>APS/…</p>\n<!-- /wp:paragraph -->', 'Estrena Banco Metropolitano nuevo canal de comunicación', '', 'inherit', 'closed', 'closed', '', '1821-revision-v1', '', '', '2024-05-28 20:36:15', '2024-05-28 20:36:15', '', 1821, 'http://localhost/banco-actual/?p=1822', 0, 'revision', '', 0),
