. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|nv-site-bg\"}}}},\"textColor\":\"nv-site-bg\"} -->\n<p class=\"has-nv-site-bg-color has-text-color has-link-color\">El <strong>servicio automático</strong>&nbsp;de <strong>voz interactiva</strong>, está activo  las <strong>24 horas</strong>,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"40px\",\"width\":\"0px\",\"style\":{\"layout\":{}}} -->\n<div style=\"height:40px;width:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:themeisle-blocks/button-group {\"id\":\"wp-block-themeisle-blocks-button-group-95351c8e\",\"align\":\"center\",\"paddingTopBottom\":15,\"paddingLeftRight\":50,\"fontSize\":16,\"fontFamily\":\"Montserrat\",\"fontVariant\":\"regular\",\"textTransform\":\"none\",\"fontStyle\":\"normal\"} -->\n<div id=\"wp-block-themeisle-blocks-button-group-95351c8e\" class=\"wp-block-themeisle-blocks-button-group wp-block-buttons align-center\"><!-- wp:themeisle-blocks/button {\"id\":\"wp-block-themeisle-blocks-button-b91a0c77\",\"color\":\"#ffffff\",\"background\":\"var(\\u002d\\u002dnv-primary-accent)\",\"border\":\"var(\\u002d\\u002dnv-primary-accent)\",\"hoverColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"hoverBackground\":\"var(\\u002d\\u002dnv-primary-accent)\",\"hoverBorder\":\"var(\\u002d\\u002dnv-primary-accent)\",\"borderSize\":3,\"borderRadius\":0,\"boxShadowColor\":\"\",\"hoverBoxShadowColor\":\"\",\"prefix\":\"\",\"icon\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-button-b91a0c77\" class=\"wp-block-themeisle-blocks-button wp-block-button\"><a href=\"http://localhost/banco-actual/portafolio/telebanca/\" target=\"_self\" rel=\"noopener noreferrer\" class=\"wp-block-button__link\"><span>Consúltelos</span></a></div>\n<!-- /wp:themeisle-blocks/button --></div>\n<!-- /wp:themeisle-blocks/button-group --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:t