"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":\"40px\",\"right\":null},\"marginMobile\":{\"top\":\"-50px\",\"left\":\"10px\",\"right\":\"10px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadow\":true,\"boxShadowColor\":\"#121212\",\"boxShadowColorOpacity\":8,\"boxShadowBlur\":24,\"boxShadowSpread\":5,\"columnWidth\":\"70.26\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-ea20ba02\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-d67790d0\",\"tag\":\"h1\",\"margin\":{\"top\":\"0px\",\"bottom\":\"8px\"},\"className\":\"\"} -->\n<h1 id=\"wp-block-themeisle-blocks-advanced-heading-d67790d0\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-d67790d0\">Quiénes Somos</h1>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":19}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-neve-text-color-color has-text-color\" style=\"font-size:19px\">Su Banco en la Capital</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-c28105de\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"30.00\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-c28105de\" class=\"wp-block-themeisle-blocks-advanced-column\"></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-849ddfc1\",\"columns\":2,\"layout\":\"oneTwo\",\"layoutTablet\":\"oneTwo\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"69px\",\"bottom\":\"80px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"top\":null,\"bottom\":null},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-849ddfc1\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-oneTwo-layout has-tablet-oneTwo-layout has-mobile-collapsedRows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-169e5640\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"24.98\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-169e5640\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-7a662a6f\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-7a662a6f\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-7a662a6f\">Desde 1996 a su servicio.</h2>\n<!-- /wp:themeisle-blocks/advanced-heading --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-1ed7e0a8\",\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"45px\",\"right\":\"60px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"20px\",\"bottom\":\"40px\",\"left\":\"0px\",\"right\":\"0px\"},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"74.90\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-1ed7e0a8\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:paragraph -->\n<p>El&nbsp;<strong>Banco Metropolitano S.A.</strong>&nbsp;es un banco comercial con presencia sólo en la capital cubana. Su objeto social es el de dedicarse al negocio de la banca, lo cual le permite realizar cualquier acción de intermediación financiera.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Inició sus operaciones en el año 1996, con una sucursal en La Habana especializada en brindar servicios bancarios sólo a misiones diplomáticas y a personas naturales y jurídicas extranjeras residentes en el país.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Por acuerdo del&nbsp;<strong>Banco Central de Cuba</strong>&nbsp;(BCC), a partir del 2004 amplía su objeto social, así como los segmentos de clientes y la gama de productos y servicios, al adquirir 30 oficinas del&nbsp;<strong>Banco de Crédito y Comercio</strong>(BANDEC) y más de 50 del&nbsp;<strong>Banco Popular de Ahorro</strong>&nbsp;(BPA), ubicadas todas en La Habana, quedando representado en cada uno de los municipios de la provincia.<br>La estructura del banco cuenta con una oficina central como nivel de dirección estratégica y metodológica, cuatro direcciones territoriales como nivel de supervisión y control, a las que se subordinan las sucursales y cajas de ahorro donde se brindan los servicios a los clientes y conforman el nivel operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Actualmente la misión del Banco Metropolitano es:&nbsp;<strong><em>“Brindar servicios y asesoría a nuestros clientes con la calidad requerida, cumpliendo todas las normativas legales y bancarias”</em></strong><em>.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-813d4f77\",\"columns\":1,\"layout\":\"equal\",\"padding\":{\"top\":\"80px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"bottom\":\"40px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{\"bottom\":\"0px\"},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-813d4f77\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-02e447ca\",\"padding\":{\"top\":\"20px\",\"bottom\":\"0px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":null,\"bottom\":\"0px\",\"left\":null,\"right\":null},\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-02e447ca\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-4cf0d89f\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-text-color)\",\"marginBottom\":20,\"marginBottomMobile\":11,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-4cf0d89f\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-4cf0d89f\"> Los canales de distribución&nbsp;</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":21}},\"textColor\":\"neve-text-color\"} -->\n<p class=\"has-text-align-center has-neve-text-color-color has-text-color\" style=\"font-size:21px\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator {\"opacity\":\"css\",\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-css-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Los canales de distribución&nbsp; están conformados por&nbsp;<strong>94 sucursales</strong>&nbsp;y&nbsp;<strong>27 cajas de ahorro</strong>&nbsp;(con un total de 653 cubículos de caja) que ofrecen más de&nbsp;<strong>30 productos y servicios</strong>&nbsp;dirigidos a personas naturales y jurídicas, los trabajadores por cuenta propia, las cooperativas no agropecuarias, los agricultores pequeños y otras formas de gestión no estatal.<br>Dispone de&nbsp;<strong>526 cajeros automáticos</strong>&nbsp;(ATM), de ellos, ocho son&nbsp;<strong>cajeros recicladores</strong>&nbsp;que permiten realizar depósitos y extracciones de efectivo en Pesos cubanos (CUP) y seis&nbsp;<strong>cajeros multifunción</strong>&nbsp;que permiten realizar operaciones de cambio de monedas extranjeras. Existen&nbsp;<strong>252 equipos desplazados</strong>&nbsp;que son atendidos bajo contratación con SEPSA y&nbsp;<strong>274 ubicados en las sucursales</strong>. Cuenta también con un servicio de&nbsp;<strong>Banca Telefónica</strong>&nbsp;(Telebanca),&nbsp;<strong>Banca Móvil</strong>&nbsp;y&nbsp;<strong>Banca Remota</strong>&nbsp;(Metropolitano en Línea), así como&nbsp;<strong>98 Terminales de Puntos de Ventas</strong>&nbsp;(TPV) en las sucursales y cajas de ahorro.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Las operaciones del banco se registran en tiempo real por vía informatizada en tres centros contables interconectados entre sí, soportados en enlaces de transmisión de datos con líneas de la&nbsp;<strong>Empresa de Telecomunicaciones de Cuba S.A.</strong>&nbsp;(ETECSA).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">El&nbsp;<strong>Banco Metropolitano S.A.</strong>&nbsp;tiene relaciones de corresponsalía con otros&nbsp;<strong>bancos en el exterior</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Si desea conocer más sobre nuestra institución, nuestros principales productos y servicios, le invitamos a explorar nuestro sitio web.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:image {\"id\":466,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"boxShadowColor\":\"#e3dede\",\"boxShadowColorOpacity\":37,\"boxShadowBlur\":34,\"boxShadowHorizontal\":-100,\"boxShadowVertical\":-64} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/banco-actual/wp-content/uploads/2023/11/banco-metropolitano.jpg\" alt=\"\" class=\"wp-image-466\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-c6367fcb\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"20px\",\"right\":\"20px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"20px\"},\"marginTablet\":{\"top\":null,\"bottom\":null},\"marginMobile\":{},\"columnsWidth\":1100,\"horizontalAlign\":\"center\",\"backgroundColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"backgroundOverlayPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"align\":\"full\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-c6367fcb\" class=\"wp-block-themeisle-blocks-advanced-columns alignfull has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset has-light-bg\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-0eaf178a\",\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"20px\",\"right\":\"20px\"},\"paddingTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"paddingMobile\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"10px\",\"right\":\"10px\"},\"margin\":{\"top\":\"20px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"marginTablet\":{\"top\":null,\"bottom\":null,\"left\":null,\"right\":null},\"marginMobile\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"backgroundPosition\":{\"x\":\"0.00\",\"y\":\"0.00\"},\"border\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"0px\",\"right\":\"0px\"},\"columnWidth\":\"50\",\"className\":\"has-light-bg\",\"hasCustomCSS\":true} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-0eaf178a\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-24702efc\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"marginBottom\":12,\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-24702efc\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-24702efc\">Tipos de Cambio</h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/icon-list {\"id\":\"wp-block-themeisle-blocks-icon-list-e4f8ad2b\",\"defaultContentColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"defaultIconColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"hideLabels\":false,\"hasDivider\":false,\"className\":\"is-style-horizontal\"} -->\n<div id=\"wp-block-themeisle-blocks-icon-list-e4f8ad2b\" class=\"wp-block-th