tom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"borderRadius\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"0px\",\"right\":\"0px\"},\"boxShadowColor\":\"#176618\",\"boxShadowColorOpacity\":30,\"boxShadowSpread\":-100,\"boxShadowVertical\":52,\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-45099559\" class=\"wp-block-themeisle-blocks-advanced-column\"><div class=\"wp-block-themeisle-blocks-advanced-column-overlay\"></div><!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-05b5ec91\",\"tag\":\"h5\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"marginBottom\":12,\"className\":\"\"} -->\n<h5 id=\"wp-block-themeisle-blocks-advanced-heading-05b5ec91\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-05b5ec91\"><strong>HAGA SUS CUENTAS</strong></h5>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-1329a4f9\",\"tag\":\"h3\",\"align\":\"center\",\"headingColor\":\"var(\\u002d\\u002dnv-text-dark-bg)\",\"marginBottom\":12,\"className\":\"\"} -->\n<h3 id=\"wp-block-themeisle-blocks-advanced-heading-1329a4f9\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-1329a4f9\">SIMULADORES</h3>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:themeisle-blocks/button-group {\"id\":\"wp-block-themeisle-blocks-button-group-0463ce1b\",\"align\":{\"desktop\":\"center\"},\"paddingTopBottom\":\"10px\",\"paddingLeftRight\":\"10px\",\"isSynced\":[]} -->\n<div id=\"wp-block-themeisle-blocks-button-group-0463ce1b\" class=\"wp-block-themeisle-blocks-button-group wp-block-buttons align-center-desktop\"><!-- wp:themeisle-blocks/b