ttonTextColor\":\"var(\\u002d\\u002dnv-site-bg)\",\"buttonBorderColor\":\"var(\\u002d\\u002dnv-primary-accent)\"} /--></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"20px\",\"right\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-f15ecf3f\" class=\"wp-block-themeisle-blocks-advanced-columns has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-a910e476\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-a910e476\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-287a5027\",\"FAQSchema\":false,\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"contentBackground\":\"var(\\u002d\\u002dnv-light-bg)\",\"borderColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"borderWidth\":\"2px\",\"textTransform\":\"capitalize\",\"alwaysOpen\":false,\"iconFirst\":true,\"activeTitleColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"icon\":{\"name\":\"minus-circle\",\"prefix\":\"fas\"},\"openItemIcon\":{\"name\":\"plus-circle\",\"prefix\":\"fas\"},\"className\":\"has-light-content-bg is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-287a5027\" data-has-schema=\"false\" class=\"wp-block-themeisle-blocks-accordion exclusive icon-first has-icon has-open-icon has-light-content-bg is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"Telebanca\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div>Telebanca</div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>A través del <strong>centro de llamadas</strong> pueden ser atendidas las solicitudes de información general de los productos o servicios que ofrece el <strong>Banco Metropolitano</strong>, gestionar servicios bancarios, pagar la electricidad, la telefonía fija, el agua, impuestos, pagos de multas y contravenciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es el canal por excelencia para atender y gestionar las inquietudes o reclamaciones relacionadas con los servicios asociados a la banca electrónica y los canales de pagos digitales con el empleo de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7868-3535, 7866-0606</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: clientes@banmet.cu</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-dcb9b3e7\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-dcb9b3e7\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-61866666\",\"FAQSchema\":false,\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"contentBackground\":\"var(\\u002d\\u002dnv-light-bg)\",\"borderColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"borderWidth\":\"2px\",\"textTransform\":\"capitalize\",\"alwaysOpen\":false,\"iconFirst\":true,\"activeTitleColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"icon\":{\"name\":\"minus-circle\",\"prefix\":\"fas\"},\"openItemIcon\":{\"name\":\"plus-circle\",\"prefix\":\"fas\"},\"className\":\"has-light-content-bg is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-61866666\" data-has-schema=\"false\" class=\"wp-block-themeisle-blocks-accordion exclusive icon-first has-icon has-open-icon has-light-content-bg is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003eAtención a Clientes sobre quejas, sugerencias y reclamaciones\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong>Atención a Clientes sobre quejas, sugerencias y reclamaciones</strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Las inquietudes, quejas, sugerencias y reclamaciones son gestionadas por especialistas del departamento de <strong>Atención a Clientes </strong> en calle Cuba 225 esquina a O’ Reilly, La Habana Vieja, La Habana, Cuba.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7801-3418 y 7801-3333 extensiones 1121 y 1124</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: atencionalapoblacion@banmet.cu&nbsp;</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-db7f3778\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"20px\",\"right\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-db7f3778\" class=\"wp-block-themeisle-blocks-advanced-columns has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-84c2aa08\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-84c2aa08\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-3c77aaf8\",\"FAQSchema\":false,\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"contentBackground\":\"var(\\u002d\\u002dnv-light-bg)\",\"borderColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"borderWidth\":\"2px\",\"textTransform\":\"capitalize\",\"alwaysOpen\":false,\"iconFirst\":true,\"activeTitleColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"icon\":{\"name\":\"minus-circle\",\"prefix\":\"fas\"},\"openItemIcon\":{\"name\":\"plus-circle\",\"prefix\":\"fas\"},\"className\":\"has-light-content-bg is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-3c77aaf8\" data-has-schema=\"false\" class=\"wp-block-themeisle-blocks-accordion exclusive icon-first has-icon has-open-icon has-light-content-bg is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003eAtención a clientes del segmento de personas jurídicas y formas de gestión no estatal\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong><strong>Atención a clientes del segmento de personas jurídicas y formas de gestión no estatal</strong></strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p><strong><strong><strong>Para empresarios, mipymes, trabajadores por cuenta propia, cooperativas no agropecuarias, otras formas de gestión no estatal</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:negocios@banmet.cu\">negocios@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para trabajadores por cuenta propia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:tcp@banmet.cu\">tcp@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para micro, pequeñas y medianas empresas (mipymes)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:mipymes@banmet.cu\">mipymes@banmet.cu</a></p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7e9ea079\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"columnWidth\":\"50\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7e9ea079\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/accordion {\"id\":\"wp-block-themeisle-blocks-accordion-56e4a6cc\",\"FAQSchema\":false,\"titleColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"contentBackground\":\"var(\\u002d\\u002dnv-light-bg)\",\"borderColor\":\"var(\\u002d\\u002dnv-secondary-accent)\",\"borderWidth\":\"2px\",\"textTransform\":\"capitalize\",\"alwaysOpen\":false,\"iconFirst\":true,\"activeTitleColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"icon\":{\"name\":\"minus-circle\",\"prefix\":\"fas\"},\"openItemIcon\":{\"name\":\"plus-circle\",\"prefix\":\"fas\"},\"className\":\"has-light-content-bg is-style-default\"} -->\n<div id=\"wp-block-themeisle-blocks-accordion-56e4a6cc\" data-has-schema=\"false\" class=\"wp-block-themeisle-blocks-accordion exclusive icon-first has-icon has-open-icon has-light-content-bg is-style-default\"><!-- wp:themeisle-blocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003eAtención a clientes. Gestión de créditos bancarios\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<details class=\"wp-block-themeisle-blocks-accordion-item\"><summary class=\"wp-block-themeisle-blocks-accordion-item__title\"><div><strong><strong><strong><strong><strong><strong>Atención a clientes. Gestión de créditos bancarios</strong></strong></strong></strong></strong></strong></div></summary><div class=\"wp-block-themeisle-blocks-accordion-item__content\"><!-- wp:paragraph -->\n<p>Se ofrece asesoramiento, otorgamiento y seguimiento a las solicitudes en las <strong>Oficinas de Crédito</strong>. También pueden visitar las <strong>sucursales bancarias</strong> en todos los municipios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Plaza de la Revolución</strong>, calle 23 entre P y Malecón, La Rampa, Vedado</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7833-2316</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Diez de Octubre</strong>, Juan Delgado esquina a Lacret, Díez de Octubre</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7649-5215</p>\n<!-- /wp:paragraph --></div></details>\n<!-- /wp:themeisle-blocks/accordion-item --></div>\n<!-- /wp:themeisle-blocks/accordion --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->', 'Contáctenos', '', 'inherit', 'closed', 'closed', '', '744-revision-v1', '', '', '2024-05-30 21:57:47', '2024-05-30 21:57:47', '', 744, 'http://localhost/banco-actual/?p=2040', 0, 'revision', '', 0);
