el-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-43db9348\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-43db9348\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-5f5fe8aa\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-5f5fe8aa\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-09969818\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-09969818\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-09969818\"><strong><strong><strong>Atención a clientes del segmento de personas jurídicas: empresarios, mipymes, trabajadores por cuenta propia, cooperativas no agropecuarias, otras formas de gestión no estatal</strong></strong></strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Para empresarios, cooperativas, otras formas de gestión no estatal</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:negocios@banmet.cu\">negocios@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para trabajadores por cuenta propia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:tcp@banmet.cu\">tcp@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para micro, pequeñas y medianas empresas (mipymes)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:mipymes@banmet.cu\">mipymes@banmet.cu</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-77331213\",\"columns\":1,\"layout\":\"equal\",\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-77331213\" class=\"wp-block-themeisle-blocks-advanced-columns has-1-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-equal-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-3d2c1928\",\"columnWidth\":\"100\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-3d2c1928\" class=\"wp-block-themeisle-blocks-advanced-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-455bc1a2\",\"className\":\"\"} -->\n<h2 id=\"wp-block-themeisle-blocks-advanced-heading-455bc1a2\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-455bc1a2\"><strong><strong><strong><strong>Atención a clientes. Gestión de créditos bancarios</strong></strong></strong></strong></h2>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Se ofrece asesoramiento, otorgamiento y seguimiento a las solicitudes en las <strong>Oficinas de Crédito</strong>. También pueden visitar las <strong>sucursales bancarias</strong> en todos los municipios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Plaza de la Revolución</strong>, calle 23 entre P y Malecón, La Rampa, Vedado</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7833-2316</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Diez de Octubre</strong>, Juan Delgado esquina a Lacret, Díez de Octubre</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7649-5215</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->', 'Contáctenos', '', 'inherit', 'closed', 'closed', '', '744-revision-v1', '', '', '2024-05-30 21:53:42', '2024-05-30 21:53:42', '', 744, 'http://localhost/banco-actual/?p=2037', 0, 'revision', '', 0);
