hemeisle-blocks-advanced-heading-2d5938a2\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-2d5938a2\">Telebanca</h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>A través del <strong>centro de llamadas</strong> pueden ser atendidas las solicitudes de información general de los productos o servicios que ofrece el <strong>Banco Metropolitano</strong>, gestionar servicios bancarios, pagar la electricidad, la telefonía fija, el agua, impuestos, pagos de multas y contravenciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es el canal por excelencia para atender y gestionar las inquietudes o reclamaciones relacionadas con los servicios asociados a la banca electrónica y los canales de pagos digitales con el empleo de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7868-3535, 7866-0606</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: clientes@banmet.cu</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-dcb9b3e7\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"border\":{\"top\":\"2px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"borderColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"columnWidth\":\"50\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-dcb9b3e7\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-b6ecc1a9\",\"tag\":\"h4\",\"align\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-b6ecc1a9\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-b6ecc1a9\"><strong><strong>Atención a Clientes sobre quejas, sugerencias y reclamaciones</strong></strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>A través del <strong>centro de llamadas</strong> pueden ser atendidas las solicitudes de información general de los productos o servicios que ofrece el <strong>Banco Metropolitano</strong>, gestionar servicios bancarios, pagar la electricidad, la telefonía fija, el agua, impuestos, pagos de multas y contravenciones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Es el canal por excelencia para atender y gestionar las inquietudes o reclamaciones relacionadas con los servicios asociados a la banca electrónica y los canales de pagos digitales con el empleo de las aplicaciones <strong>Transfermóvil</strong> y <strong>EnZona</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfonos</strong>: 7868-3535, 7866-0606</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: clientes@banmet.cu</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:themeisle-blocks/advanced-columns {\"id\":\"wp-block-themeisle-blocks-advanced-columns-db7f3778\",\"columns\":2,\"layout\":\"equal\",\"layoutMobile\":\"collapsedRows\",\"padding\":{\"top\":\"20px\",\"right\":\"20px\",\"bottom\":\"0px\",\"left\":\"20px\"},\"columnsWidth\":\"1100px\",\"horizontalAlign\":\"center\",\"className\":\"\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-columns-db7f3778\" class=\"wp-block-themeisle-blocks-advanced-columns has-2-columns has-desktop-equal-layout has-tablet-equal-layout has-mobile-collapsedRows-layout has-vertical-unset\"><div class=\"wp-block-themeisle-blocks-advanced-columns-overlay\"></div><div class=\"innerblocks-wrap\"><!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-84c2aa08\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"border\":{\"top\":\"2px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"borderColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"columnWidth\":\"50\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-84c2aa08\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-6709872b\",\"tag\":\"h4\",\"align\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-6709872b\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-6709872b\"><strong><strong><strong>Atención a clientes del segmento de personas jurídicas y formas de gestión no estatal</strong></strong></strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p><strong><strong><strong>Para empresarios, mipymes, trabajadores por cuenta propia, cooperativas no agropecuarias, otras formas de gestión no estatal</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:negocios@banmet.cu\">negocios@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para trabajadores por cuenta propia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:tcp@banmet.cu\">tcp@banmet.cu</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Para micro, pequeñas y medianas empresas (mipymes)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Correo-e</strong>: <a href=\"mailto:mipymes@banmet.cu\">mipymes@banmet.cu</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:themeisle-blocks/advanced-column -->\n\n<!-- wp:themeisle-blocks/advanced-column {\"id\":\"wp-block-themeisle-blocks-advanced-column-7e9ea079\",\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"},\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"20px\",\"left\":\"20px\"},\"backgroundColor\":\"var(\\u002d\\u002dnv-light-bg)\",\"border\":{\"top\":\"2px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"borderColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"columnWidth\":\"50\",\"className\":\"has-light-bg\"} -->\n<div id=\"wp-block-themeisle-blocks-advanced-column-7e9ea079\" class=\"wp-block-themeisle-blocks-advanced-column has-light-bg\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:themeisle-blocks/advanced-heading {\"id\":\"wp-block-themeisle-blocks-advanced-heading-095f0471\",\"tag\":\"h4\",\"align\":\"left\",\"headingColor\":\"var(\\u002d\\u002dnv-primary-accent)\",\"className\":\"\"} -->\n<h4 id=\"wp-block-themeisle-blocks-advanced-heading-095f0471\" class=\"wp-block-themeisle-blocks-advanced-heading wp-block-themeisle-blocks-advanced-heading-095f0471\"><strong><strong><strong><strong><strong><strong><strong><strong>Atención a clientes. Gestión de créditos bancarios</strong></strong></strong></strong></strong></strong></strong></strong></h4>\n<!-- /wp:themeisle-blocks/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Se ofrece asesoramiento, otorgamiento y seguimiento a las solicitudes en las <strong>Oficinas de Crédito</strong>. También pueden visitar las <strong>sucursales bancarias</strong> en todos los municipios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Plaza de la Revolución</strong>, calle 23 entre P y Malecón, La Rampa, Vedado</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7833-2316</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Oficina de Diez de Octubre</strong>, Juan Delgado esquina a Lacret, Díez de Octubre</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Teléfono</strong>: 7649-5215</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:themeisle-blocks/advanced-column --></div></div>\n<!-- /wp:themeisle-blocks/advanced-columns -->\n\n<!-- wp:separator {\"backgroundColor\":\"neve-link-color\"} -->\n<hr class=\"wp-block-separator has-text-color has-neve-link-color-color has-alpha-channel-opacity has-neve-link-color-background-color has-background\"/>\n<!-- /wp:separator -->', 'Contáctenos', '', 'inherit', 'closed', 'closed', '', '744-revision-v1', '', '', '2024-05-31 01:39:55', '2024-05-31 01:39:55', '', 744, 'http://localhost/banco-actual/?p=2055', 0, 'revision', '', 0);
